window.EXPL={"경제교재-01-02":{"f":"경제재는 경제학의 분석 대상이 되며, 자유재는 분석 대상에서 제외된다.","w":"자유재는 대가 없이 얻을 수 있어 경제문제가 생기지 않는다. 대가를 치러야 하는 경제재만 분석 대상이다.","c":"상","v":1},"경제교재-01-03":{"f":"매몰비용은 회수할 수 없어 기회비용이 0이므로 의사결정 때 고려하지 않는다.","w":"회계 장부에 비용으로 남아 있어도 되돌릴 수 없는 지출은 선택에 따라 달라지지 않는다. 앞으로 늘거나 줄어드는 편익과 비용만 비교한다.","c":"상","v":1},"경제교재-01-05":{"f":"기회비용은 주관적 개념이므로 두 사람이 같은 선택을 해도 기회비용은 서로 다른 것이 일반적이다.","w":"포기하는 것의 가치는 사람과 상황에 따라 다르다. 같은 사람도 상황이 바뀌면 기회비용이 달라진다.","c":"상","v":1},"경제교재-01-07":{"f":"생산가능곡선 안쪽에서 곡선 위로 옮겨가는 것은 효율성이 높아졌다는 뜻이고, 기술진보는 곡선 자체를 바깥으로 옮긴다.","w":"실업자 취업이나 유휴설비 가동으로 낭비를 없애면 곡선 위로 올라간다. 주어진 자원과 기술 자체가 바뀌어야 곡선이 이동한다.","c":"상","v":1},"경제교재-01-09":{"f":"기회비용이 일정하면 생산가능곡선은 우하향하는 직선이다.","w":"원점에 대해 오목한 곡선은 기회비용체증일 때의 모양이다. 기회비용이 체감하면 원점에 대해 볼록하다.","c":"상","v":1},"경제교재-01-12":{"f":"X재 1개의 기회비용은 Y재 2개이다.","w":"생산가능곡선 4X + 2Y = 100에서 X를 1 늘리면 Y는 4/2 = 2 줄어든다. 1/2은 Y재의 기회비용이다.","c":"상","v":1},"경제교재-01-14":{"f":"저축 증가는 개인에게는 바람직하지만 총수요를 줄여 경기침체를 더 깊게 하므로 경제 전체에는 바람직하지 않다.","w":"부분에 참인 것이 전체에 참이 아닌 구성의 오류의 예로, 절약의 역설이라 한다.","c":"상","v":1},"경제교재-01-16":{"f":"그림의 좌표에 없는 외생변수가 변하면 곡선 자체가 이동한다.","w":"좌표에 있는 독립변수가 변할 때만 곡선 위의 이동이 나타난다.","c":"상","v":1},"경제교재-02-02":{"f":"수요와 공급이 모두 증가하면 균형거래량은 반드시 증가하지만 균형가격의 변화는 알 수 없다.","w":"수요 증가는 가격을 올리고 공급 증가는 가격을 내려 두 힘이 부딪친다. 어느 쪽이 큰지는 이동폭과 기울기에 달렸다.","c":"상","v":1},"경제교재-02-04":{"f":"생산 측면에서 보완관계인 재화는 양고기 가격이 오르면 양털의 공급이 증가한다.","w":"양고기 가격이 오르면 양고기 공급량이 늘고, 함께 나오는 양털도 늘어난다. 생산 측면의 보완재는 같은 방향으로 움직인다.","c":"상","v":1},"경제교재-02-06":{"f":"마샬의 관점에서 어떤 수량에서 수요가격이 공급가격보다 높은 초과수요가격이 있으면 거래량이 증가한다.","w":"소비자가 내려는 가격이 생산자가 받으려는 가격보다 높으면 그 수량의 거래가 서로 이득이므로 거래량이 늘어난다.","c":"상","v":1},"경제교재-02-08":{"f":"생산자가 앞으로 가격이 오를 것으로 예상하면 오른 뒤에 팔려고 하므로 현재 공급이 감소한다.","w":"가격 상승이 예상되면 생산자는 판매를 미래로 미룬다. 현재 공급이 느는 경우는 가격 하락을 예상할 때다.","c":"상","v":1},"경제교재-02-09":{"f":"소비자에게 단위당 조세를 부과하면 수요곡선이 단위당 세금만큼 하방(좌측)으로 이동한다.","w":"같은 수요량에서 소비자가 낼 수 있는 가격이 세금만큼 줄어든다. 보조금을 주면 반대로 상방(우측)으로 이동한다.","c":"상","v":1},"경제교재-02-11":{"f":"가격 10에서 시장수요량은 1이다.","w":"B의 최대지불가격은 8이므로 가격 10에서 q_B = 0이다. q_A = (12 − 10)/2 = 1만 남으며, 이 구간에서는 A의 수요가 시장수요다.","c":"상","v":1},"경제교재-02-12":{"f":"수요함수가 같은 소비자가 두 배로 늘면 시장수요곡선은 가격축 절편이 그대로이고 기울기가 절반이 된다.","w":"같은 가격에서 수요량이 두 배가 되므로 수량축 절편이 두 배가 된다. 가격축 절편은 변하지 않는다.","c":"상","v":1},"경제교재-02-14":{"f":"백로효과가 있으면 시장수요곡선은 없을 때보다 더 가팔라지고 가격에 대해 더 비탄력적이 된다.","w":"가격이 내려 다른 사람 소비가 늘 것으로 예상되면 백로효과 때문에 개인 수요가 줄어 수요량이 덜 늘어난다. 편승효과는 이와 반대다.","c":"상","v":1},"경제교재-03-02":{"f":"P = 20인 점에서 수요의 가격탄력성은 2이다.","w":"P = 20에서 Q = 20이므로 탄력성은 2 × 20/20 = 2이다. 중점(P = 15)보다 가격이 높아 탄력적이다.","c":"상","v":1},"경제교재-03-03":{"f":"가격탄력성은 변화율로 재므로 가격과 수량의 단위와 무관하게 같다.","w":"단위를 바꾸면 수요곡선의 기울기가 바뀌지만 원점에서 그 점을 잇는 직선의 기울기도 함께 바뀌어 탄력성은 그대로다.","c":"상","v":1},"경제교재-03-05":{"f":"필수품과 사치품을 구분하는 기준은 수요의 소득탄력성이다.","w":"대부분의 필수품이 가격에 비탄력적이고 사치품이 탄력적인 경향은 있으나 구분 기준은 소득탄력성이 1보다 작은지 큰지다.","c":"상","v":1},"경제교재-03-07":{"f":"가격축 절편이 양수인 직선 공급곡선에서 원점에서 멀어질수록 공급의 가격탄력성은 작아진다(항상 1보다 크다).","w":"탄력성 P/(P − a)는 가격이 오를수록 1에 가까워진다. 커지는 쪽은 수량축 절편이 양수인 공급곡선이다.","c":"상","v":1},"경제교재-03-09":{"f":"수량축 절편이 양수인 직선 공급곡선은 모든 점에서 가격탄력성이 1보다 작다.","w":"가격축 절편이 양수일 때가 1보다 크고, 수량축 절편이 양수일 때는 1보다 작다.","c":"상","v":1},"경제교재-03-11":{"f":"상품의 범위를 좁게 정의할수록 대체재가 많아져 수요의 가격탄력성은 커진다.","w":"사과의 탄력성이 과일보다, 콩의 탄력성이 곡물보다 크다.","c":"상","v":1},"경제교재-03-12":{"f":"가격을 4% 인상했더니 판매량이 2% 줄었다면 총수입은 약 2% 증가한다.","w":"총수입 변화율은 가격 변화율과 판매량 변화율의 합이므로 4 − 2 = +2%이다. 탄력성이 0.5인 비탄력적 구간이다.","c":"상","v":1},"경제교재-03-14":{"f":"엥겔의 법칙은 소득이 증가하면 식료품 지출액은 늘지만 총지출에서 차지하는 비중은 감소한다는 것이다.","w":"식료품의 수요의 소득탄력성이 1보다 작다는 뜻이다.","c":"상","v":1},"경제교재-03-16":{"f":"시장 전체의 가격탄력성은 수요량 비중으로 가중평균한 0.95이다.","w":"0.3 × 2 + 0.7 × 0.5 = 0.95이다. 1.25는 단순평균이며, 소비자 수 비중으로 가중해서도 안 된다.","c":"상","v":1},"경제교재-04-02":{"f":"수요의 가격탄력성이 클수록 소비자의 조세부담은 작아지고 생산자의 부담이 커진다.","w":"탄력적인 소비자는 가격이 오르면 구매량을 크게 줄이므로 생산자가 가격을 올려 전가하기 어렵다.","c":"상","v":1},"경제교재-04-05":{"f":"생산자에게 종가세를 부과하면 공급곡선은 기울기가 커지면서 상방으로 이동한다.","w":"종가세는 가격이 높을수록 단위당 세액이 커져 상방 이동 폭이 가격에 비례한다. 기울기가 그대로인 평행 이동은 종량세다.","c":"상","v":1},"경제교재-04-07":{"f":"총보조금 지급액(192)은 소비자잉여와 생산자잉여의 증가분의 합(176)보다 크고, 그 차이 16이 자중손실이다.","w":"보조금 후 균형은 P = 16, Q = 24이고 총보조금은 8 × 24 = 192이다. 소비자잉여는 200에서 288로, 생산자잉여도 200에서 288로 각각 88 늘어 합이 176이다.","c":"상","v":1},"경제교재-04-10":{"f":"유효한 최고가격제는 거래량을 공급량 수준으로 줄여 초과수요와 사회적 후생손실을 낳는다.","w":"상한가격에서는 공급자가 균형 때보다 적게 팔려 하므로 거래량이 줄어든다.","c":"상","v":1},"경제교재-04-12":{"f":"노동수요곡선이 수직선이면 최저임금제로 기존 노동자의 해고는 없고 신규 노동자의 미취업만 생긴다.","w":"수직선이면 임금이 올라도 고용량이 같아 취업자 수는 그대로이고, 늘어난 노동공급자만 실업자가 된다.","c":"상","v":1},"경제교재-04-13":{"f":"균형에서 생산자잉여와 소비자잉여는 각각 50으로 같다.","w":"균형은 P = 10, Q = 10이다. 소비자잉여는 1/2 × (20 − 10) × 10 = 50, 생산자잉여는 1/2 × 10 × 10 = 50이다.","c":"상","v":1},"경제교재-04-14":{"f":"소비자에게 종량세를 부과하면 수요곡선이 하방 이동하여 균형가격(생산자 수취가격)이 하락하고, 소비자가격은 균형가격에 세액을 더한 값이다.","w":"수요가 줄어 생산자가 받는 가격이 내리고, 소비자는 그 가격에 세금을 더 낸다. 가격이 오르는 쪽은 생산자에게 부과할 때의 균형가격이다.","c":"상","v":1},"경제교재-04-16":{"f":"보조금은 생산자에게 주든 소비자에게 주든 균형거래량과 소비자가격이 같다.","w":"종량세와 마찬가지로 지급 대상은 곡선이 이동하는 쪽만 다를 뿐 소비자가격, 생산자 수취가격, 거래량은 같다.","c":"상","v":1},"경제교재-05-02":{"f":"한계효용이 체감한다는 것은 소비량이 늘 때 총효용의 증가분이 감소한다는 뜻이다.","w":"한계효용이 양수인 한 총효용은 계속 늘어난다. 총효용이 줄어드는 것은 한계효용이 음수일 때다.","c":"상","v":1},"경제교재-05-05":{"f":"U = 2X + 3Y에서 X재의 한계효용은 2로 일정하므로 한계효용체감의 법칙이 적용되지 않는다.","w":"X로 미분하면 2, Y로 미분하면 3이어서 소비량과 관계없이 일정하다.","c":"상","v":1},"경제교재-05-08":{"f":"MUx/Px가 MUy/Py보다 크면 X재 소비를 늘리고 Y재 소비를 줄여야 한다.","w":"X재 1원어치에서 얻는 한계효용이 더 크므로 지출을 X재로 옮기면 효용이 늘어난다. 이 과정은 두 값이 같아질 때까지 계속된다.","c":"상","v":1},"경제교재-05-10":{"f":"한계효용학파에 따르면 사용가치는 총효용으로, 교환가치는 한계효용으로 결정된다.","w":"물은 총효용이 크므로 사용가치가 크지만 한계효용이 낮아 가격(교환가치)이 낮다.","c":"상","v":1},"경제교재-05-12":{"f":"사전편찬식 선호는 완전성과 이행성은 만족하지만 연속성을 어긴다.","w":"첫째 재화의 양이 같은 순간 갑자기 선호가 뒤집히므로 연속적이지 않고, 그래서 효용함수로 나타낼 수 없다.","c":"상","v":1},"경제교재-05-14":{"f":"한계효용이론은 1870년대에 등장해 소비자이론의 출발점이 되었고, 현대 소비자이론의 중심은 1920년대 이후의 무차별곡선이론이다.","w":"한계효용이론의 기수적 효용 가정의 한계가 무차별곡선이론이 나오는 계기였다.","c":"상","v":1},"경제교재-05-16":{"f":"현시선호이론은 관측할 수 있는 소비 행태, 즉 현시된 선호로 소비자이론을 전개한다.","w":"관측 불가능한 선호를 전제로 한 것은 한계효용이론과 무차별곡선이론이며, 현시선호이론은 그 문제의식에서 출발했다.","c":"상","v":1},"경제교재-06-02":{"f":"X재를 가로축에 둘 때 한계대체율은 MUx/MUy이다.","w":"X재를 한 단위 늘릴 때 얻는 효용 MUx를 Y재 감소분 MUy로 메워야 하므로 포기하는 Y재의 양은 MUx/MUy이다.","c":"상","v":1},"경제교재-06-05":{"f":"U = X + 2Y이고 두 재화의 가격이 같으면 효용극대화 소비는 Y재만 사는 것이다.","w":"MRS = 1/2이 가격비 1보다 작으므로 1원당 한계효용이 큰 Y재만 산다. 선형 효용함수에서는 MRS가 가격비보다 클 때 X재만 산다.","c":"상","v":1},"경제교재-06-07":{"f":"레온티에프 효용함수에서는 대체효과가 0이고 가격효과 전부가 소득효과이다.","w":"완전보완재는 상대가격이 변해도 소비 비율이 바뀌지 않으므로 대체가 일어나지 않는다. 이때 가격소비곡선과 소득소비곡선이 일치한다.","c":"상","v":1},"경제교재-06-09":{"f":"X재 수요의 가격탄력성이 1보다 크면 가격소비곡선은 우하향한다.","w":"탄력적이면 가격이 내릴 때 X재 지출이 늘어 Y재 지출이 줄므로 Y재 수요가 감소하고 곡선이 우하향한다. 우상향은 탄력성이 1보다 작을 때다.","c":"상","v":1},"경제교재-06-11":{"f":"레온티에프 효용함수는 대체효과가 0이므로 보상수요곡선이 수직선이다.","w":"보상수요곡선은 대체효과만 담는데 완전보완재는 대체효과가 없어 가격이 변해도 보상수요량이 같다. 보통수요곡선은 우하향한다.","c":"상","v":1},"경제교재-06-13":{"f":"소비자잉여는 점마다 효용이 같게 유지되는 보상수요곡선으로 재는 것이 적절하다.","w":"보통수요곡선은 가격 변화에 따른 실질소득 변화까지 담아 곡선 위 점마다 효용수준이 달라진다.","c":"상","v":1},"경제교재-06-16":{"f":"엥겔곡선이 원점을 지나는 직선이면 기울기와 관계없이 소득탄력성이 1이므로 동조재이다.","w":"사치재는 소득탄력성이 1보다 큰 재화로 엥겔곡선이 아래쪽으로 휜다. 필수재는 위쪽으로 휜다.","c":"상","v":1},"경제교재-07-02":{"f":"직접현시선호는 같은 예산집합 안의 두 상품조합 사이에서 쓴다.","w":"같은 예산집합에서 둘 다 살 수 있는데 하나를 골랐을 때 직접현시선호가 성립한다. 예산집합이 서로 다르면 간접현시선호로 선호를 파악한다.","c":"상","v":1},"경제교재-07-03":{"f":"P0Q0 ≥ P0Q1 이면서 P1Q1 ≥ P1Q0이면 약공리를 위배한다.","w":"앞 부등식은 Q0가 Q1보다 직접현시선호됨을, 뒤 부등식은 Q1이 Q0보다 직접현시선호됨을 뜻한다. 두 관계가 동시에 성립할 수 없다는 것이 약공리다.","c":"상","v":1},"경제교재-07-05":{"f":"재화가 세 가지 이상이면 약공리만으로는 부족하고 강공리가 필요하다.","w":"재화가 둘이면 약공리로 충분하지만 셋 이상이면 간접현시선호까지 다루는 강공리(이행성)가 있어야 한다.","c":"상","v":1},"경제교재-07-09":{"f":"(12, 3)을 고르면 약공리를 위배하지 않는다.","w":"처음 가격에서 (12, 3)의 비용은 27로 소득 24를 넘어 그때는 살 수 없었다. 처음 묶음이 (12, 3)보다 현시선호된다는 근거가 없으므로 위배가 아니다.","c":"상","v":1},"경제교재-07-11":{"f":"효용은 감소했다.","w":"처음 예산집합에서 (4, 8)의 비용은 80 + 80 = 160이라 살 수 있었는데 (4, 12)를 골랐으므로 (4, 12)가 현시선호되었다. 새 가격에서 (4, 12)의 비용은 280이라 살 수 없으니 약공리는 만족하고, 나중 선택이 덜 선호하는 묶음이라 효용은 줄었다.","c":"상","v":1},"경제교재-07-12":{"f":"(50, 30)을 고르면 약공리를 위배하지 않는다.","w":"처음 가격에서 (60, 20)의 비용은 1,400이고 (50, 30)의 비용은 1,700이다. (50, 30)은 처음에 살 수 없던 조합이므로 (60, 20)이 (50, 30)보다 현시선호되었다고 할 수 없다.","c":"상","v":1},"경제교재-07-14":{"f":"X재 구입량이 늘어난다.","w":"가상 예산선 위에서 처음 선택점보다 X재를 덜 사는 점은 처음 선택점이 현시선호되어 있어 약공리를 위배한다. 그러므로 대체효과로 X재 구입량이 늘어난다.","c":"상","v":1},"경제교재-07-16":{"f":"E0를 지나는 무차별곡선은 E0의 우상방 영역을 지날 수 없다.","w":"우상방의 점은 E0보다 두 재화를 모두 더 많이 갖는 점이라 E0보다 더 선호된다. 같은 효용을 주는 점의 집합인 무차별곡선이 이 영역을 지나면 모순이다.","c":"상","v":1},"경제교재-08-02":{"f":"X재 현물보조를 받은 소비자의 예산선은 일부 구간에서만 기울기가 같다.","w":"보조받은 양 미만의 X재 소비는 불가능해 예산선이 꺾인다. 그래서 현금보조 때 고를 수 있던 일부 소비점이 현물보조에서는 선택 불가능해진다.","c":"상","v":1},"경제교재-08-04":{"f":"현물보조와 현금보조의 효용은 17로 같다.","w":"현물을 받으면 x = 6 + y_구입이고 4x + 2y_구입 = 90에서 x = 17이다. 현금 12를 받아도 (90 + 12)/6 = 17이다. 현금으로도 Y재를 6단위 이상 사게 되므로 현물 제약이 걸리지 않는다.","c":"상","v":1},"경제교재-08-05":{"f":"X재 소비를 늘리는 데는 가격보조가 현금보조보다 효과가 크거나 같다.","w":"가격보조는 소득효과에 더해 X재가 상대적으로 싸지는 대체효과가 X재 소비를 늘린다. 반면 소비자 효용은 현금보조가 가격보조보다 높다.","c":"상","v":1},"경제교재-08-07":{"f":"동등변화는 가격 변화 이후와 같은 효용을 얻도록 원래 가격 아래에서 조정해야 하는 소득이다.","w":"가격 변화 이전의 효용을 기준으로 변화된 가격에서 재는 것은 보상변화다.","c":"상","v":1},"경제교재-08-09":{"f":"라스파이레스 수량지수가 1보다 커도 생활수준이 반드시 개선된다는 보장은 없다.","w":"수량지수 P0Q1/P0Q0가 1보다 크면 비교연도 묶음을 기준연도 가격에서 살 수 없었다는 뜻이다. 반면 1 이하이면 기준연도 묶음이 선택되었으므로 명백한 악화다.","c":"상","v":1},"경제교재-08-10":{"f":"라스파이레스 물가지수는 물가 상승을 과대평가하는 경향이 있다.","w":"소비자는 값이 오른 재화의 구입을 줄이는데 기준연도 수량은 이를 반영하지 못한다. 비교연도 수량을 쓰는 파셰 지수는 과소평가하는 경향이 있다.","c":"상","v":1},"경제교재-08-12":{"f":"차입자는 이자율이 상승하면 소득효과로 현재소비가 감소한다.","w":"이자 부담이 늘어 실질소득이 줄므로 정상재인 현재소비가 감소한다. 대체효과도 현재소비를 줄이므로 차입자의 현재소비는 반드시 감소한다.","c":"상","v":1},"경제교재-08-14":{"f":"1기 소비는 50이다.","w":"MRS = C2/(2C1) = 1 + r에서 C2 = 2.2C1이고 소득의 현재가치는 90 + 66/1.1 = 150이다. C1 + C2/1.1 = 3C1 = 150이므로 C1 = 50이다.","c":"상","v":1},"경제교재-09-01":{"f":"위험기피자가 유리한 도박에 참여할지는 위험기피 정도에 따라 달라진다.","w":"유리한 도박이어도 기피 정도가 크면 확실한 소득이 불확실한 기대소득보다 더 큰 효용을 줄 수 있어 참여하지 않는다.","c":"하","v":1},"경제교재-09-02":{"f":"위험선호자의 확실성등가는 기대소득보다 크다.","w":"위험선호자는 효용함수가 강볼록이라 기대소득의 효용이 소득의 기대효용보다 작다. 따라서 같은 효용을 주는 확실한 소득이 기대소득보다 크고 위험프리미엄은 음수다.","c":"상","v":1},"경제교재-09-03":{"f":"오목한 정도가 클수록 확실성등가는 작아진다.","w":"위험기피 정도가 클수록 위험을 피하는 대가로 포기하려는 금액이 커져 확실성등가는 작아지고 위험프리미엄은 커진다.","c":"상","v":1},"경제교재-09-04":{"f":"위험중립자의 총효용곡선은 우상향하는 직선이다.","w":"위험중립자는 소득의 한계효용이 일정해 기대소득의 효용과 소득의 기대효용이 같다. 그래서 확실성등가가 기대소득과 같고 위험프리미엄은 0이다.","c":"상","v":1},"경제교재-09-06":{"f":"확실성등가는 4이다.","w":"기대효용은 0.5 × 4 + 0.5 × 0 = 2이므로 확실성등가는 2² = 4다. 기대소득 8과의 차이 4가 위험프리미엄이다.","c":"상","v":1},"경제교재-09-08":{"f":"공정한 보험에 가입해도 소득의 기댓값은 늘지 않고 효용만 늘어난다.","w":"보험 가입 후 소득은 사고 여부와 관계없이 보험 가입 전 기대소득과 같은 확실한 값이 된다. 불확실한 소득이 확실한 소득으로 바뀌어 효용만 증가한다.","c":"하","v":1},"경제교재-09-11":{"f":"위험프리미엄은 25이다.","w":"재산이 100 또는 400이므로 기대효용은 (10 + 20)/2 = 15이고 확실성등가는 225다. 기대소득이 250이므로 위험프리미엄은 250 − 225 = 25다.","c":"상","v":1},"경제교재-09-13":{"f":"이 게임의 기대 상금은 무한대인데도 참가하려는 사람이 거의 없다는 것이 역설이다.","w":"다니엘 베르누이는 사람들이 기대 수익이 아니라 기대효용을 따지기 때문이라고 풀었다. 소득의 한계효용이 체감하면 기대효용은 크지 않다.","c":"상","v":1},"경제교재-10-01":{"f":"한계생산체감의 법칙은 고정투입요소가 있는 단기에 가변요소를 늘릴 때 나타난다.","w":"모든 요소를 같은 비율로 늘릴 때의 산출 변화는 규모에 대한 보수다. 두 개념은 서로 체계적 관계가 없다.","c":"상","v":1},"경제교재-10-03":{"f":"한계생산이 체감하더라도 양(+)이면 총생산은 계속 증가하고, 한계생산이 음이 되어야 총생산이 감소한다.","w":"한계생산이 체감하는 것과 부호가 음인 것은 다르다. 총생산의 증감은 한계생산의 부호로 판단한다.","c":"상","v":1},"경제교재-10-05":{"f":"규모수익불변이어도 한 요소만 늘리면 한계생산이 체감할 수 있다.","w":"Q = L^0.5K^0.5은 규모수익불변이지만 K를 고정하고 L을 늘리면 MPL이 줄어든다. 한계생산체감은 단기, 규모수익은 장기의 개념이라 서로 무관하다.","c":"상","v":1},"경제교재-10-07":{"f":"두 법칙은 논리적 관계가 없다.","w":"MRTS 체감은 등량곡선의 볼록성이고 한계생산체감은 한 요소만 늘릴 때의 단기 현상이다. 소비자이론에서 한계대체율체감과 한계효용체감이 무관한 것과 같다.","c":"상","v":1},"경제교재-10-10":{"f":"최소비용은 250이다.","w":"L자형 생산함수는 2L = K = Q에서 쓰므로 L = 50, K = 100이다. 비용은 3 × 50 + 1 × 100 = 250이다.","c":"상","v":1},"경제교재-10-12":{"f":"대체탄력성이 1보다 크면 임금이 오를 때 노동소득분배율이 낮아진다.","w":"임금이 1% 오를 때 노동투입이 1%를 넘게 줄어 노동소득(임금 × 노동량)이 줄어든다. 대체탄력성이 1보다 작으면 노동소득분배율이 높아지고 1이면 불변이다.","c":"상","v":1},"경제교재-10-14":{"f":"규모수익체증이면 한계생산물만큼 지급해도 총생산물이 부족해 이윤이 음이다.","w":"오일러 정리는 1차 동차(규모수익불변)일 때 총생산물이 한계생산물 지급으로 정확히 분배된다는 것이다. 체증이면 지급액이 총생산물보다 크다.","c":"상","v":1},"경제교재-10-16":{"f":"자본집약적(노동절약적) 기술진보가 일어나면 요소집약도는 증가한다.","w":"등량곡선이 안쪽으로 이동하면서 새 균형점의 K/L이 커진다. 노동집약적 진보는 요소집약도를 낮추고 중립적 진보는 그대로 둔다.","c":"상","v":1},"경제교재-11-01":{"f":"기지출 1,000은 매몰비용이라 제외하고 추가비용 300과 예상 판매액 500을 비교해 개발을 계속해야 한다.","w":"매몰비용은 기회비용이 0이라 의사결정에 영향을 주지 않는다. 지금부터의 추가 수입 500이 추가 비용 300보다 크므로 완료하는 것이 이득이다.","c":"상","v":1},"경제교재-11-03":{"f":"총고정비용이 늘어도 한계비용은 변하지 않는다.","w":"한계비용은 총비용을 생산량으로 미분한 값이고 총고정비용은 상수라 미분하면 0이다. 총비용곡선이 위로 평행 이동할 뿐 기울기는 같다.","c":"상","v":1},"경제교재-11-05":{"f":"평균가변비용 최저점은 평균비용 최저점보다 생산량이 작은 쪽에서 먼저 나타난다.","w":"AVC가 오르기 시작해도 증가분이 평균고정비용의 감소분보다 작으면 평균비용은 계속 내려간다. 그래서 AC의 최저점이 더 오른쪽에 있다.","c":"상","v":1},"경제교재-11-06":{"f":"평균비용이 증가하는 구간에서는 한계비용이 평균비용보다 크다.","w":"평균보다 큰 한계값이 추가되면 평균이 오르고 작은 한계값이 추가되면 평균이 내린다.","c":"상","v":1},"경제교재-11-09":{"f":"장기평균비용곡선은 단기평균비용곡선들을 아래에서 감싸는 포락선이며 최저점을 이은 곡선이 아니다.","w":"LAC와 SAC는 접점에서 일치하는데 그 접점은 규모수익불변일 때만 SAC의 최저점이다.","c":"상","v":1},"경제교재-11-11":{"f":"규모수익체증이면 장기평균비용곡선은 단기평균비용곡선의 최저점 왼쪽에서 접한다.","w":"LAC가 아직 하락 중이라 접점에서 SAC도 하락하는 구간이다. 그래서 SAC 최저점의 설비보다 큰 설비를 쓰는 과잉설비가 존재한다.","c":"상","v":1},"경제교재-11-14":{"f":"두 개념은 체계적인 관계가 없어 규모의 경제가 있어도 범위의 경제가 없을 수 있다.","w":"범위의 경제는 여러 상품을 함께 생산할 때의 비용절감이고 규모의 경제는 한 상품의 생산량이 늘 때 평균비용이 줄어드는 것이다.","c":"상","v":1},"경제교재-11-16":{"f":"MR = MC에 더해 MC 곡선의 기울기가 MR 곡선의 기울기보다 커야 이윤이 극대화된다.","w":"1계 조건을 만족해도 2계 조건이 안 맞으면 이윤이 극소가 된다. 한계비용이 체감하는 점은 극소점이다.","c":"상","v":1},"경제교재-12-02":{"f":"완전경쟁기업의 한계수입은 시장가격과 같다.","w":"가격이 판매량과 무관하게 일정하므로 한 단위를 더 팔 때 수입이 가격만큼 늘어난다. 한계수입이 가격보다 작아지는 것은 불완전경쟁시장이다.","c":"상","v":1},"경제교재-12-06":{"f":"임금이 오르면 생산중단 가격도 올라간다.","w":"생산중단점은 평균가변비용의 최저점이라 가변비용이 늘면 AVC 곡선이 위로 이동해 오른다. 총고정비용이 늘 때는 생산중단점이 변하지 않는다.","c":"상","v":1},"경제교재-12-08":{"f":"종량세를 부과하면 개별기업의 생산량이 줄어든다.","w":"종량세는 한계비용을 세금만큼 높여 P = MC를 만족하는 생산량이 감소한다. 평균가변비용도 올라 생산중단점이 상승한다.","c":"상","v":1},"경제교재-12-10":{"f":"개별기업의 장기공급곡선은 존재하지 않는다.","w":"장기에는 LAC의 최저점에서만 생산이 이루어지므로 LMC 곡선 전체가 공급곡선이 되지 못한다. 산업의 장기공급곡선도 개별 곡선의 수평합이 아니라 장기균형점을 이어 도출한다.","c":"상","v":1},"경제교재-12-11":{"f":"장기균형에서 0인 것은 경제적 이윤이며 정상이윤은 얻는다.","w":"경제적 이윤은 회계적 이윤에서 정상이윤을 포함한 암묵적 비용을 뺀 값이다. 경제적 이윤이 0이어도 회계적 이윤은 정상이윤만큼 양수다.","c":"상","v":1},"경제교재-12-13":{"f":"장기에는 가격이 14로 그대로이고 기업 10개가 새로 진입한다.","w":"비용불변산업은 생산요소 가격이 변하지 않아 개별 비용곡선이 이동하지 않는다. 가격이 최저 LAC로 돌아가고 개별 생산량 6이 같으므로 늘어난 60은 60/6 = 10개 기업이 맡는다.","c":"상","v":1},"경제교재-12-14":{"f":"비용증가산업의 장기공급곡선은 우상향한다.","w":"산업 전체 생산이 늘면 생산요소 가격이 올라 개별기업의 비용곡선이 위로 이동하므로 새 균형가격이 이전보다 높다. 수평선은 비용불변산업이다.","c":"상","v":1},"경제교재-12-15":{"f":"P = MC에 더해 MC 곡선의 기울기가 양이어서 2계 조건을 충족해야 극대화다.","w":"한계비용이 체감하는 구간에서 P = MC이면 이윤극소점이다. 이윤극대점은 한계비용이 체증하는 구간에 있다.","c":"상","v":1},"경제교재-12-16":{"f":"단기 생산자잉여는 이윤에 총고정비용을 더한 값이라 이윤보다 크거나 같다.","w":"생산자잉여는 총수입에서 총가변비용을 뺀 값이다. 고정비용이 없는 장기에는 이윤과 같이 0이 된다.","c":"상","v":1},"경제교재-13-01":{"f":"독점기업은 MR = MC로 생산량을 먼저 정하고 그 생산량에 대응하는 가격을 시장수요곡선에서 책정한다.","w":"MR = MC는 생산량을 결정하는 조건이다. 독점기업은 가격책정자이지만 가격과 판매량을 동시에 임의로 정할 수 없고 수요곡선을 따른다.","c":"상","v":1},"경제교재-13-02":{"f":"독점기업에는 공급곡선이 존재하지 않는다.","w":"독점기업은 가격에 맞춰 공급량을 정하지 않고 생산량을 정한 뒤 수요곡선에서 가격을 받으므로 가격과 공급량이 일대일로 대응하지 않는다.","c":"상","v":1},"경제교재-13-05":{"f":"자중손실은 200에서 450으로 늘어난다.","w":"MC = 40이면 Q = 20, P = 60이고 자중손실은 ½ × (60 − 40) × (40 − 20) = 200이다. MC = 20이면 Q = 30, P = 50이고 ½ × (50 − 20) × (60 − 30) = 450이다. 비용이 내려가면 독점기업이 이윤을 더 쌓을 뿐 완전경쟁과의 격차는 커진다.","c":"상","v":1},"경제교재-13-06":{"f":"수요의 가격탄력성이 낮은 시장에 높은 가격을 매긴다.","w":"MR1 = MR2 = MC이고 MR = P(1 − 1/ε)이므로 ε가 작은 시장의 P가 커야 한계수입이 같아진다.","c":"상","v":1},"경제교재-13-09":{"f":"3급 가격차별이 사회후생을 반드시 늘리는 것은 아니다.","w":"시장마다 가격이 달라 소비자의 한계편익이 서로 달라지는 비효율이 생긴다. 가격차별로 새 소비자가 생겨 총생산량이 늘 때만 후생이 개선될 수 있다.","c":"상","v":1},"경제교재-13-11":{"f":"묶어팔기는 두 상품에 대한 소비자들의 선호가 음(−)의 상관일 때 효과가 크다.","w":"한 소비자는 햄버거를, 다른 소비자는 콜라를 더 높이 평가해야 묶음가격으로 두 소비자의 지불용의가 비슷해진다. 한 소비자가 모든 상품을 높이 평가하면 묶어팔기로 수입을 늘릴 수 없다.","c":"상","v":1},"경제교재-13-14":{"f":"한계비용가격 규제에서는 P < AC라 독점기업이 손실을 본다.","w":"평균비용이 계속 줄면 한계비용이 평균비용보다 낮아 한계비용 가격으로는 평균비용을 회수하지 못한다. 평균비용가격 규제를 해야 정상이윤만 얻는다.","c":"상","v":1},"경제교재-13-16":{"f":"세액의 절반이 소비자에게 전가된다.","w":"MR의 기울기가 수요곡선 기울기의 2배라 한계비용이 t만큼 오르면 가격은 t/2만큼 오른다. 나머지 절반은 독점기업이 부담한다.","c":"상","v":1},"경제교재-14-02":{"f":"독점적 경쟁기업의 수요곡선은 독점기업보다 가격에 대해 더 탄력적이다.","w":"밀접한 대체재가 많아 가격을 올리면 고객을 많이 잃는다. 그래서 수요곡선이 더 완만하다.","c":"상","v":1},"경제교재-14-03":{"f":"독점적 경쟁시장의 장기균형에서 개별기업의 수요곡선은 장기평균비용곡선이 우하향하는 구간에서 접한다.","w":"수요곡선이 우하향하므로 같은 기울기로 접하려면 평균비용곡선도 내려가는 구간이어야 한다. 최저점에서 접하는 것은 수평 수요곡선인 완전경쟁이다.","c":"상","v":1},"경제교재-14-05":{"f":"신규기업이 진입하면 기존 기업의 수요곡선이 왼쪽으로 이동한다.","w":"시장수요를 새 기업과 나눠 가지므로 기존 기업의 고객이 줄어든다. 이 이동은 초과이윤이 0이 될 때까지 계속된다.","c":"상","v":1},"경제교재-14-07":{"f":"완전경쟁기업만 초과설비가 없고 독점적 경쟁기업은 초과설비를 보유한다.","w":"이윤이 0인 것은 같지만 완전경쟁기업은 LAC 최저점에서 생산한다. 독점적 경쟁기업은 우하향하는 수요곡선 때문에 최저점 왼쪽에서 생산한다.","c":"상","v":1},"경제교재-14-09":{"f":"독점적 경쟁기업도 가격차별을 할 수 있다.","w":"가격차별은 독점기업만큼 강한 시장지배력을 요구하지 않는다. 제품 차별화로 얻은 시장지배력만 있으면 가능하다.","c":"상","v":1},"경제교재-14-11":{"f":"독점적 경쟁기업은 수요의 가격탄력성이 1보다 큰 구간에서 이윤을 극대화한다.","w":"MC가 양수이므로 MR = MC > 0이어야 하고, MR = P(1 − 1/ε) > 0이 되려면 ε > 1이다.","c":"상","v":1},"경제교재-15-02":{"f":"꾸르노 모형에서 기업 수가 늘어나면 균형은 완전경쟁시장의 균형에 가까워진다.","w":"기업이 많아지면 한 기업의 증산이 가격에 미치는 영향이 작아진다. 총산출 n(a − c)/((n + 1)b)는 n이 커질수록 완전경쟁 산출 (a − c)/b에 수렴한다.","c":"상","v":1},"경제교재-15-04":{"f":"선도자 이윤은 꾸르노 기업 이윤보다 크다.","w":"선도자는 독점 산출량 30을 정하고 추종자는 15를 생산해 P = 15이다. 선도자 이윤 450은 꾸르노 400보다 크다.","c":"상","v":1},"경제교재-15-06":{"f":"슈타켈버그 균형의 시장가격은 꾸르노 균형의 가격보다 낮다.","w":"슈타켈버그 총산출(독점 산출량의 3/2배)이 꾸르노 총산출(독점의 4/3배)보다 많다. 산출이 많으면 가격이 낮고 소비자후생은 커진다.","c":"상","v":1},"경제교재-15-09":{"f":"카르텔의 한계비용곡선은 가맹 기업 한계비용곡선을 수평으로 합해 구한다.","w":"같은 한계비용 수준에서 각 기업이 내놓는 양을 더하는 것이다. 다공장 독점과 같은 방식이다.","c":"상","v":1},"경제교재-15-10":{"f":"각 기업에는 협정을 어기고 몰래 증산할 유인이 있다.","w":"카르텔 가격이 한계비용보다 높아 협정 할당량을 넘겨 팔면 이윤이 더 늘어난다. 그래서 카르텔은 불안정하다.","c":"상","v":1},"경제교재-15-12":{"f":"한계비용이 MR 곡선의 불연속 구간 안에서 변해도 가격과 생산량은 변하지 않는다.","w":"MC가 불연속 구간을 지나는 동안 MR = MC인 점이 꺾이는 점에 그대로 있다. 이것이 가격 경직성의 설명이다.","c":"상","v":1},"경제교재-15-14":{"f":"진입저지가격은 기존 기업의 이윤극대화 가격보다 낮게 설정된다.","w":"진입을 막으려고 초과이윤 일부를 포기한다. 하한은 잠재 진입자의 초과이윤이 0이 되는 가격이다.","c":"상","v":1},"경제교재-16-01":{"f":"용의자의 딜레마 게임의 우월전략균형은 파레토 비효율적이다.","w":"둘 다 부인하면 두 사람 보수가 모두 더 높은데도 각자의 우월전략 때문에 둘 다 자백한다.","c":"상","v":1},"경제교재-16-03":{"f":"모든 우월전략균형은 내쉬균형이지만 모든 내쉬균형이 우월전략균형인 것은 아니다.","w":"내쉬전략은 상대의 주어진 전략에 대해서만 최선이면 된다.","c":"상","v":1},"경제교재-16-05":{"f":"a = 3이면 (U,L)은 내쉬균형이다.","w":"경기자 1이 D로 바꿔도 보수가 3으로 같아 이득이 없고, 경기자 2도 L에서 이탈하면 0이므로 손해다. 이탈해도 보수가 같으면 균형이 유지된다.","c":"상","v":1},"경제교재-16-08":{"f":"경기자 1의 A 확률은 변하지 않고 경기자 2의 A 확률이 2/5에서 1/3로 낮아진다.","w":"경기자 1의 확률은 경기자 2의 보수로만 정해진다. 경기자 1의 보수가 변하면 경기자 1을 무차별하게 만드는 상대 확률이 바뀐다.","c":"상","v":1},"경제교재-16-11":{"f":"내쉬균형이 둘이어도 부분게임완전균형은 하나다.","w":"진입 안 함과 경쟁의 조합은 공허한 위협에 기대는 내쉬균형이어서 부분게임에서 최선이 아니다. 진입과 협조만 부분게임완전균형이다.","c":"상","v":1},"경제교재-16-14":{"f":"최소극대화 전략은 내쉬전략과 일치할 수도, 다를 수도 있다.","w":"최소극대화는 상대의 비합리성에 대비해 최악의 보수를 가장 크게 하는 보수적 선택이고, 내쉬전략은 상대가 합리적이라는 가정에서 나온다.","c":"상","v":1},"경제교재-16-15":{"f":"경합시장에서는 기업이 소수여도 P = AC = MC이다.","w":"진입과 퇴출이 자유로워 가격이 평균비용 위로 오르면 잠재 진입자가 들어온다. 이윤이 0이 되고 완전경쟁과 비슷한 효율을 얻는다.","c":"상","v":1},"경제교재-17-02":{"f":"생산물시장이 불완전경쟁이면 VMP가 MRP보다 크다.","w":"P > MR이므로 P × MPL이 MR × MPL보다 크다. 생산량이 늘수록 둘의 격차도 벌어진다.","c":"상","v":1},"경제교재-17-04":{"f":"수요독점 노동시장에서는 한계요소비용이 임금보다 크다.","w":"고용을 늘리려면 새로 고용하는 노동자뿐 아니라 이미 고용한 노동자에게도 높아진 임금을 줘야 한다. 그래서 MFC > w이다.","c":"상","v":1},"경제교재-17-06":{"f":"수요독점기업은 임금을 노동공급곡선에서 정하므로 MRP보다 낮게 지급한다.","w":"MRP = MFC로 고용량을 정한 뒤 그 고용량에 필요한 최소 임금을 공급곡선에서 읽는다. MRP와의 차이가 수요독점적 착취다.","c":"상","v":1},"경제교재-17-09":{"f":"최저임금이 경쟁 임금 80을 넘으면 고용은 55로 경쟁 균형 60보다 적다.","w":"w = 90에서 MRP = 90이 되는 L은 55이다. 55는 수요독점 때의 45보다 많지만 경쟁 균형 60보다 적다.","c":"상","v":1},"경제교재-17-10":{"f":"노동수요의 임금탄력성은 단기보다 장기에 크다.","w":"장기에는 자본 등 다른 요소를 조정해 노동을 대체할 수 있어 노동수요곡선이 더 완만해진다.","c":"상","v":1},"경제교재-17-12":{"f":"대체탄력성이 커지면 노동수요의 임금탄력성도 커진다.","w":"임금이 오를 때 기업이 노동을 자본으로 쉽게 바꾸므로 노동수요량이 더 크게 줄어든다.","c":"상","v":1},"경제교재-17-15":{"f":"노동공급이 감소할 때 총노동소득은 노동수요가 비탄력적이면 증가하고 탄력적이면 감소한다.","w":"임금 상승률과 고용 감소율 중 어느 쪽이 큰지에 달렸다. 탄력적이면 고용 감소율이 더 크다.","c":"상","v":1},"경제교재-18-02":{"f":"실질임금은 약 3% 내린다.","w":"실질임금 상승률은 명목임금 상승률에서 물가 상승률을 뺀 값이라 5 − 8 = −3(%)이다.","c":"상","v":1},"경제교재-18-04":{"f":"보상적 임금격차는 완전경쟁시장에서도 나타난다.","w":"위험하거나 불쾌한 직무에는 근로자가 그 불리함을 감수하는 대가로 더 높은 임금이 붙는다. 시장이 불완전해서 생기는 격차가 아니다.","c":"상","v":1},"경제교재-18-06":{"f":"토지세는 전액 지주가 부담한다.","w":"토지서비스 공급이 완전비탄력적이라 지대를 올리면 초과공급이 생겨 지대가 원래 수준으로 돌아간다. 공급량이 변하지 않아 후생손실도 없다.","c":"상","v":1},"경제교재-18-08":{"f":"노동공급이 완전탄력적이면 보수는 전부 전용수입이다.","w":"공급곡선이 수평이면 균형 보수 전체가 공급곡선 아래 면적이라 지대로 남는 부분이 없다.","c":"상","v":1},"경제교재-18-10":{"f":"준지대는 단기에만 존재한다.","w":"장기에는 모든 요소가 가변이고 진입과 퇴출이 자유로워 고정요소의 몫이 없다.","c":"상","v":1},"경제교재-18-12":{"f":"로렌츠곡선이 대각선과 일치하면 지니계수는 0이다.","w":"대각선과 곡선 사이의 면적이 0이므로 완전 평등이다. 지니계수가 1이면 한 사람이 모든 소득을 갖는 경우다.","c":"상","v":1},"경제교재-18-14":{"f":"십분위분배율은 0.3이다.","w":"하위 40%의 점유율을 상위 20%의 점유율로 나누므로 15/50 = 0.3이다. 십분위분배율은 0과 2 사이다.","c":"상","v":1},"경제교재-18-15":{"f":"오분위분배율은 값이 작을수록 더 평등하다.","w":"상위 20% 점유율을 하위 20% 점유율로 나눈 값이라 완전 평등이면 1이고 불평등할수록 커진다. 십분위분배율과 방향이 반대다.","c":"상","v":1},"경제교재-19-02":{"f":"n − 1개 시장이 균형이면 나머지 한 시장도 반드시 균형이다.","w":"왈라스 법칙에 따라 모든 시장의 초과수요 가치의 합이 0이므로 한 시장만 불균형일 수 없다.","c":"상","v":1},"경제교재-19-03":{"f":"왈라스 법칙은 어떤 가격에서도 성립하는 항등식이다.","w":"소비자의 총지출은 총수요 가치이고 생산자의 총판매는 총공급 가치인데, 예산제약 때문에 가격과 관계없이 합계가 0이 된다.","c":"상","v":1},"경제교재-19-05":{"f":"한계대체율은 같지만 효용 수준은 3과 9로 다르다.","w":"경쟁균형에서는 두 소비자의 MRS가 상대가격과 같아 서로 같다. 그러나 부존량의 가치가 달라 소득이 다르므로 효용은 같지 않다.","c":"상","v":1},"경제교재-19-07":{"f":"두 소비자의 선호가 u = x + √y로 같으면 계약곡선은 y를 반씩 나누는 수평선이다.","w":"MRS = 2√y로 y만으로 정해져 파레토 효율 조건은 y1 = y2이다. x는 어떻게 나누어도 된다.","c":"상","v":1},"경제교재-19-10":{"f":"일반균형이 존재하기 위한 필요충분조건은 정립되어 있지 않다.","w":"애로우와 드브뢰는 충분조건(완전경쟁과 시장실패 없음)을 증명했을 뿐이다. 이것이 일반균형분석의 한계로 꼽힌다.","c":"상","v":1},"경제교재-19-12":{"f":"왈라스는 일반균형의 존재를 증명하지 않고 가정했다.","w":"수학적 증명은 1950년대 애로우와 드브뢰가 했다.","c":"상","v":1},"경제교재-20-01":{"f":"파레토 효율은 자원배분의 효율만 의미하고 분배의 공평성은 고려하지 않는다.","w":"한 사람이 모든 재화를 갖고 다른 사람은 아무것도 갖지 못하는 배분도 파레토 효율이다. 그래서 효율적인 배분이 모두 사회적으로 바람직한 것은 아니다.","c":"상","v":1},"경제교재-20-04":{"f":"생산의 파레토 효율 조건은 두 재화 생산의 한계기술대체율이 같은 것이다.","w":"한계대체율은 소비의 조건이다. 생산에서는 노동과 자본의 교환비율인 MRTS가 두 재화 사이에서 같아야 한다.","c":"상","v":1},"경제교재-20-07":{"f":"MRS > MRT이면 X재 생산을 늘리고 Y재 생산을 줄여야 한다.","w":"MRS는 소비자가 X 한 단위에 부여하는 Y 단위 가치이고 MRT는 X의 기회비용이다. 가치가 비용보다 크면 X를 더 만드는 것이 이득이다.","c":"상","v":1},"경제교재-20-09":{"f":"제2정리는 초기부존을 적절히 재분배한 뒤에야 임의의 파레토 효율 배분이 경쟁균형으로 달성된다는 것이다.","w":"효율과 공평을 함께 얻으려면 먼저 초기부존을 조정하고 그 뒤에 시장에 맡긴다. 선호와 생산기술이 볼록해야 한다.","c":"상","v":1},"경제교재-20-11":{"f":"롤즈의 사회후생함수에서는 A가 20, B가 80을 갖는다.","w":"최소 효용을 극대화하려면 두 효용이 같아야 하므로 4√x_A = 2√x_B, x_B = 4x_A이다. 효용이 낮아지기 쉬운 B에게 더 많이 준다.","c":"상","v":1},"경제교재-20-14":{"f":"충족되는 효율 조건을 늘려도 사회후생이 증가한다는 보장이 없다.","w":"이것이 립시와 랭카스터의 차선의 이론이다. 일부가 어긋난 상태에서는 나머지 조건도 어기는 쪽이 나을 수 있다.","c":"상","v":1},"경제교재-21-01":{"f":"자연독점은 규모의 경제, 즉 평균비용이 계속 감소할 때 발생한다.","w":"수확체감이면 규모가 커질수록 평균비용이 올라 자연독점이 생기지 않는다.","c":"상","v":1},"경제교재-21-03":{"f":"최적 오염 수준은 0이 아니다.","w":"오염을 줄일수록 저감 한계비용이 커진다. 한계편익과 한계비용이 같은 양의 오염 수준에서 사회후생이 최대다.","c":"상","v":1},"경제교재-21-05":{"f":"단위당 10의 피구세로는 산출이 35가 되어 최적 30보다 많다.","w":"세금 10을 넣은 공급은 P = Q + 10이므로 80 − Q = Q + 10에서 Q = 35이다. 최적 세율은 외부 한계비용 20이다.","c":"상","v":1},"경제교재-21-07":{"f":"재산권이 누구에게 있든 최종 산출량은 같다.","w":"협상 결과는 사회적 최적 수준으로 같고, 재산권 배분은 누가 보상금을 받느냐만 바꾼다.","c":"상","v":1},"경제교재-21-09":{"f":"직접규제는 기업의 저감비용 차이를 반영하지 못해 배출권 거래보다 비용이 더 든다.","w":"배출권 거래는 한계저감비용이 낮은 기업이 더 줄이고 권리를 팔아 한계저감비용을 같게 만든다.","c":"상","v":1},"경제교재-21-11":{"f":"막히지 않는 유료도로와 케이블TV는 클럽재이다.","w":"대가를 낸 사람만 쓸 수 있어 배제가 가능하고 혼잡이 없어 비경합적이다. 공유자원은 배제가 불가능하고 경합적이다.","c":"상","v":1},"경제교재-21-15":{"f":"시장실패는 정부개입의 충분조건이 아니다.","w":"정부실패의 크기가 시장실패보다 작을 때만 개입이 정당화된다.","c":"상","v":1},"경제교재-22-02":{"f":"전원합의제에서는 외부비용이 거의 0이다.","w":"반대하는 사람이 있으면 통과되지 않으므로 반대자가 피해를 입을 일이 없다. 대신 의사결정비용이 최대가 된다.","c":"상","v":1},"경제교재-22-04":{"f":"다수결투표제의 결과는 파레토 최적이 아닐 수 있다.","w":"다수파의 효용은 오르고 소수파의 효용은 내리는 방향으로 갈 수 있다. 전원합의제만 파레토 최적을 보장한다.","c":"상","v":1},"경제교재-22-05":{"f":"투표의 역설은 일부 투표자가 다봉선호를 가질 때 발생할 수 있다.","w":"모두 단봉선호이면 중위투표자의 선호가 안정적으로 채택된다.","c":"상","v":1},"경제교재-22-07":{"f":"점수투표제에서는 투표의 역설이 발생하지 않는다.","w":"합계 점수가 가장 높은 안건 하나를 채택하므로 순환이 생기지 않는다. 대신 전략적 투표에 취약하다.","c":"상","v":1},"경제교재-22-11":{"f":"의결에 필요한 찬성 비율이 높아질수록 외부비용은 감소한다.","w":"찬성이 많이 필요할수록 반대자가 늘어나는 안이 통과되기 어려워 반대자의 피해가 줄어든다. 반면 의사결정비용은 증가한다.","c":"상","v":1},"경제교재-22-13":{"f":"지대추구 행위는 로비에 쓰인 자원만큼 사회적 낭비를 만든다.","w":"진입장벽이 만들어지면 독점처럼 후생손실이 생기고, 지대를 놓고 경쟁하는 데 자원이 쓰인다.","c":"상","v":1},"경제교재-23-01":{"f":"역선택은 계약 전의 감추어진 특성 때문에 생긴다.","w":"계약 뒤 감추어진 행동에서 생기는 것은 도덕적 해이다. 역선택은 상대의 특성이나 품질을 모르고 거래해 바람직하지 못한 상대가 남는 현상이다.","c":"상","v":1},"경제교재-23-03":{"f":"구매자가 품질을 알면 좋은 차도 700과 900 사이의 가격에서 거래된다.","w":"좋은 차의 지불의사 900이 수용의사 700보다 커서 거래 이득이 있다. 정보 비대칭이 있을 때만 거래가 사라진다.","c":"상","v":1},"경제교재-23-05":{"f":"신호발송은 정보를 가진 쪽이 자신의 특성을 상대에게 알리려는 행동이다.","w":"정보를 갖지 못한 쪽이 상대의 특성을 가려내려는 행동은 선별이다.","c":"상","v":1},"경제교재-23-08":{"f":"도덕적 해이는 선별로 막을 수 없고 행동에 따라 몫을 달리하는 장치로 줄인다.","w":"선별은 계약 전에 상대의 특성을 가리는 수단이다. 계약 뒤의 감추어진 행동에는 공동보험, 성과급, 감시 같은 유인 장치가 필요하다.","c":"상","v":1},"경제교재-23-10":{"f":"완전히 보상할수록 도덕적 해이가 심해진다.","w":"사고가 나도 손해가 없으므로 예방 노력을 할 이유가 사라진다. 그래서 보험회사는 전부 보상하는 보험을 꺼린다.","c":"상","v":1},"경제교재-23-13":{"f":"의무 가입은 역선택을 해결하는 방법이다.","w":"위험이 높은 사람만 보험에 드는 선택을 막아 위험이 낮은 사람도 포함시키기 때문이다.","c":"상","v":1},"경제교재-24-02":{"f":"회사채이자는 GDP에 포함되지만 국공채이자는 이전지출이어서 포함되지 않는다.","w":"회사채이자는 포함하지만 국공채이자는 생산과 무관한 이전지출이므로 제외된다.","c":"상","v":1},"경제교재-24-04":{"f":"한국 기업이 중국에 공장을 세우고 한국인 노동자를 고용하면 한국의 GNP만 증가하고 GDP는 변하지 않는다.","w":"생산이 중국 영토에서 이뤄지므로 한국의 GDP는 변하지 않고, 한국인이 받는 요소소득만큼 한국의 GNP만 늘어난다. 중국은 GDP가 는다.","c":"상","v":1},"경제교재-24-09":{"f":"실질GDP는 생산지표이고 실질GNI는 소득지표다.","w":"실질GDP는 생산활동의 수준을 재는 생산지표이고, 실질GNI·실질GDI는 생산을 통해 얻은 소득의 실질구매력을 재는 소득지표다.","c":"상","v":1},"경제교재-24-11":{"f":"연평균 5%로 성장하면 70의 법칙에 따라 약 14년 걸린다.","w":"70의 법칙은 70을 성장률로 나눈다. 5%이면 70 ÷ 5 = 14년이다.","c":"상","v":1},"경제교재-24-12":{"f":"GDP 갭을 잠재GDP에서 실제GDP를 뺀 값으로 정의하면 갭이 양(+)일 때 경기는 불황이다.","w":"잠재GDP보다 실제GDP가 작으면 갭이 양(+)이고 이는 불황이다. 호황기에는 실제GDP가 잠재GDP를 넘어 갭이 음(−)이 된다.","c":"상","v":1},"경제교재-24-13":{"f":"총공급이 감소하면 균형국민소득은 감소하고 균형물가는 상승한다.","w":"총공급곡선이 왼쪽으로 이동하면 균형소득은 줄고 균형물가는 올라 스태그플레이션이 나타난다.","c":"상","v":1},"경제교재-24-14":{"f":"MEW는 GDP에 여가의 가치와 가사서비스의 가치를 더하고 공해비용을 뺀다.","w":"MEW는 GDP에 여가의 가치와 가사서비스의 가치를 더하고 공해비용은 뺀다.","c":"상","v":1},"경제교재-24-16":{"f":"수입 소비재 가격 상승은 소비자물가지수에는 반영되지만 GDP 디플레이터에는 반영되지 않는다.","w":"GDP 디플레이터는 국내에서 생산된 재화만 대상이어서 수입품 가격 상승이 반영되지 않는다. 소비자물가지수는 수입 소비재 가격이 반영된다.","c":"상","v":1},"경제교재-25-01":{"f":"고전학파 모형에서 균형국민소득은 공급 측면인 노동시장과 총생산함수에서 결정된다.","w":"고전학파에서는 노동시장의 균형고용량과 총생산함수가 소득을 정하고 총수요는 소득에 영향을 주지 못한다. 총수요 변화는 물가만 움직인다.","c":"상","v":1},"경제교재-25-03":{"f":"물가가 하락해 실질임금이 상승해도 명목임금이 즉시 하락해 초과공급이 곧바로 해소된다.","w":"초과공급이 생기면 명목임금이 즉시 하락해 실질임금이 원래 수준으로 돌아온다. 그래서 비자발적 실업은 사라진다.","c":"상","v":1},"경제교재-25-05":{"f":"고전학파 모형에서 정부지출이 증가하면 이자율이 오르고 민간투자가 줄지만 국민소득은 변하지 않는다.","w":"소득은 공급 측면에서 완전고용수준에 고정되어 있다. 정부지출 증가는 국민저축을 줄여 이자율을 올리고 민간투자를 밀어낸다.","c":"상","v":1},"경제교재-25-07":{"f":"인구 증가로 노동공급이 늘면 균형 실질임금은 하락하고 고용량과 총공급이 증가한다.","w":"노동공급이 늘면 노동시장에서 실질임금이 하락하고 고용량이 늘어 총공급이 증가한다.","c":"상","v":1},"경제교재-25-12":{"f":"고전학파의 총공급곡선은 완전고용산출량에서 수직이다.","w":"물가가 올라도 명목임금이 같이 올라 실질임금과 고용이 변하지 않으므로 총공급곡선은 완전고용산출량에서 수직이다.","c":"상","v":1},"경제교재-25-15":{"f":"z가 커지면 정부지출 1단위 증가에 따른 생산 증가분은 z/(z + 1)로 더 커진다.","w":"dy/dg = z/(z + 1)은 z가 클수록 커진다. 예컨대 z = 9이면 0.9, z = 10이면 약 0.909다.","c":"상","v":1},"경제교재-25-16":{"f":"고전학파 모형에서 노동시장의 보이지 않는 손은 명목임금이고 생산물시장의 보이지 않는 손은 실질이자율이다.","w":"노동시장의 불균형을 해소하는 것은 명목임금이고, 실질임금은 물가에 비례한 명목임금 조정으로 결국 변하지 않는다. 생산물시장은 실질이자율이 조정한다.","c":"상","v":1},"경제교재-26-02":{"f":"케인즈 모형에서 생산물시장의 불균형은 재고 변동에 따른 실질국민소득의 조정으로 해소된다.","w":"이자율이 조정하는 것은 고전학파 모형이다. 케인즈 모형은 가격이 경직적이어서 재고 변동에 따른 생산량(실질소득)의 조정이 불균형을 해소한다.","c":"상","v":1},"경제교재-26-04":{"f":"케인즈 소비함수에서 처분가능소득이 늘어도 한계소비성향은 일정하고 평균소비성향은 감소한다.","w":"한계소비성향은 일정하고 평균소비성향 a/Yd + b가 감소하면서 한계소비성향에 접근하나 같아지지는 않는다.","c":"상","v":1},"경제교재-26-05":{"f":"케인즈 단순모형에서 저축은 소득의 증가함수이고 이자율과 무관하다.","w":"케인즈 모형의 저축은 S = −a + (1 − b)Yd로 소득의 증가함수다. 저축이 이자율에 의존하는 것은 고전학파 모형이다.","c":"상","v":1},"경제교재-26-07":{"f":"균형소득은 1,200이고 완전고용소득이 1,300이면 GDP 갭은 100, 디플레이션갭은 25다.","w":"균형소득은 Y = 100 + 0.75Y − 150 + 150 + 200에서 0.25Y = 300이므로 1,200이다. 소득 차이 100은 GDP 갭이고 디플레이션갭은 이를 승수 4로 나눈 25다.","c":"상","v":1},"경제교재-26-11":{"f":"정액세만 있는 모형에서 투자승수와 정부지출승수는 같다.","w":"투자승수와 정부지출승수는 모두 1/(1 − b)로 항상 같다. 정부지출승수가 큰 것은 조세승수의 절댓값과 비교할 때다.","c":"상","v":1},"경제교재-26-13":{"f":"한계수입성향이 커지면 개방경제의 승수는 작아진다.","w":"수입은 소득 순환에서 빠지는 누출이므로 한계수입성향이 클수록 승수의 분모가 커져 승수가 작아진다. 개방경제 승수는 폐쇄경제 승수보다 작다.","c":"상","v":1},"경제교재-26-15":{"f":"승수효과는 유휴설비가 있는 불황에서 성립하고 완전고용소득에서는 나타나지 않는다.","w":"완전고용에서는 생산능력에 한계가 있어 총수요가 늘어도 생산이 따르지 못한다. 승수효과는 유휴설비와 실업이 있는 불황에서 성립한다.","c":"상","v":1},"경제교재-27-02":{"f":"중고 자동차 거래는 소유권 이전이라 소비에 포함되지 않는다.","w":"중고품 거래는 소유권 이전이다. 구입 가계의 지출만큼 판매 가계의 판매가 상쇄되므로 가계부문 전체의 소비는 변하지 않고 GDP에도 포함되지 않는다.","c":"상","v":1},"경제교재-27-04":{"f":"쿠즈네츠의 장기 시계열 분석에서는 평균소비성향이 소득이 변해도 일정했다.","w":"장기 시계열에서는 평균소비성향이 소득과 관계없이 일정했고 장기소비곡선은 원점을 지나는 직선이었다. 소득이 늘수록 감소하는 것은 단기소비함수다.","c":"상","v":1},"경제교재-27-06":{"f":"상대소득가설에서 소득이 증가할 때는 장기소비곡선을, 소득이 감소할 때는 단기소비곡선을 따라 소비가 조정된다.","w":"소득이 증가할 때는 장기소비곡선을, 소득이 감소할 때는 단기소비곡선을 따라 조정된다. 그래서 소비함수가 비대칭이다.","c":"상","v":1},"경제교재-27-07":{"f":"전시효과는 소비가 타인의 소비에 영향을 받는 상호의존성에서 나온다.","w":"전시효과는 소비가 타인의 소비수준에 영향을 받는 소비의 상호의존성에서 나온다. 독립성은 케인즈 절대소득가설의 가정이다.","c":"상","v":1},"경제교재-27-09":{"f":"항상소득가설에서 일시소득에 대한 한계소비성향은 항상소득에 대한 한계소비성향보다 작다.","w":"임시소득은 대부분 저축되므로 임시소득에 대한 한계소비성향은 작고 항상소득에 대한 한계소비성향이 크다.","c":"상","v":1},"경제교재-27-11":{"f":"항상소득가설에서 단기 한계소비성향은 장기 한계소비성향보다 작다.","w":"단기소비곡선에는 임시소득의 변동이 섞여 있어 기울기가 장기소비곡선보다 완만하다. 단기 한계소비성향이 장기보다 작다.","c":"상","v":1},"경제교재-27-13":{"f":"은퇴 시점이 그대로이고 기대수명이 길어지면 은퇴 이전 근로자의 평균소비성향은 낮아진다.","w":"은퇴 후 소비할 기간이 길어져 근로기에 더 저축해야 하므로 근로기 평균소비성향은 낮아진다.","c":"상","v":1},"경제교재-27-14":{"f":"불규칙보행가설에 따르면 예상치 못한 정책만 소비에 영향을 준다.","w":"합리적 소비자는 예상된 정책을 이미 반영해 소비를 정한다. 소비에 영향을 주는 것은 예상치 못한 정책뿐이다.","c":"상","v":1},"경제교재-28-02":{"f":"정부의 사회간접자본 투자는 국민계정상 투자지출로 분류된다.","w":"정부가 최종생산물을 만들기 위해 사는 자본재는 국민계정상 투자지출로 분류된다. 거시이론의 정부지출은 정부소비지출만 뜻한다.","c":"상","v":1},"경제교재-28-05":{"f":"현재가치법에서 이자율이 오르면 현재가치곡선이 아래로 이동해 최적투자량이 줄어든다.","w":"이자율이 오르면 같은 기대수익의 현재가치가 줄어 현재가치곡선과 순현재가치곡선이 아래로 이동하고 최적투자량이 감소한다.","c":"상","v":1},"경제교재-28-07":{"f":"내부수익률은 시장이자율과 무관하게 비용과 기대수익으로 정해진다.","w":"내부수익률은 투자비용과 기업가의 기대수익으로 정해지는 주관적 수익률이라 시장이자율과 무관하다. 시장이자율과 비교해 투자 여부를 정할 뿐이다.","c":"상","v":1},"경제교재-28-10":{"f":"신고전학파 투자이론에서 기술진보로 자본의 한계생산이 늘어나면 적정자본량이 늘어 투자가 증가한다.","w":"자본의 한계생산곡선이 오른쪽으로 이동해 적정자본량이 늘고 투자가 증가한다.","c":"상","v":1},"경제교재-28-12":{"f":"가속도원리는 설비가 완전가동되는 상황을 전제하며 유휴설비가 있으면 성립하지 않는다.","w":"가속도원리는 기존 설비의 완전가동을 전제한다. 유휴설비가 있으면 신규투자 없이 생산을 늘릴 수 있어 성립하지 않는다.","c":"상","v":1},"경제교재-28-14":{"f":"토빈의 q이론에서 이자율이 하락하면 주가가 상승해 q가 커지고 투자가 늘어난다.","w":"이자율이 하락하면 주가가 상승하고 q가 커져 투자가 늘어난다.","c":"상","v":1},"경제교재-28-15":{"f":"딕싯의 투자옵션모형에 따르면 불확실성이 커질수록 기업은 설비투자를 미룬다.","w":"투자는 비가역적이라 기다리는 옵션의 가치가 불확실성과 함께 커진다. 그래서 불확실성이 크면 설비투자를 미루고 줄인다.","c":"하","v":1},"경제교재-29-02":{"f":"신용카드 사용액은 지급연기수단이므로 통화지표에 포함되지 않는다.","w":"신용카드는 지급을 뒤로 미루는 지급연기수단이어서 통화지표에 포함되지 않는다. 다만 카드가 보급되면 화폐수요는 줄어든다.","c":"상","v":1},"경제교재-29-07":{"f":"민간의 현금예금비율이 상승하면 통화승수는 작아진다.","w":"현금은 예금과 달리 신용창조를 일으키지 못하는 누출이다. 현금예금비율이 오르면 통화승수는 작아진다.","c":"상","v":1},"경제교재-29-09":{"f":"법정지급준비금이 부족한 은행은 증권 매각, 중앙은행·콜시장 차입, 증자로 준비금을 마련하고 대출을 줄여야 한다.","w":"대출을 늘리면 지급준비금이 줄어든다. 증권 매각, 중앙은행 차입, 콜시장 차입, 증자 같은 방법으로 메운다.","c":"상","v":1},"경제교재-29-11":{"f":"재할인율을 인하하면 시중은행의 중앙은행 차입이 늘어 본원통화가 증가한다.","w":"재할인율을 내리면 차입비용이 줄어 시중은행의 차입이 늘고 본원통화와 통화량이 증가한다.","c":"상","v":1},"경제교재-29-13":{"f":"유동성함정에서는 통화량이 늘어도 이자율이 내리지 않아 이자율경로가 작동하지 않는다.","w":"유동성함정에서는 화폐수요가 이자율에 완전탄력적이라 통화량이 늘어도 이자율이 내리지 않는다. 그래서 이자율경로가 막히고 금융정책이 무력해진다.","c":"상","v":1},"경제교재-29-15":{"f":"유동성효과는 통화량 증가가 단기에 이자율을 낮추는 효과다.","w":"유동성효과는 통화량이 예상치 못하게 늘 때 물가가 경직적인 단기에 이자율이 하락하는 효과다. 장기에 명목이자율이 오르는 것은 피셔효과다.","c":"상","v":1},"경제교재-29-16":{"f":"한국은행은 2007년부터 소비자물가 상승률을 물가안정목표 지표로 사용한다.","w":"한국은 2006년까지 근원인플레이션율을 목표로 삼았고 2007년부터 소비자물가 상승률로 바꿨다.","c":"상","v":1},"경제교재-30-01":{"f":"고전학파의 화폐수량설에서 통화량이 늘면 물가가 같은 비율로 오르고 실질국민소득은 변하지 않는다.","w":"유통속도가 일정하고 실질소득이 완전고용 수준에 고정되어 있어 통화량 증가는 물가만 비례해서 올린다. 이것이 화폐의 중립성이다.","c":"상","v":1},"경제교재-30-03":{"f":"보몰-토빈 모형에서 거래적 화폐수요는 이자율의 감소함수다.","w":"이자율이 오르면 화폐 보유의 기회비용이 커져 은행을 더 자주 가고 평균화폐보유액이 줄어든다. 케인즈는 거래적 수요가 이자율과 무관하다고 보았다.","c":"상","v":1},"경제교재-30-05":{"f":"위험중립적인 개인은 시장이자율이 임계이자율보다 높으면 화폐를 모두 채권으로 바꿔 채권만 보유한다.","w":"시장이자율이 임계이자율보다 높으면 채권 보유수익률 r + g가 0보다 커서 채권이 화폐보다 유리하다. 화폐만 보유하는 경우는 시장이자율이 임계이자율보다 낮을 때다.","c":"상","v":1},"경제교재-30-07":{"f":"보몰-토빈 모형에서 화폐수요의 소득탄력성은 0.5다.","w":"평균화폐보유액이 √(bY/(2r))이므로 소득이 1% 늘면 화폐수요는 0.5% 늘어 화폐 보유에 규모의 경제가 있다.","c":"상","v":1},"경제교재-30-09":{"f":"케인즈의 투기적 화폐수요이론에서 개인은 임계이자율을 기준으로 전부 채권 아니면 전부 화폐를 보유하고, 연속적인 곡선은 경제 전체에서만 나타난다.","w":"개인의 수요곡선은 임계이자율에서 끊어지는 계단형이고 개인이 많아지면 수평합이 매끄러운 우하향 곡선이 된다.","c":"상","v":1},"경제교재-30-11":{"f":"프리드먼의 신화폐수량설에서 실질화폐수요는 예상인플레이션율의 감소함수다.","w":"예상인플레이션율이 오르면 화폐의 실질가치 하락이 예상되어 화폐 보유가 줄어든다.","c":"상","v":1},"경제교재-30-13":{"f":"케인즈학파는 금융정책의 중간목표로 통화량보다 이자율이 적절하다고 본다.","w":"케인즈학파는 화폐시장이 불안정하다고 보아 통화량을 목표로 하면 이자율이 급변한다고 한다. 통화량을 중간목표로 삼는 쪽은 통화주의학파다.","c":"상","v":1},"경제교재-30-16":{"f":"화폐수량설이 성립하고 통화량이 6% 늘고 유통속도가 일정할 때 실질GDP가 4% 늘면 물가상승률은 2%다.","w":"물가상승률 = 통화증가율 + 유통속도증가율 − 실질성장률 = 6 + 0 − 4 = 2%다.","c":"상","v":1},"경제교재-31-01":{"f":"투자의 이자율탄력성이 클수록 IS곡선은 완만해진다.","w":"이자율이 조금만 내려도 투자가 크게 늘어 소득이 많이 늘기 때문에 IS곡선의 기울기 절댓값이 작아진다.","c":"상","v":1},"경제교재-31-03":{"f":"LM곡선 위쪽의 점은 화폐시장이 초과공급인 상태다.","w":"같은 소득에서 균형보다 이자율이 높으면 화폐수요가 균형보다 작아 화폐가 남는다. 이때 채권시장은 초과수요다.","c":"상","v":1},"경제교재-31-05":{"f":"물가가 내리면 LM곡선은 오른쪽 아래로 이동한다.","w":"물가가 내리면 실질화폐공급이 늘어 같은 소득에서 균형이자율이 낮아진다.","c":"상","v":1},"경제교재-31-07":{"f":"생산물시장과 화폐시장이 동시에 불균형이면 이자율 조정이 생산량 조정보다 먼저 일어난다.","w":"생산량을 바꾸려면 설비 조정에 시간과 비용이 들어 화폐시장의 이자율 조정이 더 빠르다.","c":"상","v":1},"경제교재-31-09":{"f":"유동성함정에서는 구축효과가 없어 재정정책이 소득을 늘리는 효과가 가장 크다.","w":"LM이 수평이라 정부지출이 늘어도 이자율이 오르지 않고 민간투자가 줄지 않는다. 힘을 잃는 쪽은 통화정책이다.","c":"상","v":1},"경제교재-31-11":{"f":"먼델-토빈효과는 예상인플레이션이 명목이자율에 일부만 반영돼 실질이자율이 내린다고 본다.","w":"예상인플레이션이 명목이자율에 전부 반영된다고 보는 것은 고전학파의 피셔효과다.","c":"상","v":1},"경제교재-31-12":{"f":"IS: Y = 2,220 − 60r, LM: Y = 400 + 200r이면 균형이자율은 7%이고 균형소득은 1,800이다.","w":"두 식을 같게 놓으면 2,220 − 60r = 400 + 200r에서 260r = 1,820이므로 r = 7이다. Y = 400 + 1,400 = 1,800이다.","c":"상","v":1},"경제교재-31-15":{"f":"소비와 투자가 이자율에 반응하지 않으면 통화정책보다 재정정책이 총수요관리에 더 효과적이다.","w":"IS가 수직이어서 통화량을 늘려 이자율을 내려도 총수요가 변하지 않는다. 재정정책은 구축효과 없이 승수만큼 소득을 늘린다.","c":"상","v":1},"경제교재-32-02":{"f":"정부가 중앙은행에서 차입해 지출하면 본원통화가 늘어 통화량이 증가하므로 구축효과가 작거나 나타나지 않는다.","w":"재정지출로 IS가 오른쪽으로 이동하는 동시에 통화량 증가로 LM도 오른쪽으로 이동해 이자율 상승이 억제된다. 이런 경우를 정책혼합이라 한다.","c":"상","v":1},"경제교재-32-04":{"f":"재정적 견인은 회복기에 소득이 늘면서 조세수입도 늘어 총수요 증가가 억제되고 완전고용에 이르지 못하는 현상이다.","w":"이자율 상승으로 민간투자가 줄어드는 현상은 구축효과다. 재정적 견인은 자동안정화장치의 부작용이다.","c":"상","v":1},"경제교재-32-06":{"f":"화폐수요의 이자율탄력성이 클수록 확대재정정책의 구축효과는 작아진다.","w":"탄력성이 크면 LM이 완만해 소득이 늘어도 이자율이 적게 오르므로 투자 감소가 작다. 유동성함정에서는 구축효과가 0이다.","c":"상","v":1},"경제교재-32-08":{"f":"고전학파 모형에서 정부지출이 늘면 이자율 상승으로 투자가 줄고 저축이 늘어 소비도 줄며, 정부지출 증가분이 투자와 소비 감소분의 합과 같아진다.","w":"이자율이 오르면 저축이 늘고 같은 소득에서 소비가 줄어든다. 투자 감소분과 소비 감소분의 합이 정부지출 증가분이어서 총수요는 변하지 않는다.","c":"상","v":1},"경제교재-32-10":{"f":"유동성제약이 있는 가계가 많으면 감세가 소비를 늘리므로 리카도의 등가성정리가 성립하기 어렵다.","w":"빌릴 수 없는 가계는 감세로 늘어난 소득을 소비에 쓰므로 미래 증세를 예상해 저축한다는 가정이 깨진다.","c":"상","v":1},"경제교재-32-11":{"f":"케인즈학파는 가파른 IS와 완만한 LM을 가정하므로 구축효과가 작아 재정정책의 효과가 크다고 본다.","w":"투자가 이자율에 둔감해 IS가 가파르고 화폐수요가 이자율에 민감해 LM이 완만하면 소득이 늘어도 이자율이 적게 오른다. 통화주의학파는 반대로 구축효과가 커 재정정책이 약하다고 본다.","c":"상","v":1},"경제교재-32-13":{"f":"긴축재정정책과 확대금융정책을 함께 쓰면 균형소득은 그대로이고 이자율만 내린다.","w":"IS가 왼쪽으로, LM이 오른쪽으로 이동해 소득 변화는 상쇄되고 이자율은 이중으로 하락한다. 이자율이 그대로이고 소득만 느는 조합은 확대재정과 확대금융이다.","c":"상","v":1},"경제교재-32-15":{"f":"IS: Y = 1,200 − 60r, 실질화폐수요 Y − 60r, 물가 2에서 통화량이 800에서 1,200으로 늘면 균형소득은 100 증가한다.","w":"M = 800이면 LM은 60r = Y − 400이고 IS와 연립하면 Y = 800이다. M = 1,200이면 60r = Y − 600이어서 Y = 900이다.","c":"상","v":1},"경제교재-33-01":{"f":"총수요곡선이 우하향하는 이유는 이자율효과, 실질자산효과, 경상수지효과 때문이고 상대가격 변화 때문이 아니다.","w":"물가 하락은 모든 재화의 가격이 함께 내리는 것이어서 상대가격이 변하지 않는다.","c":"상","v":1},"경제교재-33-03":{"f":"피구효과는 물가 하락으로 실질자산이 늘어 소비가 증가하고 IS곡선이 오른쪽으로 이동하는 효과다.","w":"LM을 이동시키는 것은 이자율효과다. 피구효과는 생산물시장에서 소비를 늘린다.","c":"상","v":1},"경제교재-33-05":{"f":"화폐수요의 이자율탄력성이 클수록 총수요곡선은 가팔라진다.","w":"탄력성이 크면 LM이 완만해 물가 하락으로 LM이 이동해도 이자율이 조금만 내리므로 투자 증가폭과 총수요 증가폭이 작다.","c":"상","v":1},"경제교재-33-07":{"f":"케인즈 단순모형에서 확대금융정책은 총수요곡선을 움직이지 못한다.","w":"유동성함정이면 이자율이 내리지 않고 독립투자만 있으면 이자율이 내려도 투자가 변하지 않아 총수요가 그대로다.","c":"상","v":1},"경제교재-33-09":{"f":"고전학파의 총공급곡선은 완전고용국민소득에서 수직선이다.","w":"명목임금과 물가가 완전신축적이어서 물가가 올라도 실질임금이 곧 회복되고 고용과 생산이 그대로다.","c":"상","v":1},"경제교재-33-11":{"f":"노동자들의 예상물가가 오르면 단기 총공급곡선은 왼쪽으로 이동한다.","w":"예상실질임금이 내려 노동공급이 줄어 같은 물가에서 고용과 생산이 줄어든다.","c":"상","v":1},"경제교재-33-13":{"f":"가격을 바꾸지 않는 기업의 비중이 클수록 단기 총공급곡선은 완만해진다.","w":"가격을 못 바꾸는 기업이 많으면 총수요 증가에 가격보다 생산량으로 대응하는 기업이 많아 물가는 덜 오르고 소득이 더 늘어난다.","c":"상","v":1},"경제교재-33-16":{"f":"φπ가 커지면 (Y, π) 평면의 총수요곡선은 더 완만해진다.","w":"Y = Y* − αr과 결합하면 총수요곡선의 기울기 절댓값이 (1 + αφY)/(αφπ)여서 φπ가 클수록 작아진다. 인플레이션에 금리가 크게 반응하면 같은 물가 변화에 소득이 더 크게 줄기 때문이다.","c":"상","v":1},"경제교재-34-01":{"f":"고용률은 취업자 수를 생산가능인구로 나눈 값이다.","w":"경제활동인구로 나누면 취업률이다. 고용률은 비경제활동인구를 분모에 포함해 실질적 고용창출력을 보여 준다.","c":"상","v":1},"경제교재-34-03":{"f":"직장폐쇄로 일하지 못하고 쉬는 근로자는 일시휴직자로 취업자에 포함된다.","w":"직업이나 사업체가 있으나 조사 기간에 질병·휴가·노동쟁의 등으로 일하지 못한 사람은 취업자다.","c":"상","v":1},"경제교재-34-05":{"f":"군 의무복무자와 교도소 수감자는 경제활동 조사 대상에서 제외되므로 비경제활동인구에도 포함되지 않는다.","w":"비경제활동인구는 조사 대상인 15세 이상 중 일할 의사나 능력이 없는 사람이다.","c":"상","v":1},"경제교재-34-07":{"f":"실업보험이 확대되면 자연실업률은 높아진다.","w":"복지가 강화되면 구직 노력이 약해지고 실업 기간이 길어져 자연실업률이 상승한다.","c":"상","v":1},"경제교재-34-09":{"f":"이 경우 실업률은 6%다.","w":"실직자 수와 구직자 수가 같으므로 0.05E = 47에서 E = 940만 명이고 U = 1,000 − 940 = 60만 명이므로 실업률은 6%다.","c":"상","v":1},"경제교재-34-10":{"f":"오쿤의 법칙에 따르면 실업률이 1%p 오르면 실질GDP는 잠재수준에 비해 약 2.5% 줄어든다.","w":"오쿤의 법칙은 실업률과 산출량 사이의 음의 관계다. 미국의 경험으로 계수는 약 2.5다.","c":"상","v":1},"경제교재-34-12":{"f":"고전학파는 비자발적 실업의 대책으로 명목임금 하락을 막는 제도적 요인의 제거가 적절하다고 본다.","w":"고전학파에서 비자발적 실업은 임금 경직을 낳는 제도 때문에 생기므로 총수요정책이 아니라 제도를 고쳐야 한다.","c":"상","v":1},"경제교재-34-14":{"f":"내부자-외부자모형에서 내부자의 교섭력이 임금을 높게 유지하면 외부자는 일자리를 얻지 못해 실업이 지속된다.","w":"취업자가 자기 이익을 위해 높은 임금을 관철하면 낮은 임금에도 일하려는 외부자가 고용되지 못한다.","c":"상","v":1},"경제교재-35-01":{"f":"소비자물가지수는 기준연도 거래량을 가중치로 쓰는 라스파이레스 방식으로 작성한다.","w":"파셰 방식은 GDP디플레이터에 쓰인다. 소비자물가지수와 생산자물가지수는 라스파이레스 방식이다.","c":"상","v":1},"경제교재-35-03":{"f":"GDP디플레이터는 국내에서 생산된 최종생산물만 대상으로 하므로 수입품 가격의 변동을 반영하지 못한다.","w":"소비자물가지수는 수입 소비재를 포함하지만 GDP디플레이터는 포함하지 않는다.","c":"상","v":1},"경제교재-35-05":{"f":"공급견인 인플레이션에서는 총수요를 늘리면 물가가 더 오르고 줄이면 소득이 더 줄어드는 딜레마가 생긴다.","w":"총공급곡선이 왼쪽으로 이동한 상태여서 총수요 조절만으로는 물가와 소득을 함께 잡을 수 없다.","c":"상","v":1},"경제교재-35-08":{"f":"케인즈학파는 확대재정정책이 일시적인 인플레이션을 일으킬 뿐 지속되는 인플레이션은 일으키지 않는다고 본다.","w":"지속되는 인플레이션은 지속적인 정부지출 증가가 필요한데 예산제약이 이를 막는다고 본다. 지속적 인플레이션을 화폐 증가의 결과로 보는 쪽은 통화주의학파다.","c":"상","v":1},"경제교재-35-10":{"f":"이 경우 세후 실질이자율은 1%다.","w":"명목이자율은 12%이고 세후 명목이자율은 12 × 0.75 = 9%이므로 세후 실질이자율은 9 − 8 = 1%다.","c":"상","v":1},"경제교재-35-12":{"f":"예상된 인플레이션에서도 구두창비용과 메뉴비용이 발생한다.","w":"명목이자율이 올라 화폐 보유의 기회비용이 커지고 가격표를 바꾸는 비용이 드는 것은 예상 여부와 무관하다.","c":"상","v":1},"경제교재-35-14":{"f":"예상치 못한 인플레이션은 채무자에게 이익을 주고 채권자에게 손해를 준다.","w":"실질이자율이 예상보다 낮아져 갚을 돈의 실질가치가 줄어들기 때문이다.","c":"상","v":1},"경제교재-35-16":{"f":"이 경우 실질이자율은 7%다.","w":"인플레이션율은 6 − 3 = 3%이고 실질이자율은 명목이자율에서 인플레이션율을 뺀 10 − 3 = 7%다.","c":"상","v":1},"경제교재-36-01":{"f":"필립스가 처음 발견한 곡선은 명목임금상승률과 실업률 사이의 음의 관계를 나타낸다.","w":"물가상승률과 실업률의 관계로 바꾼 것은 립시의 필립스곡선이다. 노동생산성증가율이 0이면 명목임금상승률을 물가상승률로 대체할 수 있다.","c":"상","v":1},"경제교재-36-03":{"f":"총수요곡선이 오른쪽으로 이동하면 필립스곡선 위의 좌상방 점으로 이동하고 필립스곡선 자체는 이동하지 않는다.","w":"필립스곡선 자체를 이동시키는 것은 총공급곡선의 이동이다.","c":"상","v":1},"경제교재-36-05":{"f":"실업률이 낮은 구간에서는 필립스곡선이 가파르다.","w":"소득이 높은 구간에서는 총공급곡선이 가팔라 실업률을 더 낮추려면 감수해야 할 인플레이션이 커진다.","c":"상","v":1},"경제교재-36-07":{"f":"예상인플레이션율이 오르면 단기 필립스곡선이 위로 이동하고 장기 필립스곡선은 이동하지 않는다.","w":"장기 필립스곡선의 위치는 자연실업률이 정한다. 예상인플레이션 상승은 단기 총공급곡선을 왼쪽으로 옮겨 단기 필립스곡선만 움직인다.","c":"상","v":1},"경제교재-36-09":{"f":"합리적 기대에서도 예상치 못한 확장정책을 쓰면 π > πe가 되어 단기 필립스곡선이 우하향한다.","w":"단기 필립스곡선이 수직이 되는 것은 정책이 예상된 경우다.","c":"상","v":1},"경제교재-36-11":{"f":"고통 없는 디스인플레이션은 정책이 미리 알려지고 신뢰를 얻어 기대가 즉시 조정되는 합리적 기대에서만 가능하다.","w":"적응적 기대에서는 기대가 과거 인플레이션을 따라 천천히 조정되어 디스인플레이션에 실업 증가가 따른다.","c":"상","v":1},"경제교재-36-13":{"f":"이 경우 희생비율은 2다.","w":"실업률 4%p 상승은 GDP를 4 × 2.5 = 10% 줄이므로 희생비율은 10/5 = 2다.","c":"상","v":1},"경제교재-36-16":{"f":"정부가 개입하지 않으면 장기에는 생산요소 가격이 내려 총공급곡선이 다시 오른쪽으로 이동하고 원래 균형으로 돌아온다.","w":"실업이 오래되면 노동자가 낮은 임금에 합의해 생산비용이 내리므로 공급충격이 지속적인 인플레이션의 원천이 될 수 없다. 대가로 그동안 불황과 실업을 감내해야 한다.","c":"상","v":1},"경제교재-37-02":{"f":"고전학파 모형에서 통화량이 늘면 물가가 비례해 오르고 실질이자율은 그대로이며 명목이자율만 오른다.","w":"실질이자율은 저축과 투자가 같아지는 곳에서 정해지는 실질변수라 통화량과 무관하다. 명목이자율만 물가상승분만큼 오르는 것이 피셔효과다.","c":"상","v":1},"경제교재-37-03":{"f":"케인즈 단순모형은 투자를 독립투자로 두므로 이자율이 내려가도 투자가 늘지 않아 금융정책은 소득에 효과가 없다.","w":"독립투자수요 가정으로 총수요곡선이 수직선이 된다. 유동성함정이면 이자율조차 내려가지 않는다.","c":"상","v":1},"경제교재-37-04":{"f":"케인즈학파는 IS가 가파르고 LM이 완만하므로 재정정책이 금융정책보다 효과가 크다고 주장한다.","w":"가파른 IS와 완만한 LM에서는 재정지출 증가가 이자율을 조금만 올려 구축효과가 작고, 통화량 증가는 이자율을 조금만 내리며 투자도 둔감해 효과가 작다.","c":"상","v":1},"경제교재-37-06":{"f":"통화주의학파는 금융정책의 효과가 커도 정책시차가 길고 가변적이므로 재량보다 미리 공표한 준칙에 따라 통화량을 늘려야 한다고 주장한다.","w":"시차 때문에 재량정책이 오히려 경기변동의 진폭을 키운다고 본다. k% 준칙이 그 사례다.","c":"상","v":1},"경제교재-37-10":{"f":"새고전학파에서도 예상하지 못한 통화량 증가는 실제물가를 예상물가보다 높여 단기 산출량을 자연산출량보다 늘린다. 무력한 것은 예상된 정책이다.","w":"루카스 공급함수에서 산출량은 실제물가가 예상물가를 웃돌 때 자연산출량을 넘는다. 다만 거듭하면 민간이 속지 않고 정책 신뢰도 무너진다.","c":"상","v":1},"경제교재-37-12":{"f":"새케인즈학파는 정책무력성이 합리적 기대가 아니라 가격변수의 신축성 가정에서 나온다고 보고, 가격이 경직적이면 합리적 기대 아래에서도 예상된 정책이 단기에 유효하다고 본다.","w":"새케인즈학파는 합리적 기대를 방법론으로 받아들이되 임금과 물가의 경직성을 미시적으로 설명한다.","c":"상","v":1},"경제교재-37-14":{"f":"효율성임금 이론에서 기업은 임금 인하가 생산성 하락으로 이어질 것을 우려해 초과공급이 있어도 시장임금보다 높은 효율성임금을 유지한다.","w":"높은 임금은 역선택과 태만을 막고 이직을 줄여 생산성을 높인다. 그 결과 실질임금이 경직되고 비자발적 실업이 생긴다.","c":"상","v":1},"경제교재-37-16":{"f":"래퍼곡선에서 세율이 조세수입을 극대화하는 세율보다 높은 구간에서는 세율을 올릴수록 조세수입이 줄어든다.","w":"세율이 너무 높으면 근로의욕이 꺾여 소득 자체가 줄고 지하경제와 해외로 소득이 빠져나가 조세수입이 감소한다.","c":"상","v":1},"경제교재-38-02":{"f":"경기변동은 주기와 진폭이 매번 다르게 나타나는 비주기적 현상이다.","w":"제2차 세계대전 전후의 경기변동도 서로 다른 주기를 가진다. 다만 한번 시작되면 상당 기간 지속되는 경향은 있다.","c":"상","v":1},"경제교재-38-03":{"f":"경기순환에서 정점과 정점 사이의 길이를 주기라 하고, 저점에서 정점까지의 높이를 진폭이라 한다.","w":"주기는 시간의 길이이고 진폭은 변동의 높이다.","c":"상","v":1},"경제교재-38-06":{"f":"경기선행지수는 경기에 앞서 변해 장래 경기를 예측하는 데 쓰고, 동행지수는 현재의 경기 동향을 보여 준다.","w":"후행지수는 경기보다 늦게 변해 이미 지나간 경기 상황을 확인하는 데 쓴다.","c":"상","v":1},"경제교재-38-08":{"f":"루카스의 화폐적 균형경기변동이론에서는 예상치 못한 통화량 변화가 산출량을 바꾸므로 화폐의 중립성이 성립하지 않는다.","w":"예상치 못한 통화량 증가가 기업의 물가 인식을 흐려 생산을 늘리게 한다. 다만 합리적 기대 때문에 효과는 일시적이다.","c":"상","v":1},"경제교재-38-10":{"f":"실물경기변동이론에서 경기침체기의 실업은 노동의 기간 간 대체에 따른 자발적 실업이다.","w":"가격이 신축적이라 노동시장도 청산되므로 모든 실업을 자발적 실업으로 본다.","c":"상","v":1},"경제교재-38-12":{"f":"실물경기변동이론은 생산이 늘어 화폐수요가 커지면 중앙은행이 통화를 공급하므로 생산이 통화량을 바꾼다는 역의 인과관계로 설명한다.","w":"통화량과 생산이 같이 움직이는 현상은 인정하되 화폐는 중립적이라고 본다.","c":"상","v":1},"경제교재-38-14":{"f":"실물적 균형경기변동이론은 경기변동을 자연산출량 자체가 변동하는 현상으로 본다.","w":"실제산출량이 자연산출량에서 이탈한다고 보는 쪽은 화폐적 균형경기변동이론과 새케인즈학파다. 실물적 이론은 가격이 신축적이라 산출은 항상 자연산출량이다.","c":"상","v":1},"경제교재-38-16":{"f":"정치적 경기순환이론에 따르면 집권당은 선거 직전에 통화량을 늘리거나 감세해 경기를 띄우고 선거 직후에는 인플레이션을 막으려고 긴축한다.","w":"정치인은 표를 얻으려 선거 전에 실업을 줄이는 쪽을 택하므로 선거 전에는 경기가 확장되고 선거 뒤에는 위축된다.","c":"상","v":1},"경제교재-39-02":{"f":"이 경제의 균제상태 1인당 자본은 황금률 수준의 1인당 자본보다 크다.","w":"0.4k^0.2 = 0.2k에서 k = 2^(5/4) ≈ 2.38이다. 황금률은 0.2k^(−0.8) = 0.2에서 k = 1이므로 과다자본이며 황금률 저축률은 자본소득분배율 0.2다.","c":"상","v":1},"경제교재-39-04":{"f":"솔로우 모형에서 저축률이 오르면 균제상태의 1인당 소득 수준만 높아지고 장기 성장률은 바뀌지 않는다.","w":"새 균제상태에 도달하면 총생산 증가율은 다시 인구증가율과 같아진다. 저축률 상승은 일시적 성장률 상승과 수준효과만 낳는다.","c":"상","v":1},"경제교재-39-05":{"f":"솔로우 모형에서 인구증가율이 낮아지면 균제상태의 1인당 소득은 높아지지만 총생산 증가율은 인구증가율과 같으므로 오히려 낮아진다.","w":"(n + δ)k 직선의 기울기가 작아져 1인당 자본이 늘어난다. 그래도 균제상태의 경제성장률은 n과 일치한다.","c":"상","v":1},"경제교재-39-07":{"f":"해로드-도마 모형에서 자본계수가 3이고 인구증가율이 5%이면 균형성장을 위한 저축률은 15%다.","w":"균형성장은 s/v = n일 때 가능하므로 s = v × n = 3 × 5% = 15%다.","c":"상","v":1},"경제교재-39-09":{"f":"1인당 자본이 황금률 수준보다 적을 때 저축률을 올리면 1인당 소비는 먼저 줄었다가 1인당 자본이 늘면서 점차 늘어나 처음 균제상태보다 커진다.","w":"저축률이 오르는 순간 소비 몫이 줄어든다. 현재세대의 희생으로 미래세대의 후생이 늘어 세대 간 재분배 효과가 생긴다.","c":"상","v":1},"경제교재-39-11":{"f":"자본이 황금률 수준보다 많은 경제가 저축률을 황금률 수준으로 내리면 1인당 소비는 즉시 늘고 이후 줄어들지만 처음 균제상태보다는 크다.","w":"저축률을 내리는 순간 소비 몫이 커진다. 이후 1인당 자본이 줄며 소비가 줄지만 황금률 균제상태의 소비가 최대이므로 처음보다 크다.","c":"상","v":1},"경제교재-39-12":{"f":"이 경제에서 노동소득분배율은 0.4다.","w":"10 = 3 + 10α + 5(1 − α)에서 5α = 2이므로 α = 0.4이고 자본소득분배율이 0.6이다.","c":"상","v":1},"경제교재-39-15":{"f":"루카스 모형에서 인적자본은 지식을 체화한 노동력이므로 경합성과 배제성을 가진다.","w":"숙련노동자는 자동차와 컴퓨터를 동시에 만들 수 없어 경합적이고 지식이 있어도 체화하지 않으면 인적자본이 되지 않아 배제성이 있다.","c":"상","v":1},"경제교재-39-16":{"f":"AK 모형에서는 저축률이 오르면 1인당 성장률 sA − (n + δ)가 영구히 높아진다.","w":"자본의 한계생산이 체감하지 않으므로 저축을 통한 자본축적이 지속적인 성장을 낳는다. 솔로우 모형과 달리 저축률은 성장효과를 갖는다.","c":"상","v":1},"경제교재-40-02":{"f":"교역조건이 A국의 국내상대가격비와 같아지면 A국은 무역으로 이득이 없고 이득은 모두 B국에 돌아간다.","w":"A국은 교역해도 국내에서 바꾸는 비율과 같은 비율로 바꾸므로 소비가능집합이 넓어지지 않는다. 이득은 교역조건이 상대국의 기회비용에 가까울수록 자국에 많이 돌아온다.","c":"상","v":1},"경제교재-40-06":{"f":"헥셔-올린 정리는 생산기술이 같다고 가정하고 요소부존도의 차이와 재화 간 요소집약도의 차이가 비교우위의 원인이라고 설명한다.","w":"노동생산성 차이에서 비교우위를 찾는 것은 리카도 모형이다. 헥셔-올린 모형은 그 차이가 왜 생기는지 설명하지 못한 점을 보완했다.","c":"상","v":1},"경제교재-40-07":{"f":"요소가 국가 간에 이동하지 못해도 상품이 자유롭게 이동하면 두 나라의 요소가격이 같아지며 무역이 요소를 간접적으로 교환하는 효과를 낸다.","w":"상품가격이 같아지므로 그것을 만드는 데 드는 요소의 가격도 같아진다는 것이 요소가격균등화 정리다.","c":"상","v":1},"경제교재-40-09":{"f":"재화 가격이 일정할 때 자본 부존량이 늘면 자본집약재의 생산은 늘고 노동집약재의 생산은 줄어든다.","w":"늘어난 자본을 쓰려면 자본집약재를 늘려야 하고 이에 필요한 노동은 노동집약재에서 빠져나와야 한다. 천연자원 발견으로 제조업이 위축되는 화란병이 사례다.","c":"상","v":1},"경제교재-40-11":{"f":"레온티에프는 자본이 풍부한 미국이 오히려 노동집약재를 수출한다는 결과를 얻었고, 이는 헥셔-올린 정리와 모순되어 레온티에프의 역설이라 불린다.","w":"원인으로 미국의 높은 노동생산성, 요소집약도 역전, 인적자본, 무역장벽 등이 거론된다.","c":"상","v":1},"경제교재-40-13":{"f":"제품수명주기이론에서 제품이 표준화 단계에 이르면 생산이 임금이 낮은 개발도상국으로 옮겨 가 개발도상국이 선진국으로 수출하게 된다.","w":"신제품 단계에는 개발국이 생산·수출하고 성숙 단계에는 다른 선진국도 생산하며 표준화되면 인건비가 중요해진다.","c":"상","v":1},"경제교재-40-14":{"f":"대국이 수입품에 관세를 부과하면 수입품의 국제가격이 내려 교역조건이 개선되지만 소국은 국제가격에 영향을 줄 수 없어 교역조건이 변하지 않는다.","w":"교역조건은 국내가격이 아니라 국제가격으로 잰다. 대국의 수입 감소만 국제시장에 초과공급을 만든다.","c":"상","v":1},"경제교재-40-16":{"f":"궁핍화 성장은 수출품에 대한 외국 수요가 비탄력적일수록 일어나기 쉽다.","w":"수출이 늘 때 외국 수요가 가격에 둔감하면 수출품 가격이 크게 떨어져 교역조건이 악화된다. 수출편향적 성장과 높은 수출의존도도 조건이다.","c":"상","v":1},"경제교재-41-02":{"f":"외국의 수입수요의 가격탄력성이 클수록 대국의 최적관세율은 낮아진다.","w":"외국의 수입수요가 탄력적이면 관세로 국제가격을 떨어뜨리기 어렵다. 가격탄력성이 무한대인 소국에서는 최적관세율이 0이다.","c":"상","v":1},"경제교재-41-05":{"f":"이 경우 후생손실은 15,000이고 30,000은 수입업자에게 돌아가는 쿼터 지대다.","w":"Qd − Qs = 300에서 국내가격은 400이고 공급은 200에서 300으로 100 늘고 수요는 800에서 600으로 200 준다. 손실은 ½ × 100 × 100 + ½ × 100 × 200 = 15,000이고 지대는 100 × 300 = 30,000이다.","c":"상","v":1},"경제교재-41-08":{"f":"수출자율규제에서는 수출국이 수출권을 가지므로 높은 가격으로 수출해 얻는 이윤이 수출국의 수출업자에게 돌아간다.","w":"수입수량할당제에서는 수입허가권을 수입국이 갖지만 수출자율규제에서는 수출국이 수출권을 갖는다. 그래서 수입국의 후생손실이 더 크다.","c":"상","v":1},"경제교재-41-09":{"f":"소국이 수출보조금을 지급해도 교역조건은 변하지 않지만 생산과 소비가 왜곡되어 사회후생은 줄어든다.","w":"국내가격이 보조금만큼 올라 소비자잉여가 줄고 생산자잉여가 늘지만 보조금 지출이 그 순이득보다 크다. 대국은 교역조건 악화까지 겹쳐 손실이 더 크다.","c":"상","v":1},"경제교재-41-11":{"f":"투입재에 대한 관세율이 낮을수록 최종재의 실효보호율은 명목관세율보다 더 커진다.","w":"투입재 관세는 국내 생산자의 비용을 올려 부가가치를 줄이므로 보호 효과를 깎는다.","c":"상","v":1},"경제교재-41-14":{"f":"무역전환효과는 수입선이 저비용의 역외국에서 고비용의 역내국으로 바뀌어 자원배분의 효율성을 떨어뜨리는 효과다.","w":"관세동맹 회원국에는 관세가 없어져 역외의 더 효율적인 생산자 대신 역내의 비효율적인 생산자에게서 수입하게 된다.","c":"상","v":1},"경제교재-41-16":{"f":"GATT의 최혜국대우원칙은 두 나라가 맺은 관세인하의 혜택을 다른 모든 회원국에도 적용해야 한다는 원칙이고, 수입품을 국산품과 동등하게 취급하라는 것은 내국민대우원칙이다.","w":"최혜국대우는 회원국 사이의 차별을 막고 내국민대우는 수입품과 국산품 사이의 차별을 막는다.","c":"상","v":1},"경제교재-42-01":{"f":"환율이 오르면 수출품의 달러가격이 내리지만 수입품의 달러가격은 변하지 않아 수출품 가격만으로 교역조건이 악화된다.","w":"교역조건은 국제가격으로 잰다. 환율 상승으로 오르는 것은 원화표시 수입품 가격이다.","c":"상","v":1},"경제교재-42-03":{"f":"절대적 구매력평가가 성립하면 실질환율은 1이다.","w":"e = P/P*이면 q = eP*/P = 1이다. 실질환율이 일정하므로 순수출도 변하지 않는다.","c":"상","v":1},"경제교재-42-06":{"f":"명목 GDP 대 구매력평가 기준 GDP의 비율이 1보다 큰 나라는 물가수준이 미국보다 높다.","w":"달러표시 명목 GDP를 구매력평가 GDP로 나눈 값은 시장환율에 대한 구매력평가환율의 비율이므로 상대물가수준이다. 1보다 크면 물가가 높고 1이면 미국과 같다.","c":"상","v":1},"경제교재-42-09":{"f":"무위험 이자율평가가 성립하면 고금리 통화는 저금리 통화에 비해 선물환 디스카운트 상태에 있다.","w":"선물환율/현물환율 = (1 + i)/(1 + i*)이므로 국내 이자율이 높으면 외화의 선물환율이 현물환율보다 높고 이는 자국통화가 선물환 디스카운트라는 뜻이다.","c":"상","v":1},"경제교재-42-12":{"f":"고정환율제에서 국제수지 흑자가 나면 환율 하락을 막으려고 외환을 사야 하므로 외환보유고와 본원통화가 늘어난다.","w":"외환 매입 대금이 시중에 풀리므로 통화량이 국제수지에 따라 자동으로 변한다. 그래서 고정환율제에서는 통화정책의 독립성이 제약된다.","c":"상","v":1},"경제교재-42-14":{"f":"브레튼우즈체제는 미국 달러를 기축통화로 하고 달러에 금태환의무를 부여한 금환본위제로 조정가능 고정환율제도였다.","w":"각국 통화와 달러의 환율을 고정하고 달러만 금과 연결했다. 달러 공급을 늘리려면 미국의 적자가 필요하다는 트리핀 딜레마가 한계였고 1971년 닉슨 선언으로 붕괴했다.","c":"상","v":1},"경제교재-42-16":{"f":"구매력평가설은 자유무역 아래 경상수지의 변동에 초점을 두고 자본이동과는 무관하며 이자율평가설이 자본이동과 자본수지에 초점을 둔다.","w":"구매력평가설은 생산물시장의 일물일가를 이자율평가설은 금융시장의 일물일가를 바탕으로 한다.","c":"상","v":1},"경제교재-43-02":{"f":"1년 이상 외국에서 일해 그 나라 거주자가 된 근로자의 송금은 이전소득수지에 기록되고 1년 미만 일하고 받은 급료가 본원소득수지에 기록된다.","w":"본원소득수지는 급료·임금(1년 미만 근로)과 투자소득을 다룬다. 거주자가 된 근로자의 송금과 무상원조·국제기구 출연금은 대가 없는 이전이다.","c":"상","v":1},"경제교재-43-04":{"f":"직접투자는 투자기업에 대해 10% 이상의 의결권을 보유하는 직접투자관계에서 기록된다.","w":"1차적 직접투자관계는 10% 이상이며 연쇄출자 등을 통한 간접적 관계와 동료기업 간 투자도 포함한다.","c":"상","v":1},"경제교재-43-06":{"f":"민간저축과 투자가 변하지 않을 때 재정적자가 늘어나면 국민저축이 줄어 경상수지가 악화된다.","w":"경상수지는 국민저축 − 투자이고 정부저축이 줄면 국민저축이 준다. 재정적자와 경상수지 적자가 함께 나타나는 것이 쌍둥이 적자다.","c":"상","v":1},"경제교재-43-08":{"f":"J곡선효과는 단기에 마샬-러너조건이 성립하지 않기 때문에 환율 상승 직후 경상수지가 악화되었다가 시간이 지나 개선되는 현상이다.","w":"가격 변화는 즉시 나타나지만 수출입 물량은 시차를 두고 변하고 불완전한 환율전가도 영향을 준다.","c":"상","v":1},"경제교재-43-11":{"f":"자본이동이 완전한 소국이 변동환율제에서 확대재정정책을 쓰면 자본유입으로 환율이 하락해 순수출이 감소하므로 소득은 변하지 않는다.","w":"재정확대로 오른쪽으로 이동한 IS가 순수출 감소만큼 다시 왼쪽으로 돌아온다. 국내 이자율은 세계이자율에 묶여 있어 이자율도 불변이다.","c":"상","v":1},"경제교재-43-13":{"f":"수출이 줄어 IS가 왼쪽으로 이동하면 환율이 상승해 순수출이 원래대로 돌아오므로 소득은 변하지 않는다.","w":"소득은 LM곡선과 세계이자율에서 정해지므로 IS 이동은 환율만 바꾼다. 소비와 투자도 변하지 않아 순수출도 처음 수준이다.","c":"상","v":1},"경제교재-43-14":{"f":"BP곡선은 해외이자율이 오르면 위쪽으로 이동한다.","w":"해외이자율 상승은 자본유출을 일으킨다. 같은 소득에서 국제수지가 균형이 되려면 국내이자율이 더 높아야 하므로 BP는 위쪽(왼쪽)으로 이동한다.","c":"상","v":1},"경제교재-43-15":{"f":"틴버겐의 법칙에 따르면 독립된 정책목표가 n개이면 정책수단도 n개 필요하다.","w":"대내균형과 대외균형이라는 두 목표에는 두 개의 독립된 정책수단이 필요하다. 먼델은 고정환율제에서 재정과 금융정책을 스완은 총수요관리와 환율정책을 할당했다.","c":"상","v":1},"공인노2017_26-101":{"w":"④가 틀리다. 팔리지 않고 남은 재고는 기업이 스스로 사들인 것으로 보아 재고투자(I)에 들어가므로 올해 GDP에 포함된다.\n① 총지출 C+I+G = Y-(X-M)이다. 무역수지 X-M이 적자(음수)이면 총지출이 GDP보다 크다. 맞다.\n② GDP가 줄어도 수입이 더 크게 줄면 X-M은 흑자일 수 있다. 맞다.\n③ M은 소비·투자·정부지출에 들어 있는 수입품 금액의 합이다. 맞다.\n⑤ X-M = (S-I)+(T-G)이므로 무역수지 흑자면 국내저축이 국내투자보다 크다. 맞다.","c":"상","v":1},"공인노2019_28-101":{"w":"실질GNI = 실질GDP + 교역조건 변화에 따른 실질무역손익 + 실질대외순수취요소소득\n= 1,500 + 60 + 10 = 1,570조 원이므로 ⑤.","c":"상","v":1},"공인노2022_31-110":{"w":"②가 틀리다. 소비자물가지수는 소비자가 소비하는 모든 품목이 아니라 가계 소비지출에서 비중이 큰 대표 품목(약 460개)의 가격을 조사해 만든다.\n① 도시가계의 소비 구조를 기준으로 하므로 농촌 물가를 보기에는 맞지 않는다.\n③ GDP디플레이터는 국내 생산물만 대상이라 수입품 가격은 반영하지 못한다.\n④ GDP디플레이터 = 명목GDP/실질GDP×100이다.\n⑤ 생산자물가지수는 기업 간 거래되는 원자재·자본재 등의 가격 변화를 반영한다.","c":"상","v":1},"공인노2022_31-112":{"w":"2021년 실질GDP = 명목GDP/(디플레이터/100) = 2,200/1.05 ≈ 2,095.2조 원\n2020년은 기준연도이므로 실질GDP = 명목GDP = 2,000조 원\n실질성장률 = 2,095.2/2,000-1 ≈ 4.8%이므로 ③.\n(명목성장률 10%에서 물가상승률 5%를 뺀 5%가 아니라 4.8%인 점에 주의)","c":"상","v":1},"공인노2022_31-116":{"w":"⑤가 틀리다. 투자는 설비투자·건설투자·재고투자로 이루어지고, 재고변동도 투자에 포함한다.\n① GNP = GDP + 국외순수취요소소득이다.\n② 명목GDP = 가격×수량이므로 가격 변화에도 영향을 받는다.\n③ 정의 그대로 맞다.\n④ 최종생산물의 시장가치 합은 각 단계 부가가치의 합과 같다.","c":"상","v":1},"공인노2024_33-97":{"w":"⑤가 틀리다. 소비자물가지수는 소비자가 사는 상품에 수입품이 포함되므로 환율변화로 인한 수입재 가격 변화가 반영된다. 반면 GDP디플레이터는 국내 생산물만 대상이라 수입재 가격이 반영되지 않는다.\n① 범죄 증가로 경찰 장비 지출이 늘면 GDP는 늘지만 삶의 질은 나빠진다.\n② 가격이 오른 재화를 싼 재화로 바꾸는 대체편의 때문에 CPI는 생활비 상승을 과대평가한다.\n③ 구직을 단념한 사람은 일할 의사는 있으나 구직활동을 하지 않아 비경제활동인구로 본다.\n④ 자원봉사는 시장에서 거래되지 않아 GDP에 잡히지 않는다.","c":"상","v":1},"공인노2025_34-100":{"w":"⑤가 틀리다. 주부의 가사노동은 GDP에서 제외되지만, 자가주택의 주거서비스는 귀속임대료로 추계해 GDP에 포함한다.\n① GDP는 생산된 부가가치 100억 원을 그대로 잡고, 오염 피해 10억 원은 빼지 않는다.\n② GDP의 정의이다.\n③ 도어록 생산이 늘면 그만큼 생산이 늘어 GDP가 증가한다.\n④ 기존 주택·중고차 거래는 새로 생산된 것이 아니므로 제외한다. 다만 거래 수수료는 포함된다.","c":"상","v":1},"공인노2025_34-102":{"w":"GDP디플레이터 = 명목GDP/실질GDP×100\n2021년 = 1,050/1,000×100 = 105, 2022년 = 1,210/1,100×100 = 110\n③ 2022년 디플레이터 상승률 = 110/105-1 ≈ 4.8%로 5%가 아니므로 틀리다.\n① 실질성장률 = 1,100/1,000-1 = 10%. 맞다.\n② 110. 맞다.\n④ 105. 맞다.\n⑤ 명목성장률 = 1,210/1,050-1 ≈ 15.2%로 10%보다 높다. 맞다.","c":"상","v":1},"공인노2025_34-103":{"w":"⑤가 틀리다. 소비자물가지수는 품목별 가계 지출 비중을 가중치로 쓰므로 가중치가 서로 다르다.\n① 대상 품목과 가중치가 달라 같은 기간에도 다른 값이 나올 수 있다.\n② 소비자물가지수는 약 460개 품목, 생산자물가지수는 약 천여 개 품목이라 CPI 품목 수가 더 적다.\n③ 물가지수는 모두 기준연도를 100으로 놓는다.\n④ CPI는 도시가계가 주로 소비하는 상품·서비스의 가격 변화를 본다.","c":"상","v":1},"공인노2026_35-99":{"w":"③이 옳다. CPI는 기준연도의 소비량(바스켓)을 고정해 가격만 비교하는 라스파이레스 지수이므로 가격 변화에 따른 소비량 변화를 반영하지 못한다.\n① 파셰지수로 분류되는 것은 GDP디플레이터이다. CPI는 라스파이레스지수이다.\n② CPI는 수입품도 포함한다. 국내 생산물만 대상인 것은 GDP디플레이터이다.\n④ GDP디플레이터는 국내에서 생산된 상품·서비스가 대상이다.\n⑤ 품질 향상을 반영하지 못하면 물가 상승분 중 일부가 실제로는 품질 상승인데도 가격 상승으로 잡혀 인플레이션을 과대평가한다.","c":"상","v":1},"공인노2017_26-102":{"w":"민간현금보유비율 c(현금/통화량)=0.1, 지급준비율 r=0.2이면 현금통화비율 방식의 통화승수는\nm = 1/(c+r(1-c)) = 1/(0.1+0.2×0.9) = 1/0.28 ≈ 3.571\n통화량 = 3.571×100 ≈ 357이므로 ②.\n(현금/예금 비율로 보는 m=(1+c)/(c+r)를 쓰면 약 367이 되어 보기에 없다. 보기에 있는 357은 현금/통화량 비율로 읽을 때 나온다.)","c":"중","v":1},"공인노2017_26-106":{"w":"① 고전학파에서는 명목이자율 = 실질이자율 + 기대인플레이션(피셔효과)이다. 통화량이 늘어도 실질변수는 변하지 않고 물가와 명목이자율만 변하므로 화폐의 중립성이 성립한다.\n② IS-LM은 케인즈학파의 균형 분석틀이다.\n③ 유동성선호설은 케인즈의 이자율 이론이다.\n④ 고전학파는 화폐부문과 실물부문을 분리해 보는 고전적 이분법을 따르므로 이자율이 둘을 잇지 않는다.\n⑤ 고전학파의 이자율은 대부자금시장에서 저축과 투자에 의해 결정된다.","c":"상","v":1},"공인노2019_28-103":{"w":"통화량을 늘리는 수단은 다음과 같다.\n- 공개시장조작: 국채를 매입한다(대금이 시중에 풀린다).\n- 법정지급준비율: 인하한다(대출 가능액이 늘어 통화승수가 커진다).\n- 재할인율: 인하한다(은행이 중앙은행에서 더 싸게 빌린다).\n매입-인하-인하이므로 ①.","c":"상","v":1},"공인노2022_31-115":{"w":"⑤ 재할인율을 올리면 시중은행이 중앙은행에서 빌리는 비용이 늘어 대출과 통화량이 줄어든다. 통화량 증가 요인이 아니다.\n① 통화량 = 통화승수×본원통화이므로 본원통화가 늘면 통화량이 는다.\n② 지급준비율이 내리면 통화승수가 커진다.\n③ 통화승수가 커지면 통화량이 는다.\n④ 초과지급준비금이 줄면 그만큼 대출이 늘어 통화량이 는다.","c":"상","v":1},"공인노2024_33-101":{"w":"보몰-토빈 모형: 소득 Y, 이자율 i, 1회 전환비용 b일 때 1회 전환금액 = √(2bY/i), 평균화폐보유액 = √(bY/2i), 전환횟수 = √(iY/2b).\n① b가 크면 평균화폐보유액이 늘어난다. X\n② 이자율이 높으면 평균화폐보유액이 줄어든다. X\n③ 소득이 높으면 평균화폐보유액이 늘어난다. X\n④ b가 크면 전환횟수가 줄어든다. X\n⑤ b가 크면 한 번에 바꾸는 금액이 커진다. O","c":"상","v":1},"공인노2024_33-107":{"w":"화폐시장 균형: M/P = L(i, Y), L은 i의 감소함수, Y의 증가함수.\nㄱ. M이 늘면 실질통화공급이 늘어 이자율이 하락한다. O\nㄴ. P가 오르면 실질통화공급이 줄어 이자율이 상승한다. X\nㄷ. Y가 늘면 화폐수요가 늘어 이자율이 상승한다. O\nㄱ, ㄷ이므로 ④.","c":"상","v":1},"공인노2025_34-104":{"w":"④가 틀리다. 기업이 급여를 현금으로 주면 현금보유가 늘고 은행 예금이 줄어 현금통화비율이 오르므로 통화승수가 작아지고 예금창조액은 더 적어진다.\n① 통화승수는 통화량/본원통화이다.\n② 요구불예금 이자율이 낮으면 현금 보유가 늘어 통화승수가 작아진다.\n③ 지급준비율이 오르면 통화승수가 작아진다.\n⑤ 통화량 증가분 = 4×1억 원 = 4억 원이다.","c":"상","v":1},"공인노2017_26-103":{"w":"⑤ E씨는 일할 의사가 있고 면접을 보러 다니며 구직활동 중이므로 실업자이다.\n① 시험 준비 중인 사람은 구직활동이 아니라 비경제활동인구이다.\n② 구직을 접고 버섯재배를 시작했으므로 취업자(자영업)로 본다.\n③ 부모의 식당 일을 주중 내내 돕고 있으므로 무급가족종사자로서 취업자이다.\n④ 취업 필요를 못 느끼는 사람은 일할 의사가 없는 비경제활동인구이다.","c":"상","v":1},"공인노2017_26-123":{"w":"① 실망노동자는 일자리를 구하려는 활동을 하지 않으므로 비경제활동인구이며 실업자가 아니다. 옳다.\n② 완전고용 상태에도 마찰적·구조적 실업(자연실업)은 있다. 틀리다.\n③ 최저임금이 균형임금보다 높으면 실업이 늘 수 있다. 틀리다.\n④ 실업보험이 확대되면 구직 기간이 길어져 자연실업률이 높아진다. 틀리다.\n⑤ 마찰적 실업은 자발적 실업으로 본다. 비자발적 실업은 경기적 실업과 구조적 실업이다. 틀리다.","c":"중","v":1},"공인노2017_26-124":{"w":"경제활동인구 = 570+30 = 600만 명\n실업률 = 30/600 = 5%\n비경제활동률 = (1,000-600)/1,000 = 40%\n고용률 = 570/1,000 = 57%\n④는 고용률을 60%라 했으므로 틀리다.\n⑤ 생산가능인구(15세 이상)만 주어졌으므로 15세 미만을 포함한 전체 인구는 알 수 없다.","c":"하","v":1},"공인노2019_28-102":{"w":"④가 틀리다. 예상된 인플레이션에서도 가격표를 고쳐 다는 메뉴비용은 발생한다.\n① 정의 그대로 맞다.\n② 명목임금이 내려가지 않으면 물가 하락만큼 실질임금이 올라간다.\n③ 총수요 증가가 원인이면 수요견인 인플레이션이다.\n⑤ 물가가 내려가면 명목부채의 실질 가치가 커져 상환 부담이 늘어난다.","c":"상","v":1},"공인노2019_28-106":{"w":"④가 틀리다. 프리드만에 따르면 장기에는 기대인플레이션이 실제와 같아져 자연실업률 수준에서 필립스곡선이 수직선이 된다.\n① 단기 필립스곡선이 우하향하므로 총수요 확장으로 실업률을 낮출 수 있다.\n② 우하향 곡선에서는 인플레이션을 줄이려면 실업이 늘어나므로 희생률이 성립한다.\n③ 필립스가 처음 밝힌 것은 임금상승률과 실업률의 관계였다.\n⑤ 기대인플레이션이 오르면 단기 필립스곡선이 위(오른쪽)로 이동한다.","c":"상","v":1},"공인노2019_28-121":{"w":"ㄱ. 시장균형보다 높은 임금을 주면 노동공급이 초과되어 비자발적(구조적) 실업이 생긴다. O\nㄴ. 임금이 높으면 해고 때 손실이 커서 태업이 줄어든다. O\nㄷ. 높은 임금은 다른 곳으로 옮길 유인을 줄여 이직이 줄어든다. O\n모두 옳으므로 ⑤.","c":"상","v":1},"공인노2019_28-125":{"w":"실업률 = 실업자/경제활동인구 = 6%\n경제활동인구 = 60만/0.06 = 1,000만 명\n취업자 = 1,000-60 = 940만 명이므로 ②.","c":"상","v":1},"공인노2022_31-114":{"w":"④ 자산 가치 평가 기준이 안정되는 것은 인플레이션 비용이 아니다. 인플레이션은 화폐가치를 흔들어 자산·부채의 평가 기준을 불안정하게 만드는 것이 비용이다.\n① 가격표를 바꾸는 메뉴비용\n② 명목소득이 오르면 높은 세율 구간으로 올라가 세부담이 늘어난다.\n③ 상대가격이 왜곡되어 자원배분이 비효율적이 된다.\n⑤ 현금을 덜 들고 은행을 자주 오가는 구두창비용\n①②③⑤는 모두 인플레이션의 비용이다.","c":"상","v":1},"공인노2022_31-118":{"w":"실질이자율 5%, 인플레이션율 3%이면 세전 명목이자율 = 5+3 = 8%\n세후 명목이자율 = 8×(1-0.2) = 6.4%이므로 ④.","c":"상","v":1},"공인노2022_31-119":{"w":"생산가능인구 4,000명\n2020년: 비경제활동 2,000 → 경제활동 2,000, 취업 1,100, 실업 900\n2021년: 비경제활동 2,100 → 경제활동 1,900, 취업 1,000, 실업 900\n① 참가율 50% → 47.5%로 감소. 맞다.\n② 실업률 45% → 약 47.4%로 증가. 맞다.\n③ 고용률 27.5% → 25%로 감소. 맞다.\n④ 실업자 수는 900명으로 같다. 맞다.\n⑤ 취업률(취업자/경제활동인구)은 55% → 약 52.6%로 줄었다. 변화 없다는 것은 틀리다.","c":"상","v":1},"공인노2022_31-124":{"w":"④ 산업구조가 바뀌어 내연기관 생산 노동자가 일자리를 잃는 것은 구조적 실업이다.\n① 구직단념자는 실업자에서 빠져 비경제활동인구로 넘어가므로 비경제활동인구는 늘고 실업률은 낮아진다.\n② 비자발적 실업은 실제 임금이 균형임금보다 높아서 생긴다.\n③ 경기 둔화로 인한 실업은 경기적 실업이다.\n⑤ 해외 유아는 경제활동인구(15세 이상)에 포함되지 않아 실업률과 무관하다.","c":"상","v":1},"공인노2022_31-125":{"w":"② 효율임금이론은 같은 업무인데도 기업마다 임금이 다른 현상을 설명한다. 옳다.\n① 효율임금은 균형임금보다 높아 비자발적 실업이 생긴다.\n③ 노동자 이동이 활발하다는 가정과 무관하다. 이직 비용을 줄이려고 높은 임금을 준다.\n④ 높은 임금은 해고 때 손실을 키워 태만을 줄인다.\n⑤ 높은 임금은 우수한 노동자를 끌어들여 역선택을 줄인다.","c":"상","v":1},"공인노2024_33-98":{"w":"④가 틀리다. 예상치 못한 인플레이션이 오면 채무의 실질 가치가 줄어 채무자가 이익을 보고 채권자가 손해를 본다.\n① 메뉴비용 ② 누진세에서 세율 구간 상승 ③ 현금 보유를 줄이려는 구두창비용 ⑤ 인플레이션이 높고 변동이 크면 장기 계획이 어려워진다. 모두 인플레이션의 비용이다.","c":"상","v":1},"공인노2024_33-113":{"w":"π_t = π_t^e - β(u_t - u_n) + ν_t.\nㄱ. β가 크면 실업률이 조금만 올라도 인플레이션이 많이 내려가므로 희생비율(인플레이션 1%포인트를 낮출 때 잃는 생산)이 작아진다. X\nㄴ. 유가 상승은 ν_t > 0으로 같은 실업률에서 인플레이션을 높여 곡선을 위로 옮긴다. O\nㄷ. 오쿤의 법칙으로 실업률이 낮으면 총생산이 크다. 실업률과 인플레이션이 음의 관계이므로 총생산과 인플레이션은 양의 관계가 된다. O\nㄹ. 기대인플레이션율이 고정되어 있으면 인플레이션을 낮추려면 u_t가 u_n보다 높아져야 한다. O\nㄴ, ㄷ, ㄹ이므로 ④.","c":"상","v":1},"공인노2024_33-116":{"w":"⑤가 틀리다. 직장이 있으나 질병 등으로 일시적으로 일을 못한 사람은 일시휴직자로서 취업자에 포함된다.\n① 경제활동인구 = 취업자+실업자\n② 일할 뜻이나 능력이 없으면 비경제활동인구이다.\n③ 군 복무자·수감자는 조사대상에서 제외한다.\n④ 조사 대상 주간에 수입을 목적으로 1시간 이상 일하면 취업자이다.","c":"상","v":1},"공인노2024_33-117":{"w":"⑤가 효율성임금이론의 이유가 아니다. 효율성임금은 임금이 노동자의 생산성에 직접 영향을 주는 경로(이직 감소, 우수 인력 확보, 태만 감소, 영양·건강 개선)로 설명한다. 브랜드 이미지와 매출은 이 경로가 아니다.\n① 이직 감소 ② 역선택 완화 ③ 태만 감소(해고 시 손실 증가) ④ 영양·건강 개선","c":"상","v":1},"공인노2024_33-118":{"w":"균제상태에서는 실직자 수 = 취업자가 되는 수이다. 실직률 s, 구직률 f, 실업률 U라 하면 s(1-U) = fU.\nf = s(1-U)/U = 0.03×0.88/0.12 = 0.22 = 22%이므로 ⑤.","c":"상","v":1},"공인노2025_34-98":{"w":"생산가능인구 4,000명\n2023년: 비경제활동 2,000 → 경제활동 2,000, 취업 1,000, 실업 1,000\n2024년: 비경제활동 2,100 → 경제활동 1,900, 취업 1,000, 실업 900\n② 실업률 50% → 약 47.4%로 낮아졌다. 옳다.\n① 고용률 = 취업자/생산가능인구 = 25%로 같다.\n③ 2024년 실업률은 약 47.4%이다.\n④ 고용률의 분모는 총인구가 아니라 생산가능인구이다.\n⑤ 경제활동참가율은 50% → 47.5%로 낮아졌다.","c":"상","v":1},"공인노2025_34-99":{"w":"실질이자율 = 명목이자율-물가상승률 = 5-3 = 2%\n세후 명목이자율 = 5×(1-0.1) = 4.5%\n(2%, 4.5%)이므로 ②.","c":"상","v":1},"공인노2025_34-101":{"w":"① 수입원자재 가격 상승은 생산비 상승에서 오는 비용인상 인플레이션의 원인이다. 수요견인이 아니므로 틀리다.\n② 예상된 인플레이션에서 은행을 자주 찾는 비용은 구두창비용이다.\n③ 인플레이션 조세는 정부가 통화를 발행해 얻는 수입이다.\n④ 피셔효과가 성립하면 명목이자율이 인플레이션만큼 올라 채권자의 실질수익이 유지된다.\n⑤ 예상치 못한 인플레이션은 실물자산·외환 투기를 부른다.","c":"상","v":1},"공인노2025_34-110":{"w":"④가 틀리다. 합리적 기대를 하더라도 가격이나 임금이 경직적이면 단기 필립스곡선은 우하향할 수 있고, 수직이 항상 성립하는 것은 아니다. 합리적 기대에서 예상된 정책에 대해 곡선이 수직이 되는 것은 가격이 신축적일 때이다. ③은 같은 내용을 말하고 있어 옳다.\n① 산출량이 자연산출량이면 실업률이 자연실업률이고 필립스곡선은 수직이다.\n② 단기에 우하향하는 경우 실업률을 낮추려는 확장정책은 물가상승률을 높인다.\n⑤ 새고전학파는 예상된 정책이 즉시 반영되어 곡선이 바로 이동한다고 본다.","c":"중","v":1},"공인노2025_34-114":{"w":"경제활동인구 E+U = 4,000만 명(비경제활동인구는 영향 없음)\n균제: 실직 = 취업, 0.04E = 0.16U → E = 4U\nU = 800만 명, E = 3,200만 명이므로 ③.","c":"상","v":1},"공인노2025_34-117":{"w":"옳지 않은 것은 ㄴ 하나이므로 ②.\nㄱ. 높은 임금은 해고 시 손실이 커 태만을 줄인다. 옳다.\nㄴ. 비근로소득은 임금과 무관한 소득으로, 이를 늘리는 것은 생산성을 높이는 경로가 아니다. 틀리다.\nㄷ. 이직 확률을 낮춘다. 옳다.\nㄹ. 우수한 근로자를 끌어들인다. 옳다.","c":"상","v":1},"공인노2026_35-102":{"w":"③이 틀리다. 오쿤의 법칙에서 실업률이 1%p 오르면 실질GDP 성장률은 대략 2%p 낮아진다. 하락이지 상승이 아니다.\n① 오쿤의 법칙은 실업률 변화와 GDP 성장률의 관계이다.\n② 장기 성장률이 높아지면 실업률이 그대로여도 성장률 절편이 올라간다.\n④ 고용 없는 성장에서는 이 관계가 약해져 성립하지 않는다.\n⑤ 경기침체기에는 실업률이 오르고 확장기에는 내린다.","c":"상","v":1},"공인노2026_35-117":{"w":"균제: 취업률(f)×U = 실직률(s)×E, E = 1-U\n0.4U = 0.1(1-U) → 0.5U = 0.1 → U = 0.2\n실업률 20%이므로 ②.","c":"상","v":1},"공인노2026_35-118":{"w":"④가 틀리다. 임금이 경직적이어서 고정된 상태에서 기술혁신으로 노동의 한계생산이 오르면 노동수요가 늘어 고용량이 증가한다.\n① 케인즈는 비자발적 실업이 존재한다고 본다.\n② 비자발적 실업이 있는 고용 수준에서는 임금(=한계생산)이 한계비효용보다 높아 일하고 싶어도 못 하는 사람이 있다.\n③ 고전학파의 노동수요는 실질임금 = 노동의 한계생산에서 결정된다.\n⑤ 임금이 오를 때 소득효과가 대체효과보다 크면 여가를 늘려 노동공급이 줄어든다.","c":"상","v":1},"공인노2026_35-119":{"w":"① 내부자-외부자 이론은 내부자의 교섭력 때문에 임금이 높고 경직적이어서 외부자가 일자리를 못 얻는다고 본다. 실질임금이 경직적이어도 구조적 실업이 사라진다는 것은 틀리다.\n② 외부자는 더 낮은 임금에도 일하려 하지만 고용되지 못한다.\n③ 효율임금이론은 높은 임금으로 생산성 향상을 꾀한다고 본다.\n④ 암묵적 계약이론에서는 위험회피적인 근로자가 변동하는 임금보다 고정된 임금을 선호한다.\n⑤ 기업이 일정 임금을 보장하는 보험을 제공하는 셈이다.","c":"상","v":1},"공인노2017_26-104":{"w":"서울 빅맥 가격 = 5,500-1,100 = 4,400원, 미국 5달러, 현재 환율 5,500/5 = 1,100원/달러.\nㄱ. 4,400/1,100 = 4달러. O\nㄴ. 구매력평가 환율 = 4,400/5 = 880원. 1,100원이 아니다. X\nㄷ. 실질환율 = 명목환율×외국 가격/국내 가격 = 1,100×5/4,400 = 1.25(빅맥 개수 기준)이며 880원은 PPP환율이다. X\nㄹ. 명목환율 1,100원이 PPP환율 880원보다 높다. 달러 1단위가 PPP보다 많은 원이므로 원화가 구매력보다 낮게 평가된 상태이다. O\nㄱ, ㄹ이므로 ③.","c":"상","v":1},"공인노2019_28-108":{"w":"자본이동이 완전한 소규모 개방경제의 먼델-플레밍 모형 결론은 다음과 같다.\n- 고정환율제: 재정정책은 이자율 상승 압력 → 자본유입 → 통화량 증가로 LM이 따라 이동하여 소득이 늘어난다. 통화정책은 통화량 증가가 외환시장 개입으로 되돌려지므로 소득에 효과가 없다.\n- 변동환율제: 재정정책은 환율 하락(자국통화 절상)으로 순수출이 줄어 소득이 변하지 않는다. 통화정책은 환율 상승으로 순수출이 늘어 소득이 증가한다.\n고정환율에서 재정정책 유효·통화정책 무효이므로 ③.","c":"상","v":1},"공인노2019_28-109":{"w":"경상수지 = 상품수지+서비스수지+본원소득수지+이전소득수지\n= 54+(-17)+3+(-5) = 35억 달러 흑자이므로 ①.\n직접투자·증권투자는 금융계정 항목이라 경상수지에 들어가지 않는다.","c":"상","v":1},"공인노2024_33-102":{"w":"자본이동이 완전하고 물가가 고정된 소규모 개방경제의 고정환율제이다.\nㄱ. 정부지출이 늘면 IS가 오른쪽으로 가고 이자율 상승 압력이 생긴다. 자본이 들어오면서 중앙은행이 통화량을 늘려 LM도 따라 이동하므로 국민소득이 증가한다. O\nㄴ. 자본유입으로 환율이 내려가려는 것을 막기 위해 중앙은행이 외환을 사들이므로 외환보유고가 늘어난다. O\nㄷ. 통화량을 늘려도 환율 유지를 위해 중앙은행이 도로 흡수하므로 소득은 변하지 않는다. X\nㄹ. 평가절상은 자국 상품의 외화 가격을 올려 순수출을 줄인다. X\nㄱ, ㄴ이므로 ①.","c":"상","v":1},"공인노2024_33-108":{"w":"③이 틀리다. 변동환율제에서 유가가 올라 무역적자가 나면 외환 수요가 늘어 환율이 오르고(통화가치 하락) 자국통화가 약해진다.\n① 고정환율제에서는 환율 유지를 위한 외환시장 개입 때문에 통화량을 마음대로 조절할 수 없다.\n② 고정환율도 불균형이 지속되면 평가절하·절상으로 조정될 수 있다.\n④ 변동환율제에서도 정부가 환율 안정을 위해 개입(더러운 변동환율제)할 수 있다.\n⑤ 두 제도 모두 환투기 등 환율 변동을 이용한 차익 추구가 가능하다.","c":"상","v":1},"공인노2024_33-111":{"w":"구매력평가환율 = 4,800/4 = 1,200원/달러이고 현재 환율은 1,300원이다. 장기에 구매력평가가 성립하면 실질환율은 1이다.\n③ 가격이 변하지 않으면 명목환율이 1,300에서 1,200으로 내려간다. 옳다.\n① 구매력평가가 성립하면 실질환율은 1이다.\n② PPP환율은 1,200이다.\n④ 미국 가격과 환율이 그대로이면 PPP가 성립하려면 한국 햄버거 가격이 1,300×4 = 5,200원으로 올라야 한다.\n⑤ 한국 가격이 4,800원으로 고정이면 환율×미국 가격 = 4,800이어야 하므로 환율이 오르면 미국 가격은 내려간다.","c":"상","v":1},"공인노2025_34-106":{"w":"③ 변동환율제에서 수입이 수출보다 많으면 순수출이 줄어 IS가 왼쪽으로 이동한다. 외환 수요가 늘어 자국통화가 평가절하되고, 평가절하가 순수출을 되살려 IS가 원위치로 돌아오므로 소득은 변하지 않는다. 옳다.\n① 변동환율에서 확장 재정은 자국통화를 절상시키고 순수출 감소로 소득은 변하지 않는다. 소득이 감소하는 것이 아니다.\n② 고정환율에서 확장 재정은 소득을 증가시킨다.\n④ 고정환율에서 순수출이 줄면 IS 좌측 이동 후 통화량이 줄어 LM도 이동하므로 소득이 감소한다.\n⑤ 고정환율에서 통화공급을 늘려도 중앙은행이 흡수해 소득은 변하지 않는다.","c":"상","v":1},"공인노2026_35-109":{"w":"⑤가 틀리다. 변동환율제에서 확대 재정은 이자율 상승 압력으로 자본이 들어와 자국통화가 절상되고, 이로 인해 순수출이 줄어 재정 효과가 완전히 상쇄된다. 순수출은 감소한다.\n① 자본이동이 완전하면 국내 이자율 = 국제 이자율이다.\n② 고정환율에서는 통화량이 내생적으로 결정되어 통화정책 독립성이 없다.\n③ 고정환율에서 확대 재정은 자본유입과 외환 매입으로 통화량을 늘린다.\n④ 변동환율에서 통화량이 늘면 이자율 하락으로 자본이 빠져 나가 통화가치가 떨어진다.","c":"상","v":1},"공인노2026_35-112":{"w":"⑤가 틀리다. 구매력평가설과 실질이자율평가가 항상 성립하면 양국의 실질이자율 차이는 0이다.\n① 구매력평가설은 두 통화의 실질 구매력이 같아지도록 환율이 정해진다는 이론이다.\n② 절대적 구매력평가가 성립하면 실질환율은 1이다.\n③ 커버되지 않은 이자율평가에서 i = i*+(기대환율-현재환율)/현재환율이다. 기대환율이 주어졌을 때 자국 이자율이 오르면 현재환율은 하락한다.\n④ 양국 이자율 차이는 환율의 기대변화율과 같다.","c":"중","v":1},"공인노2017_26-105":{"w":"ㄱ. 대출이자율이 내리면 소비·투자가 늘어 AD가 오른쪽으로 이동한다. O\nㄴ. 소득세율 인상은 가처분소득을 줄여 소비가 감소하므로 AD가 왼쪽으로 이동한다. X\nㄷ. 투자세액공제 확대는 투자를 늘린다. O\nㄹ. 물가 하락으로 실질자산이 늘어 소비가 늘어나는 것은 AD곡선 위의 이동이다. X\nㅁ. 해외 호황으로 수출이 늘면 AD가 오른쪽으로 이동한다. O\nㄱ, ㄷ, ㅁ이므로 ②.","c":"상","v":1},"공인노2019_28-104":{"w":"ㄱ. 자산효과(피구효과): 물가가 하락하면 보유 자산의 실질가치가 올라 소비가 늘어난다. O\nㄴ. 이자율효과(케인즈효과): 물가가 하락하면 실질통화량이 늘어 이자율이 내리고 투자가 늘어난다. O\nㄷ. 환율효과(먼델-플레밍 효과): 물가가 하락하면 이자율이 내려 자본이 해외로 나가고 자국통화 가치가 떨어져 순수출이 늘어난다. O\n모두 옳으므로 ⑤.","c":"상","v":1},"공인노2019_28-105":{"w":"②가 틀리다. 인적자본이 증가하면 잠재산출량이 늘어 장기 총공급곡선이 오른쪽으로 이동한다.\n① 유가가 오르면 생산비가 올라 단기 총공급곡선이 왼쪽으로 이동한다.\n③ 생산성이 오르면 단기 총공급곡선이 오른쪽으로 이동한다.\n④ 가격이 신축적이면 장기에는 물가가 변해도 산출량은 자연산출량에서 변하지 않는다.\n⑤ 고용주 부담 의료보험료가 오르면 생산비 증가로 단기 총공급곡선이 왼쪽으로 이동한다.","c":"상","v":1},"공인노2022_31-113":{"w":"⑤ 자연실업률이 오르면 완전고용 노동량이 줄어 잠재산출량이 감소하므로 장기 총공급곡선이 왼쪽으로 이동한다.\n①②③④는 노동·자본·기술·자원 등 생산요소와 생산성이 늘어 잠재산출량이 증가하는 요인으로 장기 총공급곡선을 오른쪽으로 이동시킨다.","c":"상","v":1},"공인노2022_31-117":{"w":"Y = 100+0.5(Y-100)+300+G = 350+0.5Y+G\n0.5Y = 350+G, Y = 700+2G\n현재 G = 100이면 Y = 900이고 완전고용 GDP 1,200과의 차이는 300이다.\n정부지출승수 = 1/(1-0.5) = 2이므로 ΔG = 300/2 = 150이다. 정부지출을 150 늘려야 하므로 ②.","c":"중","v":1},"공인노2024_33-103":{"w":"균형소득: Y = 100 + 0.8(Y − 200) + 300 + 200 → 0.2Y = 440 → Y = 2,200\nㄱ O 정부지출승수 = 1/(1 − 0.8) = 5\nㄴ X 조세승수 = −0.8/(1 − 0.8) = −4\nㄷ X 균형소득 2,200이 완전고용소득 2,000보다 커서 인플레이션갭이다.\nㄹ O 총생산갭의 절댓값 = 2,200 − 2,000 = 200","c":"상","v":1},"공인노2024_33-106":{"w":"② LM곡선이 수직이면 통화량이 고정된 상태이므로 재정지출을 늘려도 소득은 그대로이고 이자율만 올라 민간투자가 같은 금액만큼 줄어든다. 완전한 구축효과이다.\n① 유동성함정은 화폐수요의 이자율탄력성이 무한대일 때 생긴다.\n③ 피구효과는 물가 하락으로 실질자산이 늘어 소비가 증가하는 효과로, 소비가 이자율의 함수인 경우가 아니다.\n④ IS가 수평이면 LM 이동만큼 소득이 변하므로 통화정책이 가장 큰 효과를 낸다.\n⑤ 투자의 이자율탄력성이 0이면 IS곡선은 수직선이다.","c":"상","v":1},"공인노2024_33-112":{"w":"IS: Y = 500 + 0.8(Y − 200) + 100 − 20r + G → 0.2Y = 440 + G − 20r\nLM: 1,000 = 500 + 0.4Y − 10r → r = 0.04Y − 50\n대입: 0.2Y = 440 + G − 0.8Y + 1,000 → Y = 1,440 + G\nG = 300이면 Y = 1,740. Y = 1,500이 되려면 G = 60이므로 정부지출을 240(80%) 줄여야 한다.","c":"상","v":1},"공인노2025_34-105":{"w":"④가 틀리다. 실제물가가 기대물가와 다를 때 단기 총공급곡선은 우상향한다. 실제물가가 기대보다 높으면 산출이 늘고 낮으면 줄어드는 관계이다.\n① 수직 총공급에서는 총수요 변화가 물가만 바꾸고 산출은 그대로이다.\n② 수직인 총공급은 실물과 화폐를 분리하는 고전적 이분법과 일치한다.\n③ 모든 가격이 고정되면 총공급은 수평선이다.\n⑤ 케인즈는 명목임금 경직성 때문에 단기 총공급이 우상향한다고 본다.","c":"상","v":1},"공인노2025_34-107":{"w":"ㄱ. AD-AS 곡선은 개별 시장의 수요·공급곡선을 합쳐서 얻는 것이 아니라 거시모형에서 별도로 도출한다. 틀리다.\nㄴ. 통화공급이 늘면 AD가 오른쪽으로 이동한다. 옳다.\nㄷ. 정부지출이 줄면 AD가 왼쪽으로 이동한다. 옳다.\nㄹ. 투자의 이자율 탄력성이 음(-)이라는 것은 이자율이 오르면 투자가 줄어든다는 일반적 성질이고, 이 경우 AD곡선은 우하향한다. 틀리다.\n옳지 않은 것은 ㄱ, ㄹ이므로 ②.","c":"중","v":1},"공인노2025_34-109":{"w":"IS: Y = 20 + 0.8(Y − 50) + 10 − 2r + 50 → 0.2Y = 40 − 2r → Y = 200 − 10r\nLM: 100/1 = Y − 10r → Y = 100 + 10r\n연립하면 r = 5, Y = 150","c":"상","v":1},"공인노2026_35-101":{"w":"③ 균형예산승수 = 정부지출승수 1/(1-c) + 조세승수 -c/(1-c) = 1이다.\n① 정부지출승수는 1/(1-MPC)이다. MPC의 역수가 아니다.\n② 투자승수도 1/(1-MPC)이다.\n④ 구축효과는 승수효과를 약하게 만든다.\n⑤ 유동성함정에서는 이자율이 오르지 않아 구축효과가 없으므로 정부지출 승수가 가장 크다.","c":"상","v":1},"공인노2026_35-106":{"w":"LM이 r = r̄(정책이자율)인 수평선이어서 이자율은 정책이자율로만 정해진다.\n② X 미래 소득 기댓값이 늘면 소비가 늘어 IS가 오른쪽으로 이동하지만 이자율은 r̄에 그대로 있고 소득만 늘어난다.\n① O 정책이자율이 내리면 투자가 늘어 소득이 증가한다.\n③ O 세금이 늘면 가처분소득과 소비가 줄어 소득이 감소한다.\n④ O 정부지출이 늘어도 이자율은 r̄로 고정된다.\n⑤ O 불확실성이 커지면 투자가 줄어 소득이 감소한다.","c":"하","v":1},"공인노2017_26-107":{"w":"④가 틀리다. 케인즈 소비함수 C = a+cY에서 평균소비성향 C/Y = a/Y+c이다. 소득이 늘수록 a/Y가 작아져 평균소비성향은 감소한다.\n① 한계소비성향은 0<c<1이다.\n② 소비는 현재 소득의 함수이다.\n③ 소득이 0이어도 기초소비 a는 있다.\n⑤ 쿠즈네츠가 밝힌 장기 평균소비성향 일정을 설명하지 못한다.","c":"상","v":1},"공인노2024_33-99":{"w":"② 기간 간 최적 소비선택에서 이자율이 오르면 대체효과로 현재소비가 줄고 소득효과·부의 효과는 순저축자에게는 현재소비를 늘리고 순차입자에게는 줄이므로, 현재소비가 반드시 감소한다고 할 수 없다. 틀리다.\n① 케인즈 소비함수는 단기에 평균소비성향이 소득에 따라 감소하여 장기 일정이라는 쿠즈네츠 결과를 설명하지 못한다.\n③ 생애주기가설에서는 강제 연금저축이 개인의 자발적 저축을 대체한다.\n④ 항상소득가설에서 일시적 소득 증가는 소비에 거의 반영되지 않아 평균소비성향이 낮아진다.\n⑤ 리카도 대등정리는 일시적 감세는 항상소득을 바꾸지 않는다는 점에서 항상소득가설과 일치한다.","c":"중","v":1},"공인노2025_34-97":{"w":"④가 틀리다. 케인즈 소비이론에서 한계소비성향은 0과 1 사이이고 평균소비성향은 소득이 늘수록 감소한다.\n① 항상소득이론에서 일시소득의 한계소비성향은 항상소득보다 작다.\n② 생애주기이론은 연령에 따라 소비성향이 달라진다고 본다.\n③ 케인즈는 현재 가처분소득이 소비를 결정한다고 본다.\n⑤ 항상소득이론은 소비를 평탄하게 유지하려는 소비자를 가정한다.","c":"상","v":1},"공인노2025_34-108":{"w":"완전고용 산출: Y = 100^0.5 × 100^0.5 = 100\n처음: 100 = 10 + 0.8(100 − 50) + 8 − 2r + 50 = 108 − 2r → r = 4\nG = 60: 100 = 118 − 2r → r = 9\n이자율 변화의 절댓값 = 5","c":"상","v":1},"공인노2025_34-111":{"w":"최적 자본량은 MPK = 자본의 사용자비용 P_K(r + δ)에서 정해진다.\n사용자비용 = 20 × (0.05 + 0.05) = 2\n10 − 2K = 2 → K = 4","c":"상","v":1},"공인노2025_34-112":{"w":"옳지 않은 것은 ㄴ, ㄹ이므로 ④.\nㄱ. 차입·대부가 가능하면 현재소비는 현재소득과 미래소득의 현재가치(생애자원)에 의존한다. 옳다.\nㄴ. 차용이 불가능하면 현재소비는 현재소득에 의해 제약을 받을 수 있어 평생소득의 현재가치만으로 정해지지 않는다. 틀리다.\nㄷ. 제1기·제2기 소득이 증가하면 평생자원이 늘어 두 기간 소비가 모두 늘어난다. 옳다.\nㄹ. 이자율이 오르면 대체효과로 현재소비는 줄고 미래소비는 늘어난다. 반대로 적었으므로 틀리다.","c":"상","v":1},"공인노2026_35-108":{"w":"② 케인즈 소비이론에서 현재 소비는 현재 소득의 함수이다. 옳다.\n① 케인즈 소비함수에서 소득이 늘수록 평균소비성향은 감소한다.\n③ 항상소득가설에서는 일시적으로 현재 소득이 항상소득을 웃돌면 소비는 항상소득에 맞춰져 평균소비성향이 감소한다.\n④ 확률보행가설(홀)에서는 소비의 변화를 예측할 수 없다.\n⑤ 생애주기가설에서는 일시적 소득 증가가 소비에 크게 반영되지 않아 평균소비성향이 감소한다.","c":"상","v":1},"공인노2026_35-110":{"w":"U = C1·C2이면 C1 = (현재가치로 잰 평생소득)/2이다.\n이자율 0일 때 갑의 평생소득 1 + 2 = 3이라 C1 = 1.5 > Y1 = 1로 차입자(① O), 을은 C1 = 1.5 < Y1 = 2로 대부자(② O)이다.\n③ 차입이 금지되면 갑은 1.5를 쓰고 싶어도 1밖에 쓰지 못해 차입제약에 구속된다. 구속되지 않는다는 설명이 틀리다.\n④ 이자율 0.5에서 갑이 원하는 C1 = (1 + 2/1.5)/2 ≈ 1.17로 여전히 1보다 크므로 구속된다. O\n⑤ 이자율이 0.5에서 0.2로 내리면 C1이 1.17에서 (1 + 2/1.2)/2 ≈ 1.33으로 늘어난다. O","c":"상","v":1},"공인노2026_35-111":{"w":"④ 감가상각 충당금은 비용으로 처리되어 장부상 이윤을 줄인다. 옳다.\n① 투자의 비가역성은 이미 설치한 자본을 되팔기 어렵다는 뜻이며 순투자가 음이 될 수 없다는 뜻이 아니다.\n② 미래 실적이 좋아지면 기업의 시장가치가 올라 토빈 q가 증가한다.\n③ q가 1보다 작으면 자본의 시장가치가 대체비용보다 낮아 투자가 감소한다.\n⑤ 신고전학파 모형에서 MPK가 늘면 최적 자본량이 커져 투자가 증가한다.","c":"중","v":1},"공인노2017_26-108":{"w":"공공재 최적량은 개인 수요를 수직으로 합한 한계편익이 한계비용과 같아지는 곳이다.\nPa+Pb+Pc = (10-Q)+(20-Q)+(20-2Q) = 50-4Q = 30 → Q = 5\n각자의 가격: Pa = 10-5 = 5, Pb = 20-5 = 15, Pc = 20-10 = 10 (합 30 = MC)\n이므로 ①.","c":"상","v":1},"공인노2019_28-115":{"w":"ㄱ. 생산 측면의 부(-)의 외부효과가 있으면 사회적 비용이 사적 비용보다 크므로 시장 생산량은 사회적 최적보다 많다. X\nㄴ. 피구세·보조금으로 외부효과를 내부화할 수 있다. O\nㄷ. 코즈정리: 거래비용이 없고 재산권이 분명하면 당사자 협상으로 해결된다. O\nㄴ, ㄷ이므로 ④.","c":"상","v":1},"공인노2022_31-107":{"w":"ㄱ. 탄소세는 외부불경제를 해결하기 위한 피구세이다. O\nㄴ. 세금만큼 공급비용이 올라 X재 가격이 오른다. O\nㄷ. 사회적 비용을 반영하여 과다 생산이 줄고 자원배분이 효율적으로 된다. O\nㄹ. 태양광·풍력은 탄소를 배출하지 않는 발전이므로 X재의 사례가 아니다. X\nㄱ, ㄴ, ㄷ이므로 ④.","c":"상","v":1},"공인노2022_31-109":{"w":"아파트 CCTV 서비스는 입주민 누구나 이용할 수 있어 배제할 수 없고(ㄷ), 한 주민이 보호받는다고 다른 주민의 보호가 줄지 않아 비경합적이다. 따라서 공공재이다(ㄹ).\nㄱ. 공유자원은 경합적이다. X\nㄴ. 사적재는 배제·경합이 모두 가능한 재화이다. X\nㄷ, ㄹ이므로 ⑤.","c":"상","v":1},"공인노2024_33-83":{"w":"② 자연독점은 규모에 대한 수확체감이 아니라 규모의 경제(평균비용 체감)에서 생긴다. 틀리다.\n① 불완전경쟁은 시장실패이다.\n③ 비경합적이고 배제불가능한 재화는 공공재로 시장이 과소 공급한다.\n④ 대기오염 피해비용이 요금에 반영되지 않으면 외부효과가 있는 경우이다.\n⑤ 역선택·도덕적 해이는 정보 비대칭에서 오는 시장실패이다.","c":"상","v":1},"공인노2024_33-89":{"w":"할당 시점(각 50) 한계저감비용: A = 100 − 50 = 50, B = 120 − 50 = 70. B가 방류권을 사 들인다.\n거래 후 두 기업의 한계저감비용이 같아진다: 100 − Q_A = 120 − Q_B, Q_A + Q_B = 100\n→ Q_A = 40, Q_B = 60. 거래량 10, 가격 = 100 − 40 = 60","c":"상","v":1},"공인노2025_34-93":{"w":"ㄱ. 생산 측면의 부(-)의 외부효과가 있으면 시장 생산량이 사회적 최적보다 많다. O\nㄴ. 보조금·조세로 내부화할 수 있다. O\nㄷ. 직접통제는 상황 변화에 신축적으로 대응하기 어렵다. X\nㄹ. 코즈정리. O\nㄱ, ㄴ, ㄹ이므로 ②.","c":"상","v":1},"공인노2025_34-95":{"w":"ㄱ. 공공재는 무임승차 때문에 시장에 맡기면 과소 공급된다. O\nㄴ. 순수공공재는 비경합적이라 소비자를 한 명 더 받는 한계비용이 0이므로 효율적인 가격은 0이다. 배제도 불가능해 대가를 받을 수 없으므로 양(+)의 가격을 매길 수 없다. O\nㄷ. 한 사람의 소비가 다른 사람의 소비 기회를 줄이지 않는 것은 비경합성이다. X\nㄹ. 대가를 내지 않은 사람을 소비에서 막을 수 없는 것은 배제불가능성이다. X\nㄱ, ㄴ이므로 ①.","c":"중","v":1},"공인노2026_35-96":{"w":"저감 한계비용 MAC = d(40G − G²)/dG = 40 − 2G\n한계편익 MB = d(1.5G²)/dG = 3G\n40 − 2G = 3G → G = 8","c":"상","v":1},"공인노2026_35-98":{"w":"② 중고차 시장에서 구매자가 품질을 모르면 평균 가격만 지불하려 하여 품질 좋은 차는 시장에서 빠지고 낮은 품질만 거래된다. 거래 전 정보 비대칭에서 오는 역선택이다.\n① 보험 가입 후 부주의한 운전은 도덕적 해이이다.\n③ 소작·대리인 관계의 유인 문제이다.\n④ 공유지의 비극이다.\n⑤ 교육 기회 확대를 위한 정책이다.","c":"상","v":1},"공인노2017_26-110":{"w":"역수요 P = 100-2Q에서 총수입 TR = 100Q-2Q², 한계수입 MR = 100-4Q\n한계비용 MC = 60\nMR = MC: 100-4Q = 60 → Q = 10\nP = 100-2×10 = 80이므로 ⑤.","c":"상","v":1},"공인노2017_26-111":{"w":"③이 틀리다. 독점적 경쟁시장에서 제품 차별화가 클수록 대체재가 줄어 수요의 가격탄력성은 작아진다.\n① 독점기업이 직면하는 수요곡선은 시장수요곡선이다.\n② 러너 독점도 L = (P-MC)/P이므로 가격과 한계수입(=한계비용)의 차이가 클수록 독점도가 커진다.\n④ MR = MC는 이윤극대화의 필요조건이다.\n⑤ 탄력성이 다른 두 집단에는 3급 가격차별이 가능하다.","c":"상","v":1},"공인노2019_28-118":{"w":"③ 독점기업은 MR = MC에서 생산하는데 독점에서는 P > MR이므로 P > MC가 된다. 사회적으로 바람직한 생산량(P = MC)보다 적게 생산하여 자중손실이 생긴다.\n① 소비자가 원하는 상품을 생산하지 않는 것이 아니다.\n② 자원을 과다하게 쓰는 것이 아니라 과소 사용한다.\n④ 독점은 P > AC가 되어 초과이윤이 생길 수 있다.\n⑤ 독점기업도 MR = MC에서 생산한다.","c":"상","v":1},"공인노2022_31-103":{"w":"③ 가격차별을 하면 단일 독점가격일 때 팔지 못하던 소비자에게도 팔게 되어 생산량이 늘어난다. 일반적으로 사회후생이 증가하는 쪽으로 나타난다. 옳다.\n① 독점은 소비자잉여를 줄여 이윤을 늘린다.\n② 독점가격은 한계비용보다 높다.\n④ 가격탄력성이 낮은 집단에 높은 가격을 매긴다.\n⑤ 이부가격제는 소비자 수요가 비슷할수록 효과가 크다.","c":"중","v":1},"공인노2022_31-104":{"w":"완전경쟁기업은 P = MC에서 생산한다.\n30 = 10+4q → q = 5\n총수입 = 30×5 = 150\n총가변비용 = 10q+2q² = 50+50 = 100\n생산자잉여 = 총수입-총가변비용 = 150-100 = 50 (이윤은 50-고정비용 50 = 0)\nq = 5, PS = 50이므로 ④.","c":"상","v":1},"공인노2024_33-85":{"w":"TC = ATC × Q = 20 + Q², MC = 2Q\nMR = 200 − 8Q\nMR = MC → 200 − 8Q = 2Q → Q = 20, P = 200 − 80 = 120\n이윤 = 120 × 20 − (20 + 400) = 1,980","c":"상","v":1},"공인노2024_33-88":{"w":"ATC = 3Q + 5 + 12/Q. 최저점은 3 = 12/Q² → Q = 2, ATC = 6 + 5 + 6 = 17 → 손익분기점 가격 17\nAVC = 3Q + 5는 Q가 0에 가까울 때 최저값 5 → 조업중단점 가격 5","c":"상","v":1},"공인노2024_33-90":{"w":"③ 독점기업은 이부가격제로 가입비를 통해 소비자잉여를 가져가 이윤을 더 늘릴 수 있다.\n① 독점기업은 공급곡선이 존재하지 않는다.\n② 상대 산출량을 고정된 것으로 보는 것은 쿠르노 모형이다. 베르트랑은 상대 가격을 고정된 것으로 본다.\n④ 러너지수 (P-MC)/P는 이윤극대화점에서 1/|e|이다. 수요의 가격탄력성 자체와 같지 않고 그 역수이다.\n⑤ 한 상품이 다른 상품보다 품질이 좋다고 인식하게 하는 것은 수직적 차별화이다.","c":"상","v":1},"공인노2025_34-90":{"w":"⑤ 이윤극대화의 필요조건은 MR = MC이다.\n① 독점기업이 직면하는 것은 시장수요곡선이다.\n② 가격과 한계수입의 차이가 클수록 독점도가 크다.\n③ 제품 차별화가 클수록 대체재가 줄어 수요의 가격탄력성은 작아진다.\n④ 가격차별로 생산량이 늘면 사회후생이 증가할 수 있으므로 항상 감소하는 것은 아니다.","c":"상","v":1},"공인노2026_35-90":{"w":"④가 틀리다. 완전경쟁시장의 장기균형에서는 가격이 장기평균비용의 최저점으로 정해져 가격은 공급(비용) 측에서 결정되고, 거래량은 그 가격에서의 시장수요로 정해진다. 설명은 반대로 되어 있다.\n① 개별기업 단기공급곡선은 AVC 최저점 위의 MC곡선이다.\n② 시장 단기공급곡선은 기업별 공급곡선의 수평합이다.\n③ 비용이 일정한 산업의 장기공급곡선은 LAC 최저점에서 수평이다.\n⑤ 장기에는 LAC 최저점에서 생산한다.","c":"상","v":1},"공인노2026_35-91":{"w":"LAC_A = 900/Q − 30 + Q → 최저점 Q = 30, LAC = 30\nLAC_B = 400/Q − 20 + Q → 최저점 Q = 20, LAC = 20\n장기균형가격은 더 낮은 최저 평균비용 20이 되고, 이 가격에서 기술 A 기업은 손실을 보므로 기술 B 기업만 남는다.","c":"상","v":1},"공인노2026_35-92":{"w":"집단별 MR = f(Y) − 2Q = MC(c) → Q = (f(Y) − c)/2, P = (f(Y) + c)/2\nf(Y)는 소득의 증가함수이므로 소득이 높은 집단일수록 가격도 높고 판매량도 많다.","c":"상","v":1},"공인노2026_35-93":{"w":"ㄱ. 독점적 경쟁시장에서는 비슷한 상품을 파는 많은 기업이 같은 소비자 집단을 두고 경쟁한다. O\nㄴ. 각 기업은 차별화된 상품을 팔아 우하향하는 수요곡선에 직면하고 가격수용자가 아니다. O\nㄷ. 차별화가 클수록 대체재가 줄어 수요의 가격탄력성은 작아진다. X\nㄱ, ㄴ이므로 ③.","c":"상","v":1},"공인노2017_26-112":{"w":"효용극대화 조건: MUx/Px = MUy/Py\nX에서 MUx/Px = 600/200 = 3\nY에서 MUy/300 = 3 → MUy = 900 → 표에서 4개일 때 한계효용이 900이다. 효용을 극대화하는 Y의 소비량은 4개이므로 ④.","c":"상","v":1},"공인노2019_28-117":{"w":"② X MU_Y/MU_X > P_Y/P_X이면 MU_Y/P_Y > MU_X/P_X이다. 1원당 한계효용이 큰 Y재 소비를 늘리고 X재를 줄여야 효용이 커진다.\n①·③·④·⑤ O 무차별곡선 기울기(절댓값)는 한계대체율, 예산선 기울기는 가격비, 효용극대화는 두 선의 접점, 한계대체율은 한계효용의 비율이다.","c":"상","v":1},"공인노2019_28-119":{"w":"한 재화의 가격이 하락하면 실질소득이 늘어난 효과로 정상재인 두 재화의 소비가 모두 늘어난다. 이것이 소득효과이다(ㄱ). 또 가격이 상대적으로 싸진 재화의 소비는 늘고 비싸진 재화의 소비는 줄어드는 것이 대체효과이다(ㄴ).\nㄱ: 소득효과, ㄴ: 대체효과이므로 ①.","c":"상","v":1},"공인노2024_33-86":{"w":"ㄱ. 기펜재는 가격이 내리면 수요량이 감소하는 재화이다. 옳다.\nㄴ. 완전보완재는 대체효과가 0이고 가격효과 전체가 소득효과이다. 소득효과가 0이라는 것은 틀리다.\nㄷ. 열등재라도 대체효과가 소득효과보다 크면 수요곡선은 우하향한다. 우상향하는 것은 소득효과가 대체효과를 압도하는 기펜재이다. 틀리다.\nㄹ. 정상재는 가격이 내리면 대체효과와 소득효과가 모두 수요량을 늘린다. 옳다.\n옳지 않은 것은 ㄴ, ㄷ이므로 ②.","c":"상","v":1},"공인노2024_33-91":{"w":"콥-더글라스 수요: X = M/(3P_X), Y = 2M/(3P_Y). P_Y = 2P_X를 넣으면 Y = M/(3P_X) = X\n① O 두 재화 수요량이 같다.\n② X 소득 1단위 증가 시 두 재화 증가분은 모두 1/(3P_X)로 같다.\n③ X X재 수요는 P_Y와 무관하다.\n④ X MU_X/MU_Y < P_X/P_Y(=1/2)이면 X재를 줄여야 한다.\n⑤ X 가격이 같으면 Y = 2X다.","c":"상","v":1},"공인노2024_33-93":{"w":"가격소비곡선은 X재 가격이 바뀔 때 최적 소비점을 이은 선이다. 소득이 M일 때 Y재 지출 = M - P_X × X이다.\n① X재 수요의 가격탄력성이 1이면 X재 지출액 P_X × X가 가격과 관계없이 일정하다. Y재 지출과 Y재 수요량도 그대로라 가격소비곡선은 수평선이다. O\n② 탄력성이 1이면 X재 가격이 올라도 Y재 수요량은 변하지 않는다. X\n③ 탄력성이 1보다 작으면 X재 가격이 내려갈 때 X재 지출이 줄고 Y재 지출이 늘어 Y재 수요량이 증가한다. X\n④ 그 경우 X재 가격이 내려가며 X와 Y가 함께 늘어 가격소비곡선은 우상향한다. X\n⑤ 가격소비곡선에서 얻는 수요곡선은 소득을 고정한 보통수요곡선이다. X","c":"상","v":1},"공인노2024_33-95":{"w":"기대소득\n회사 취업: 0.9×600+0.1×300 = 570만 원\n창업: 0.2×1,850+0.8×250 = 370+200 = 570만 원\n두 선택의 기대소득은 같다.\n분산(만원²)\n회사 취업: 0.9×30²+0.1×270² = 810+7,290 = 8,100\n창업: 0.2×1,280²+0.8×320² = 327,680+81,920 = 409,600\n창업의 분산이 훨씬 크다.\n① 위험기피자는 기대소득이 같으면 위험이 작은 회사 취업을 택한다. 창업을 택한다는 것이 틀리다.\n④ 효용함수가 오목하면 위험기피자이므로 회사 취업을 택한다. 옳다.","c":"상","v":1},"공인노2025_34-85":{"w":"④ 소득효과는 가격 변화로 구매력(실질소득)이 달라져 생기는 소비량 변화이다. 옳다.\n① 슬러츠키 분해는 가격효과를 대체효과와 소득효과로 나눈다.\n② 열등재 등에서는 소득효과와 대체효과가 반대 방향이라 가격효과가 대체효과보다 작을 수 있다.\n③ 무차별곡선이 우하향 직선이면 완전대체재이다. 완전보완재는 L자형이다.\n⑤ 보상수요곡선은 소득효과를 제거한 수요곡선이다.","c":"상","v":1},"공인노2025_34-87":{"w":"U = X + 2Y는 완전대체재 효용함수다.\nㄱ O 무차별곡선은 기울기 −1/2인 직선이다.\nㄴ O MRS_XY = MU_X/MU_Y = 1/2로 일정하다.\nㄷ X 대체효과가 0인 것은 완전보완재다. 완전대체재는 상대가격이 바뀌면 소비가 한 재화로 통째로 옮겨 간다.\nㄹ O\nㅁ X MRS_XY < P_X/P_Y이면 X재가 상대적으로 비싸므로 Y재만 소비한다.","c":"상","v":1},"공인노2025_34-88":{"w":"① 소비자잉여는 소비자가 지불할 용의가 있는 금액에서 실제로 지불한 금액을 뺀 것이다. 실제 지불액과 시장가격의 차액이라는 설명은 틀리다.\n② 생산자잉여 = 실제 받은 금액-판매할 용의가 있는 금액이다.\n③ 보상변화는 가격변화 후에도 이전의 효용수준을 유지하기 위한 소득 조정액이다.\n④ 동등변화는 변화 전 가격에서 변화 후의 효용수준에 이르게 하는 소득 변화이다.\n⑤ 효용함수는 선호 서열을 나타내는 함수이다.","c":"중","v":1},"공인노2026_35-82":{"w":"3Y + 2Z 한 단위를 만드는 비용: Y로 만들면 9/3 = 3, Z로 만들면 8/2 = 4. Y만 쓴다.\n최적에서 X = 3Y. 예산: X + 9Y = 8 → X + 3X = 8 → X = 2","c":"상","v":1},"공인노2026_35-85":{"w":"소고기 가격만 올랐고 소득은 그대로이므로 실질소득이 줄었다. 대체효과는 돼지고기를 늘리는 방향이다. 그런데도 돼지고기를 덜 소비했다면 실질소득 감소에 따른 소득효과가 대체효과를 압도한 것이므로, 소득이 줄 때 소비가 줄어드는 정상재이다.\n① 돼지고기는 정상재이다. 옳다.\n② 열등재라면 실질소득 감소로 소비가 늘어난다.\n③ 소고기가 기펜재인지는 소고기 수요량이 가격 상승에 비해 반대로 움직여야 하는데, 소고기 소비는 줄었으므로 해당하지 않는다.\n④⑤ 주어진 정보로는 알 수 없다.","c":"하","v":1},"공인노2026_35-86":{"w":"ㄱ. 화폐소득이 오르면 예산선이 오른쪽으로 평행이동한다. X\nㄴ. 화폐소득모형에서 정상재는 가격이 내리면 대체효과와 소득효과가 모두 수요량을 늘린다. 같은 방향이다. O\nㄷ. 실물부존모형에서 부존량이 늘면 예산선이 평행이동한다. 회전이 아니다. X\nㄹ. 실물부존모형에서 가격이 바뀌면 부존점을 지나는 예산선이 부존점을 축으로 회전한다. O\nㄴ, ㄹ이므로 ③.","c":"상","v":1},"공인노2017_26-113":{"w":"③ X재 생산기술이 좋아지면 공급이 늘어 균형가격이 하락한다.\n① 인구가 늘면 수요가 늘어 가격이 오른다.\n② 정상재라면 소득 상승으로 수요가 늘어 가격이 오른다.\n④ 대체재 가격이 오르면 X재 수요가 늘어 가격이 오른다.\n⑤ 원료가격이 오르면 공급이 줄어 가격이 오른다.","c":"상","v":1},"공인노2017_26-114":{"w":"ㄱ. 최고가격이 균형가격보다 낮으면 암시장이 생길 수 있다. O\nㄴ. 균형가격보다 낮은 가격에서는 수요량이 공급량보다 많아 초과수요가 생긴다. O\nㄷ. 거래량이 줄어 사회적 후생(총잉여)이 감소한다. X\nㄹ. 균형가격보다 높은 최고가격은 효력이 없다. 균형가격보다 낮아야 한다. X\nㄱ, ㄴ이므로 ①.","c":"상","v":1},"공인노2017_26-115":{"w":"균형: 7-0.5Q = 2+2Q → 2.5Q = 5 → Q = 2, P = 2+2×2 = 6\n공급곡선 Q = (P-2)/2, dQ/dP = 0.5\n공급의 가격탄력성 = 0.5×P/Q = 0.5×6/2 = 1.5이므로 ④.","c":"상","v":1},"공인노2017_26-117":{"w":"수요의 가격탄력성이 0이면 수요곡선이 수직이다. 세금이 붙어 가격이 올라도 수요량이 변하지 않으므로 소비자가 세금 전액을 부담한다. 조세부담은 모두 소비자에게 귀착되어 ①.","c":"상","v":1},"공인노2019_28-111":{"w":"사적재 시장수요는 같은 가격에서 수요량을 더한 수평합이다.\nP ≤ 5에서 Q = (10 − 2P) + (15 − 3P) = 25 − 5P\n두 사람 모두 P = 5에서 수요량이 0이 되므로 구간이 나뉘지 않는다.","c":"상","v":1},"공인노2019_28-112":{"w":"⑤ 보완재인 설탕 가격이 오르면 설탕 소비가 줄고 함께 쓰는 커피 수요도 줄어 수요곡선이 왼쪽으로 이동한다.\n① 커피 가격 하락은 수요곡선 위의 이동(수요량 증가)이다.\n②③ 소득 증가와 선호 증가는 수요곡선을 오른쪽으로 이동시킨다.\n④ 대체재 가격 상승은 커피 수요를 늘린다.","c":"상","v":1},"공인노2019_28-113":{"w":"P = 2일 때 Q = 10 × 2 − 4 = 16\n공급의 가격탄력성 = (dQ/dP) × (P/Q) = 10 × 2/16 = 1.25","c":"상","v":1},"공인노2019_28-116":{"w":"⑤가 틀리다. 조세는 탄력성이 낮은 쪽이 더 많이 부담한다. 수요의 가격탄력성이 공급보다 크면 수요자는 소비를 쉽게 줄일 수 있어 수요자의 부담이 작고 공급자의 부담이 크다.\n① 공급자 과세는 공급곡선을 위로 올려 소비자가 내는 가격이 오른다.\n② 수요자 과세는 수요곡선을 아래로 내려 균형가격(공급자 수취가격)이 내린다.\n③④ 법적 납세자와 무관하게 조세수입과 자중손실은 같다.","c":"상","v":1},"공인노2022_31-101":{"w":"X재 가격이 오르면 대체재인 Y재의 수요가 늘어 Y재 수요곡선이 오른쪽으로 이동하고, Y재의 균형가격은 상승한다. ㄱ 수요, ㄴ 우측, ㄷ 상승이므로 ①.","c":"상","v":1},"공인노2022_31-106":{"w":"② 물품세를 내리면 소비자가 내는 가격이 내려가지만 100원 전액은 아니다. 생산자가 받는 가격도 올라 인하 혜택이 소비자와 생산자에게 나뉘어 귀착된다.\n① 소비자 가격은 100원보다 적게 내린다.\n③ 가격이 내리면 소비량이 늘어난다.\n④ 세금이 줄면 자중손실이 줄어든다.\n⑤ 물품세는 거래량을 왜곡하는 왜곡적 조세이다.","c":"상","v":1},"공인노2024_33-81":{"w":"① 수요가 줄고 공급이 늘면 가격은 반드시 내리지만 거래량은 두 곡선의 이동 폭에 따라 달라진다. 증가한다고 단정할 수 없어 틀리다.\n② 수요와 공급이 같은 폭으로 줄면 거래량만 감소하고 가격은 그대로이다.\n③ 요소가격이 내리면 공급이 늘어 거래량이 증가한다.\n④ 수요 증가·공급 감소는 모두 가격을 올린다.\n⑤ 수요와 공급이 함께 늘면 거래량은 반드시 증가한다.","c":"상","v":1},"공인노2024_33-82":{"w":"ㄱ. 균형가격 아래에 가격상한을 두면 물건을 산 소비자는 더 싼 값을 내므로 생산자잉여의 일부가 소비자잉여로 옮겨 간다. O\nㄴ. 노동시장에서 노동을 공급하는 쪽은 근로자이다. 최저임금이 균형보다 높으면 일자리를 지킨 근로자는 더 높은 임금을 받아 공급자 잉여가 늘 수 있고 일자리를 잃은 근로자 몫은 줄어든다. 공급자 잉여가 감소한다고 단정할 수 없다. X\nㄷ. 공급곡선이 수평(완전탄력적)이면 가격이 한계비용과 늘 같아 생산자잉여는 0이다. O\nㄱ, ㄷ이므로 ④.","c":"중","v":1},"공인노2024_33-94":{"w":"수요곡선 P = b − (b/a)Q에서 E_P = (a − Q)/Q = P/(b − P)\n③ X E_P > 1(탄력적)이면 가격을 올릴 때 총수입이 줄어든다.\n① O Q < a/2이면 (a − Q)/Q > 1\n② O P가 b에 가까워질수록 P/(b − P)가 커진다.\n④ O 같은 Q에서 a가 클수록 (a − Q)/Q가 크다.\n⑤ O 같은 P에서 b가 클수록 P/(b − P)가 작다.","c":"상","v":1},"공인노2024_33-96":{"w":"공급함수 Q = P/2 - 6을 고치면 P = 2Q + 12이다. 거래량 5에서 가격은 22이고, 수요가 완전탄력적이라 소비자가격은 22로 고정된다.\n세금 2를 내면 생산자 수취가격이 20이 되어 Q = 20/2 - 6 = 4이다(① O).\n조세수입 = 2 × 4 = 8(② O). 생산자잉여 감소 = 조세수입 8 + 자중손실 1/2 × 2 × 1 = 9(③ O).\n자중손실 1은 생산자잉여 감소분 9와 같지 않다. ④가 틀리다.\n소비자가격이 그대로라 세금은 모두 생산자가 진다(⑤ O).","c":"상","v":1},"공인노2025_34-81":{"w":"보조금 전: 200 − P = P − 2 → P = 101, Q = 99\n소비자 보조 2: 수요가 Q = 202 − P로 이동 → 202 − P = P − 2 → P = 102, Q = 100\n보조금 지급액 = 2 × 100 = 200\n사중손실 = 1/2 × 2 × (100 − 99) = 1","c":"상","v":1},"공인노2025_34-82":{"w":"ㄱ. 소득탄력성은 소득 변화에 대한 수요의 반응 정도이다. O\nㄴ. 소득이 늘 때 수요가 줄면 열등재이다. O\nㄷ. 수요증가율이 소득증가율보다 크면 사치재이다. 필수재는 정상재 중 소득탄력성이 0과 1 사이인 것이다. X\nㄹ. 교차탄력성의 정의이다. O\nㅁ. 대체재의 교차탄력성은 0보다 크다. X\nㄱ, ㄴ, ㄹ이므로 ②.","c":"상","v":1},"공인노2025_34-91":{"w":"8 − 0.25P = 0.5P − 4 → P = 16, Q = 4\n공급곡선은 P = 8에서 Q = 0이므로 생산자잉여 = 1/2 × (16 − 8) × 4 = 16","c":"상","v":1},"공인노2025_34-92":{"w":"수요의 가격탄력성이 무한대이면 수요곡선이 수평이다. 세금이 붙어도 소비자가 내는 가격은 변하지 않으므로 소비자는 부담하지 않고, 조세부담이 모두 생산자에게 귀착된다. ②.","c":"상","v":1},"공인노2026_35-81":{"w":"24 − 3P = P → P = 6, Q = 6 (①·② O)\n③ O 수요탄력성 = 3 × 6/6 = 3\n④ O 공급탄력성 = 1 × 6/6 = 1이고, 공급곡선 P = Q의 기울기도 1이다.\n⑤ X 수요곡선의 가격 절편은 8. 소비자잉여 = 1/2 × (8 − 6) × 6 = 6, 생산자잉여 = 1/2 × 6 × 6 = 18","c":"상","v":1},"공인노2026_35-83":{"w":"과세 전: 120 − P/2 = P − 3 → P = 82, Q = 79\n과세 후(소비자가격 P_c, 생산자가격 P_c − 6): 120 − P_c/2 = P_c − 9 → P_c = 86, P_s = 80, Q = 77\n소비자잉여 감소 = 4 × (79 + 77)/2 = 312, 생산자잉여 감소 = 2 × 78 = 156\n수요가 공급보다 가격에 덜 반응해 소비자 부담이 크다.","c":"상","v":1},"공인노2026_35-84":{"w":"단위당 세금 t: 5 − P_c/2 = P_c − t → P_c = (10 + 2t)/3, Q = P_c − t = (10 − t)/3\n조세수입 T = t(10 − t)/3 → dT/dt = (10 − 2t)/3 = 0 → t = 5","c":"상","v":1},"공인노2017_26-116":{"w":"② 굴절수요곡선은 굴절점을 경계로 위쪽은 탄력적, 아래쪽은 비탄력적이어서 원점에 대해 오목한 모양이다. 볼록하다는 것이 틀리다.\n① 굴절점에서 한계수입곡선이 끊어진다(불연속).\n③ 한 기업이 가격을 내리면 다른 기업들이 따라 내린다.\n④ 가격을 올리면 따라 올리지 않는다.\n⑤ 한계비용이 불연속 구간 안에서 변해도 가격과 수량이 바뀌지 않아 가격이 경직적이다.","c":"상","v":1},"공인노2019_28-110":{"w":"A국 우월전략: B국이 무관세일 때 무관세 300 > 관세 150, B국이 관세일 때 무관세 400 > 관세 200. 항상 무관세가 낫다. 따라서 A국의 우월전략은 무관세이다. 관세가 우월전략이라는 ①이 틀리다.\nB국 우월전략: A국이 무관세일 때 무관세 250 > 관세 100, A국이 관세일 때 무관세 300 > 관세 200. 무관세. ② 옳다.\n내쉬균형은 (무관세, 무관세)로 보수 (300, 250)이다. ③ 옳다.\n(300, 250)에서 한 사람의 보수를 올리려면 다른 사람 보수가 줄어드므로 파레토 효율적이다. ④ 옳다.\n우월전략균형은 내쉬균형이다. ⑤ 옳다.","c":"상","v":1},"공인노2022_31-105":{"w":"A: B가 광고함이면 광고함 6 > 광고 안함 3, B가 광고 안함이면 광고함 8 < 광고 안함 10. 우월전략이 없다.\nB: A가 광고함이면 광고함 4 > 3, A가 광고 안함이면 광고함 8 > 4. B의 우월전략은 광고함이다.\nB가 광고함을 택하므로 A의 최선은 광고함이고 내쉬균형은 (광고함, 광고함)의 보수 (6, 4)이다. ①.\n⑤ (10, 4)가 (6, 4)보다 A에게 낫고 B에게 같으므로 내쉬균형은 파레토 효율적이 아니다.","c":"상","v":1},"공인노2024_33-87":{"w":"각자의 최선응답을 구한다.\nA의 최선응답: B가 높은 보조금이면 A는 높음(600), B가 중간이면 A는 중간(550), B가 낮음이면 A는 중간(350).\nB의 최선응답: A가 높음이면 B는 낮음(650), A가 중간이면 B는 중간(500), A가 낮음이면 B는 높음(750).\n서로 최선응답인 칸은 (중간, 중간) (550, 500)이므로 ③.","c":"상","v":1},"공인노2025_34-89":{"w":"기업 i 반응함수: 20 − 2q_i − q_j = 8 → q_i = (12 − q_j)/2\n대칭 균형 q₁ = q₂ = 4, Q = 8, P = 20 − 8 = 12","c":"상","v":1},"공인노2025_34-96":{"w":"E: H가 광고함이면 광고함 10 > 3, H가 광고 안함이면 광고함 8 > 6. E의 우월전략은 광고함이다. ② 옳다.\nH: E가 광고함이면 광고함 4 > 3, E가 광고 안함이면 광고함 8 > 4. H의 우월전략도 광고함이다. ③ 옳다.\n따라서 내쉬균형은 둘 다 광고함이고 보수는 (10, 4)이다. ④⑤ 옳다.\n① 내쉬균형의 보수조합이 (6, 4)라는 것이 틀리다.","c":"상","v":1},"공인노2026_35-94":{"w":"역수요 P = 20 − Q. 추종기업 반응함수: q_B = (12 − q_A)/2\n선도기업 이윤 = (20 − q_A − q_B − 8)q_A = q_A(12 − q_A)/2 → q_A = 6, q_B = 3\n생산량 차이 = 3","c":"상","v":1},"공인노2026_35-95":{"w":"(남쪽, 동쪽)이 내쉬균형이 되려면 두 사람 모두 그 칸에서 방향을 바꿔도 이득이 없어야 한다.\n갑: 을이 동쪽일 때 남쪽 10 ≥ 북쪽 B → B < 10\n을: 갑이 남쪽일 때 동쪽 D ≥ 서쪽 C → C < D\n따라서 B < 10, C < D이므로 ①.","c":"상","v":1},"공인노2017_26-118":{"w":"ㄱ. 평균비용 = 평균가변비용+평균고정비용이므로 평균비용곡선이 위에 있다. O\nㄴ. 평균비용이 상승하는 구간에서는 한계비용이 평균비용보다 위에 있다. X\nㄷ. 평균고정비용은 산출량이 늘수록 줄어 우하향한다. O\nㄹ. 총비용에서 고정비용은 상수이므로 총가변비용곡선과 총비용곡선의 기울기는 같다(둘 다 한계비용). X\nㅁ. 평균비용 = 평균고정비용+평균가변비용. O\nㄱ, ㄷ, ㅁ이므로 ②.","c":"상","v":1},"공인노2017_26-120":{"w":"평균노동생산성은 생산량 ÷ 노동투입량으로, 원점과 각 점을 잇는 직선의 기울기다.\nE는 노동투입량이 가장 많은 편인데 생산량은 D와 같이 낮은 편이라 원점에서 그은 직선의 기울기가 가장 완만하다.\n평균노동생산성이 가장 낮은 기업은 E이다.","c":"상","v":1},"공인노2019_28-114":{"w":"②가 틀리다. 평균비용이 상승하는 구간에서는 한계비용이 평균비용보다 위에 있다(한계비용이 평균을 끌어올린다).\n① 평균비용 = 평균가변비용+평균고정비용이므로 평균비용곡선이 위에 있다.\n③ 원점에서 총비용곡선에 그은 접선 지점에서 평균비용(원점과 이은 직선의 기울기)이 최소이다.\n④ 원점에서 총가변비용곡선에 그은 접선 지점에서 평균가변비용이 최소이다.\n⑤ 총비용곡선의 접선 기울기가 한계비용이다.","c":"상","v":1},"공인노2019_28-122":{"w":"화폐 1원당 한계생산을 비교한다.\n자본: MPk/Pk = 5/12 ≈ 0.417\n노동: MPl/Pl = 8/25 = 0.32\n자본이 1원당 한계생산이 더 높으므로 자본을 늘리고 노동을 줄이면 같은 비용으로 산출이 늘어난다. 노동 감소, 자본 증가이므로 ②.","c":"상","v":1},"공인노2022_31-102":{"w":"모든 투입요소를 t배 했을 때 산출이 t배보다 크면 체증, 같으면 불변, 작으면 체감이다.\nㄱ. q = 2L+3K → 1차동차, 불변\nㄴ. q = (2L+K)^(1/2) → 1/2차동차, 체감\nㄷ. q = 2LK → 2차동차, 체증\nㄹ. q = L^(1/3)K^(2/3) → 지수 합 1, 불변\nㅁ. q = 3L^(1/2)+3K → 3(tL)^(1/2)+3tK < t(3L^(1/2)+3K) 이므로 체감\n체증은 ㄷ, 불변은 ㄱ(ㄹ), 체감은 ㄴ(ㅁ)의 순서이므로 ③ ㄷ-ㄱ-ㄴ.","c":"상","v":1},"공인노2024_33-84":{"w":"Q = √(2K + L)은 등량곡선이 2K + L = Q²인 직선이다.\n① X 투입을 2배로 하면 Q는 √2배 → 규모수확체감\n② X 등량곡선(K축 세로) 기울기 = −MP_L/MP_K = −1/2\n③ X 완전대체재다.\n④ O 직선 등량곡선과 등비용선 기울기가 다르면 한 요소만 쓰는 모서리해가 된다.\n⑤ X MRTS는 1/2로 일정하다.","c":"상","v":1},"공인노2024_33-92":{"w":"1원당 한계생산: 자본 4/9, 노동 1/3(= 3/9) → 자본만 쓴다.\n4K = 200 → K = 50, 자본 투입액 = 9 × 50 = 450, 노동 투입액 0","c":"상","v":1},"공인노2025_34-83":{"w":"Q = 9 × 8^(1/3) × 27^(2/3) = 9 × 2 × 9 = 162\nMP_K = 9 × (2/3) × L^(1/3) × K^(−1/3) = 6 × 2/3 = 4\nAP_K = 162/27 = 6","c":"상","v":1},"공인노2025_34-84":{"w":"⑤ 규모의 경제는 산출량이 늘어날수록 장기평균비용이 줄어드는 현상이다.\n① 투입요소를 일정 비율로 늘릴 때 산출량이 같은 비율로 늘면 규모에 대한 수익불변이다.\n② 여러 제품을 함께 생산해 비용이 낮아지는 것은 범위의 경제이다.\n③ 규모의 경제에서는 장기한계비용이 장기평균비용보다 작다.\n④ 산출량이 더 작은 비율로 늘어나는 것이 규모에 대한 수익체감이다.","c":"상","v":1},"공인노2025_34-86":{"w":"② 한계비용이 평균총비용보다 작으면 추가 1단위의 비용이 평균보다 작아 평균총비용이 감소한다.\n① 한계비용이 평균총비용보다 작은 구간에서도 한계비용은 증가할 수 있다.\n③⑤ 평균고정비용은 산출량이 늘수록 감소한다.\n④ 평균가변비용은 항상 감소하는 것이 아니다.","c":"상","v":1},"공인노2026_35-87":{"w":"MRTS_LK = MP_L/MP_K = 5/2로 투입량과 관계없이 일정하다. 선형 생산함수라 등량곡선이 직선이다.","c":"상","v":1},"공인노2026_35-88":{"w":"min(X₁, X₂) 1단위 비용 = 2 + 1 = 3, min(X₃, X₄) 1단위 비용 = 5 + 3 = 8\n두 항은 완전대체이므로 싼 쪽만 쓴다. Q = 1의 최소비용 = 3","c":"상","v":1},"공인노2026_35-89":{"w":"K = 2: Q = 2√L → L = Q²/4\nSTC = 6 × Q²/4 + 2 × 2 = 1.5Q² + 4\nSMC = 3Q","c":"상","v":1},"공인노2017_26-119":{"w":"완전경쟁기업은 노동의 한계생산가치와 임금이 같아지는 곳에서 고용한다.\nVMPL = P×MPL = 20×(27-5L) = 540-100L\n540-100L = 40 → L = 5이므로 ⑤.","c":"상","v":1},"공인노2017_26-121":{"w":"생산물 가격이 내리면 노동의 한계생산가치(P×MPL)가 줄어 노동수요곡선이 왼쪽으로 이동한다. 노동공급은 그대로이므로 균형에서 임금은 하락하고 고용량은 감소한다. ③.","c":"상","v":1},"공인노2017_26-122":{"w":"임금이 오르면 여가의 기회비용이 올라 여가를 줄이고 노동을 늘리는 대체효과가 있고, 소득이 늘어 정상재인 여가를 더 소비하는 소득효과가 있다. 임금 상승에도 노동공급이 줄어든다면 소득효과가 대체효과보다 크다(ㄱ 대체, ㄴ 소득).\n여가의 기회비용이 오르는 데 반응해 여가를 줄이는 것이 대체효과이므로 ㄷ은 여가이다. 노동공급곡선은 우상향한다.\n①.","c":"상","v":1},"공인노2017_26-125":{"w":"이윤극대화 조건은 임금 = 한계생산가치, 즉 w = P×MPL이다. 이때 P = MC이므로\nMC = w/MPL = 20,000/5 = 4,000원이므로 ②.","c":"상","v":1},"공인노2019_28-120":{"w":"ㄱ. 지니계수가 클수록 불평등하다. X\nㄴ. 로렌츠곡선이 대각선에 가까울수록 더 평등하다. O\nㄷ. 지니계수가 커지면 하위 40%의 소득을 상위 20%의 소득으로 나눈 십분위분배율은 작아진다. O\nㄹ. 로렌츠곡선이 대각선과 일치하면 완전평등이고 지니계수는 0이다. X\nㄴ, ㄷ이므로 ③.","c":"상","v":1},"공인노2019_28-123":{"w":"완전경쟁 기업은 생산물시장에서 가격 = 한계비용(ㄱ)에서 생산량을 정한다. 노동시장에서는 임금 = 한계생산가치(P×MPL)(ㄴ)에서 노동수요량을 정한다. ①.","c":"상","v":1},"공인노2019_28-124":{"w":"1,000 − W = −100 + W → W* = 550, L* = 1,000 − 550 = 450","c":"상","v":1},"공인노2022_31-108":{"w":"① 로렌츠곡선이 대각선에 가까울수록 소득분배가 평등하므로 지니계수는 작아진다. 커진다는 것이 틀리다.\n② 지니계수는 0~1이고 작을수록 평등하다.\n③ 로렌츠곡선의 정의이다.\n④ 십분위분배율 = 하위 40% 소득점유율/상위 20% 소득점유율이다.\n⑤ 십분위분배율은 0~2이고 클수록 평등하다.","c":"상","v":1},"공인노2022_31-120":{"w":"생산함수 Q = -4L²+100L에서 MPL = 100-8L\n노동의 한계생산가치 = 50×(100-8L) = 5,000-400L = w\nw = 1,000: L = 10\nw = 3,000: L = 5\n노동수요량이 5 감소하므로 ②.","c":"상","v":1},"공인노2022_31-121":{"w":"⑤ 숙련노동과 미숙련노동의 임금격차는 노동의 한계생산물 가치 차이에 영향을 받는다. 옳다.\n① 보상적 임금격차는 근로자가 위험을 싫어하므로 위험한 직종에 높은 임금을 주어야 한다는 이론이다.\n② 동등보수는 같은 가치(직무)의 일에 같은 임금을 주는 것이다.\n③ 유보임금은 개인마다 다르다.\n④ 이중노동시장에서 1차와 2차 시장 간 이동을 막는 것은 시장 장벽이다.","c":"상","v":1},"공인노2022_31-122":{"w":"노동수요의 임금탄력성을 작게 하는 요인이 무엇인지 고른다(마샬의 파생수요 법칙).\nㄱ. 노동과 다른 요소의 대체탄력성이 커지면 노동을 쉽게 다른 요소로 바꿀 수 있어 탄력성이 커진다. X\nㄴ. 총비용에서 노동비용 비중이 커지면 임금 변화가 비용에 큰 영향을 미쳐 탄력성이 커진다. X\nㄷ. 상품 수요의 가격탄력성이 작아지면 노동수요의 탄력성도 작아진다. O\nㄷ만 해당하므로 ③.","c":"상","v":1},"공인노2022_31-123":{"w":"③ 전용수입은 요소를 현재 용도에 계속 쓰기 위해 지급해야 하는 최소한의 보수이다. 옳다.\n① 공급이 고정된(공급곡선이 수직인) 요소에 대한 대가는 전액 경제적 지대이다.\n② 공급곡선이 수평이면 보수 전액이 전용수입이다.\n④ 지대의 비중이 높다는 것은 공급이 비탄력적이라는 뜻이므로 다른 요소로 대체하기 쉬운 것과 관계가 없다.\n⑤ 지대 비중이 높은 노동은 임금이 올라도 공급량이 쉽게 늘지 않는다.","c":"상","v":1},"공인노2024_33-114":{"w":"① 자본 가격이 내리면 노동을 자본으로 바꾸는 대체효과가 생겨 노동수요는 감소한다. 대체효과가 노동수요를 증가시킨다는 것이 틀리다.\n② 제품수요의 가격탄력성이 클수록 노동수요의 가격탄력성이 크다.\n③ 장기에는 자본으로 대체할 여지가 커 노동수요가 더 탄력적이다.\n④ 자본공급이 탄력적일수록 노동수요가 탄력적이다.\n⑤ 대체탄력성이 클수록 노동수요가 탄력적이다.","c":"상","v":1},"공인노2024_33-115":{"w":"예산선은 I = w(T - H) + A, 기울기는 -w이다.\n① 내부해에서 무차별곡선과 예산선이 접하므로 MRS_H,I = w. O\n② 임금이 오르면 실질소득이 늘어 정상재인 여가가 늘고 노동공급이 준다. 소득효과는 노동공급을 줄인다. O\n③ 여가가 열등재면 소득효과도 여가를 줄이므로 대체효과와 함께 노동공급이 늘어난다. O\n④ 임금이 오르면 여가의 상대가격이 올라 대체효과는 노동공급을 늘린다. O\n⑤ 근로외소득 A가 늘면 예산선이 평행 이동할 뿐 임금은 그대로다. 대체효과는 없고 소득효과만 있어 노동공급이 준다. ⑤가 틀리다.","c":"상","v":1},"공인노2024_33-119":{"w":"균형: 20 + 2w = 50 − 4w → w = 5, L = 30\n최저임금 6: 수요 = 50 − 24 = 26, 공급 = 20 + 12 = 32\n고용 감소 = 30 − 26 = 4, 실업자 = 32 − 26 = 6","c":"상","v":1},"공인노2025_34-94":{"w":"⑤ 십분위분배율은 클수록 소득분배가 균등하다.\n① 지니계수가 커지면 불평등이 커진다.\n② 같은 지니계수를 갖는 두 로렌츠곡선도 서로 교차할 수 있다.\n③ 모든 소득이 한 사람에게 집중되면 로렌츠곡선은 대각선에서 가장 멀어진 직각 모양이다.\n④ 상위 10%가 소득의 40%를 벌면 불균등하여 로렌츠곡선이 대각선 아래에 있다.","c":"상","v":1},"공인노2025_34-113":{"w":"한 시간당 가치\n남편: 가구생산 1만 원, 근로 2만 원\n아내: 가구생산 2.5만 원, 근로 1.5만 원\n근로 1시간의 기회비용(포기하는 가구생산)은 남편 1만 원, 아내 2.5만 원이다.\n① 가구생산만 하던 두 사람 중 한 명이 근로 1시간을 해야 한다면 기회비용이 낮은 남편이 한다. 옳다.\n② 21만 원을 벌려면 남편이 10시간 일해 20만 원을 벌고 모자란 1만 원은 아내가 약 40분(1만 ÷ 1.5만 시간) 일해 채운다. 남편 7시간과 아내 4시간이면 14만 + 6만 = 20만 원이다. 틀리다.\n③ 남편은 근로의 기회비용이 낮아 비교우위가 근로에 있다.\n④ 결혼 후 기회집합이 넓어지는 것은 비교우위에 따른 전문화 덕분이다.\n⑤ 두 사람의 기회비용이 달라 가구 예산선은 남편이 근로를 다 채운 점에서 굴절된다.","c":"중","v":1},"공인노2025_34-115":{"w":"P × MP_L = w → 10(−10L + 30) = 100 → −10L + 30 = 10 → L = 2","c":"상","v":1},"공인노2025_34-116":{"w":"ㄱ. 고용주의 선호차별은 차별하는 고용주가 이윤을 포기하므로 경쟁에서 밀려나 사라진다(베커). O\nㄴ. 고객 선호에 따른 차별은 고객 접촉이 많은 직종에서 직종분리를 낳는다. O\nㄷ. 고객 차별을 받는 집단이 파는 재화는 오히려 수요가 줄어든다. X\nㄹ. 통계적 차별은 편견 없이도 집단의 평균적 특성으로 개인을 판단하는 데서 생긴다. O\nㄱ, ㄴ, ㄹ이므로 ④.","c":"상","v":1},"공인노2025_34-118":{"w":"과세 전: W + 10 = −2W + 20 → W = 10/3, L = 40/3\n기업에 1 부과(근로자 수취임금 W 기준 수요 L = −2(W + 1) + 20): W + 10 = −2W + 18 → W = 8/3, L = 38/3\n사중손실 = 1/2 × 1 × (40/3 − 38/3) = 1/3","c":"상","v":1},"공인노2025_34-119":{"w":"② 등이윤곡선은 아래쪽에 있을수록 임금이 낮아 기업 이윤이 크다. 위에 있는 것이 이윤이 크다는 것이 틀리다.\n① 안전한 환경에는 비용이 들어 부상확률을 낮추면 임금을 낮춰야 이윤이 같아지므로 등이윤곡선은 우상향한다.\n③ 근로자 무차별곡선의 기울기는 위험이 조금 늘 때 요구하는 임금 보상이다.\n④ 근로자와 기업은 두 곡선이 접할 때 매칭된다.\n⑤ 완전경쟁에서는 초과이윤이 0이므로 이윤 0인 등이윤곡선 위에 있다.","c":"상","v":1},"공인노2025_34-120":{"w":"④ 능력이 같아도 할인율이 높은 사람은 교육의 미래 수익을 낮게 평가해 교육년수를 짧게 선택한다. 교육년수가 같다는 것은 틀리다.\n① 임금-학력 곡선은 인적자본 축적으로 우상향한다.\n② 곡선의 기울기가 교육의 한계수익률이다.\n③ 능력이 다르면 곡선도 다르다.\n⑤ 수확체감으로 기울기가 점점 완만해진다.","c":"상","v":1},"공인노2026_35-113":{"w":"완전소득 = 8 × 30 = 240. U = CR²은 콥-더글라스형이라 여가에 2/3를 쓴다.\n8R = 240 × 2/3 = 160 → R = 20, 노동시간 = 30 − 20 = 10","c":"상","v":1},"공인노2026_35-114":{"w":"P × MP_L = w: 36 × 1/(2√L) = w → √L = 18/w → L = 324/w²\nw = 2: L = 81, w = 1: L = 324\n변화분 = 243 (생산함수가 분리형이라 자본가격은 노동수요에 영향이 없다.)","c":"상","v":1},"공인노2026_35-115":{"w":"Q < 10 구간: 이윤 = √L − wL → 1/(2√L) = w → L = 1/(4w²)\nL이 100을 넘으면 생산량이 10에서 늘지 않아 노동을 더 쓸 이유가 없다.\n노동수요 L = min(1/(4w²), 100)","c":"상","v":1},"공인노2026_35-116":{"w":"기업당 노동 = 500/30 = 50/3\nw = P × MP_L = 3 × (200 − 2 × 50/3) = 3 × 500/3 = 500","c":"상","v":1},"공인노2026_35-120":{"w":"수요독점 기업은 노동을 더 쓸수록 모든 노동자의 임금을 올려야 하므로 노동의 한계요소비용이 임금보다 높다. 한계요소비용 = 한계생산가치에서 고용을 정하므로 고용량이 경쟁 노동시장보다 적고, 임금은 한계생산가치보다 낮아 경쟁 때보다 하락한다. ㄱ 하락, ㄴ 감소이므로 ④.","c":"상","v":1},"공인노2019_28-107":{"w":"③ X 지수 합 1/3 + 2/3 = 1이므로 규모수확불변이다.\n① O 노동탄력성은 지수 2/3이다.\n② O 기술진보는 A를 높인다.\n④ O 성장률 = A 증가율 + (1/3)K 증가율 + (2/3)L 증가율\n⑤ O 완전경쟁이면 노동소득분배율 = 2/3","c":"상","v":1},"공인노2024_33-100":{"w":"성장회계식: g_Y = g_A + 0.4g_K + 0.6g_L\n0.02 = 0.05 + 0.4g_K + 0.6 × (−0.08) → 0.4g_K = 0.018 → g_K = 0.045","c":"상","v":1},"공인노2024_33-104":{"w":"Y = 2K^0.5(LE)^0.5는 규모수익불변이다. 인구증가율 n = -3%, 효율성 증가율 g = 5%이다.\n균제상태에서 유효노동 1단위당 자본·생산량은 일정하다(①④ 0% O).\n총생산과 총자본은 n + g = 2%로 늘어난다(② O).\n노동자 1인당 생산량과 1인당 자본량은 g = 5%로 늘어난다(③ O). 1인당 자본량 3%라는 ⑤가 틀리다.","c":"상","v":1},"공인노2024_33-105":{"w":"y = Ak이면 1인당 자본 증가율 = sA − (n + δ)로 늘 일정하다.\nㄱ O s가 오르면 성장률이 높아진다.\nㄴ X n이 높으면 성장률이 낮아진다.\nㄷ O y = Ak라 y와 k의 증가율이 같다.\nㄹ O 이행 과정 없이 처음부터 일정한 성장률로 성장한다.","c":"상","v":1},"공인노2026_35-107":{"w":"인구증가가 없으므로 황금률 조건은 f′(k) = δ: 1/√k = 0.1 → k = 100, y = 20\n정상상태 sy = δk → s × 20 = 10 → s = 0.5","c":"상","v":1},"공인노2022_31-111":{"w":"생산에 필요한 노동량이 A국은 자동차 10·옷 5, B국은 자동차 6·옷 2이다.\n기회비용: A국 자동차 1대 = 옷 2벌, B국 자동차 1대 = 옷 3벌. A국 옷 1벌 = 자동차 0.5대, B국 옷 1벌 = 자동차 1/3대.\n자동차는 기회비용이 낮은 A국이, 옷은 B국이 비교우위이다(①②).\n③ B국의 자동차 생산의 기회비용은 옷 3벌이다. 2벌이라는 것이 틀리다.\n④ 옷 생산에 B국이 더 적은 노동(2<5)을 쓰므로 절대우위이다.\n⑤ 비교우위 산업에 특화해 교역하면 서로 이익이다.","c":"상","v":1},"공인노2024_33-110":{"w":"A국은 X 2·Y 4, B국은 X 4·Y 6의 노동이 든다.\n① A국은 두 재화 모두 더 적은 노동으로 생산하므로 절대우위. 옳다.\n② A국 X재 1단위의 기회비용은 2/4 = 1/2 단위의 Y재. 옳다.\n③ A국 총노동 20: X 6단위(12)+Y 2단위(8) = 20. 옳다.\n④ B국에서 Y재 1단위를 얻으려면 X재를 6/4 = 3/2 단위 포기하므로 Y재의 상대가격은 X재 3/2이다. Y재 1단위에 대한 X재의 상대가격(Px/Py)은 4/6 = 2/3이므로 3/2라는 것이 틀리다.\n⑤ 비교우위가 B국은 Y재(기회비용 3/2 < A국의 2)이므로 완전특화하면 Y재 60/6 = 10단위. 옳다.","c":"중","v":1},"공인노2024_33-109":{"w":"ㄱ. 합리적 기대에 따르면 예상된 정책은 효과가 없다는 정책무력성정리는 새고전학파 이론이다. O\nㄴ. 총수요 외부성은 새케인즈학파의 이론이다. 실물경기변동이론이 아니다. X\nㄷ. 케인즈학파는 경기침체의 원인을 총수요 부족으로 본다. O\nㄹ. 비동조적(엇갈린) 가격설정은 새케인즈학파의 모형이다. O\nㄱ, ㄷ, ㄹ이므로 ⑤.","c":"상","v":1},"공인노2024_33-120":{"w":"④ 실물경기변동이론에서 양(+)의 기술충격은 노동의 한계생산을 높여 노동수요를 늘리므로 실질임금이 상승한다. 옳다.\n① 명목임금경직성 모형에서 총수요 충격으로 물가가 오르면 실질임금이 하락하면서 산출이 늘어 실질임금은 경기역행적이다.\n② 중첩임금계약에서도 총수요 충격에 대해 실질임금이 경기역행적이다.\n③ 효율성임금이론은 실질임금의 경직성을 설명하는 이론이다.\n⑤ 노동공급곡선이 수평이면 기술충격이 있어도 실질임금이 변하지 않아 경기순행적이 아니다.","c":"중","v":1},"공인노2026_35-100":{"w":"③ 고전학파에서 투자가 외생적으로 늘면 대부자금 수요가 늘어 이자율이 상승한다. 이자율이 하락한다는 것이 틀리다.\n① 완전고용이 성립한다.\n② 가격과 임금이 신축적이다.\n④ 세이의 법칙은 공급이 스스로 수요를 창출한다는 것이다.\n⑤ 고전적 이분법에 따라 화폐는 중립적이다.","c":"상","v":1},"공인노2026_35-103":{"w":"④ 맨큐는 메뉴비용 때문에 가격이 경직적이 되고 이것이 경기변동을 낳는다고 설명했다. 신축적 가격변동으로 경기변동을 설명한 것이 아니다. 틀리다.\n① 케인즈는 재정정책을 강조했다.\n② 프리드먼은 연준의 통화정책 실패가 대공황을 낳았다고 보았다.\n③ 프리드먼과 펠프스는 장기에는 실업과 인플레이션의 상충관계가 없다고 주장했다.\n⑤ 루카스는 합리적 기대의 영향을 강조했다.","c":"상","v":1},"공인노2026_35-104":{"w":"④ 실물경기변동이론은 가격이 신축적이라고 보고 기술(생산성) 충격으로 경기변동을 설명한다. 가격 경직성이 경기변동을 낳는다는 것은 새케인즈학파의 입장이다. 틀리다.\n① 화폐의 중립성이 성립한다.\n② 임금과 이자율 변화에 따라 노동을 기간 간에 대체한다.\n③ 생산성 충격이 원인이다.\n⑤ 완전경쟁시장을 전제로 한다.","c":"상","v":1},"공인노2026_35-97":{"w":"⑤ 롤즈의 사회후생함수는 W = min(U갑, U을)이므로 사회무차별곡선이 L자 형태이다.\n① 롤즈 함수는 두 사람의 한계효용이 같다는 것과 관계가 없다.\n② 효용이 가장 낮은 사람의 생활수준을 높이는 정책을 강조한다.\n③ 효용의 합은 공리주의 사회후생함수이다.\n④ 큰 값이 아니라 작은 값으로 정의된다.","c":"상","v":1},"공인노2026_35-105":{"w":"⑤가 틀리다. 유동성 제약이 있으면 현재 세금이 줄어도 소비를 늘리고 싶은 사람이 추가로 소비할 수 있으므로 감세의 효과가 소비에 나타나 리카도 대등정리가 성립하지 않는다.\n① 배로는 세대 간 이타심으로 현세대가 미래 세대의 효용까지 고려하면 성립한다고 보았다.\n② 국채는 미래의 조세이므로 성립한다.\n③ 조세 부담 주체가 달라지면 이해관계가 달라 성립하지 않을 수 있다.\n④ 근시안적 소비자는 성립하지 않는다.","c":"상","v":1},"공인노2017_26-109":{"w":"ㄱ. (A)의 소득 증가 폭은 ΔG × 1/(1 - 한계소비성향)이므로 한계소비성향에 따라 달라진다. O\nㄴ. (A)는 이자율이 고정된 케인즈 교차 모형이라 소득 증가 폭이 (B)의 Ya → Yc에 해당한다. 이자율이 오르는 (B)의 Ya → Yb는 그보다 작다. X\nㄷ. e는 이자율이 r1에서 r2로 올라 투자가 줄어든 점이라 구축효과를 반영한다. O\nㄹ. 정부지출이 늘면 처음에는 계획된 지출이 생산보다 많아 재고가 예기치 않게 줄어든다. X\nㄱ, ㄷ이므로 ②.","c":"상","v":1},"경제교재-01-01":{"w":"희소성은 무한한 욕망에 비해 경제적 자원이 상대적으로 부족한 현상이다. 절대량의 많고 적음이 기준이 아니다.","c":"상","v":1},"경제교재-01-04":{"w":"등록금은 명시적 비용이고, 포기한 임금은 암묵적 비용이다. 기회비용은 두 가지의 합이다.","c":"상","v":1},"경제교재-01-06":{"w":"잃어버린 표값 5,000원은 매몰비용이라 기회비용이 아니다. 재구입에 드는 5,000원만 비용이고 편익 20,000원이 더 크므로 다시 사는 것이 합리적이다.","c":"상","v":1},"경제교재-01-08":{"w":"X재 한 단위를 만들기 위해 포기하는 Y재가 줄어 X재의 기회비용이 감소한다. 기울기의 절댓값은 X재의 기회비용이므로 곡선이 완만해진다.","c":"상","v":1},"경제교재-01-10":{"w":"한계전환율은 X재를 한 단위 늘릴 때 줄여야 하는 Y재의 양이다. 오목한 곡선에서는 X재 생산이 늘수록 커진다.","c":"상","v":1},"경제교재-01-11":{"w":"생산가능곡선은 4X + 2Y = 100이다. Y를 1 늘리면 X는 2/4 = 1/2 줄어든다.","c":"상","v":1},"경제교재-01-13":{"w":"노동은 300 + 300 = 600시간, 자본은 300 + 900 = 1,200단위로 둘 다 전부 쓴다.","c":"상","v":1},"경제교재-01-15":{"w":"저축을 늘리는 것이 바람직하다는 가치판단이 들어 있다. 이자율이 오르면 저축이 늘어난다는 진술은 실증경제학이다.","c":"상","v":1},"경제교재-02-01":{"w":"공급곡선이 더 가파르면 가격 변동폭이 시간이 지날수록 줄어 균형으로 수렴한다. 공급곡선이 더 완만하면 발산한다.","c":"상","v":1},"경제교재-02-03":{"w":"생산 측면에서 대체관계인 재화는 한 재화 가격이 오르면 그 재화 생산이 늘고 다른 재화 공급이 줄어든다. 수요 측면과 달리 가격과 반대 방향으로 움직인다.","c":"상","v":1},"경제교재-02-05":{"w":"가격이 오르면 수요량은 줄고 공급량은 늘어 부족분이 점점 줄어든다. 초과공급량이 있으면 반대로 가격이 내린다.","c":"상","v":1},"경제교재-02-07":{"w":"소비자는 오르기 전에 사려 하고 생산자는 오른 뒤에 팔려고 생산과 판매를 미룬다.","c":"상","v":1},"경제교재-02-10":{"w":"q_A = (12 − 4)/2 = 4, q_B = 8 − 4 = 4이므로 합은 8이다.","c":"상","v":1},"경제교재-02-13":{"w":"가격 상승으로 실질소득이 줄면 열등재 수요가 늘어나는 소득효과가 생기고, 이 효과가 대체효과를 넘어서면 수요량이 늘어난다.","c":"상","v":1},"경제교재-02-15":{"w":"가격이 내려 소비가 늘 것으로 예상되면 다른 사람을 따라 사는 수요가 더해져 수요량이 더 크게 늘어난다.","c":"상","v":1},"경제교재-02-16":{"w":"처음 균형은 P = 50, Q = 50이고 새 균형은 120 − P = P에서 P = 60, Q = 60이다.","c":"상","v":1},"경제교재-03-01":{"w":"P = 15에서 Q = 30이고 탄력성은 2 × 15/30 = 1이다. 이 점은 직선 수요곡선의 중점이다.","c":"상","v":1},"경제교재-03-04":{"w":"지수의 절댓값이 탄력성이다. 탄력적이므로 가격이 오르면 수량이 더 큰 비율로 줄어 총수입 A/P가 감소한다.","c":"상","v":1},"경제교재-03-06":{"w":"|ΔQ/ΔP| = 20/4 = 5이고 평균가격 10, 평균수량 20이므로 5 × 10/20 = 2.5이다.","c":"상","v":1},"경제교재-03-08":{"w":"가격과 공급량이 비례하므로 가격이 1% 오르면 공급량도 1% 늘어난다.","c":"상","v":1},"경제교재-03-10":{"w":"기간이 길면 대체재를 찾고 소비 습관을 바꿀 여유가 생겨 가격 변화에 수요량이 더 크게 반응한다.","c":"상","v":1},"경제교재-03-13":{"w":"소득이 늘 때 수요가 줄면 열등재다. 정상재 중 수요 증가율이 소득 증가율보다 크면 사치재, 작으면 필수재다.","c":"상","v":1},"경제교재-03-15":{"w":"(−0.5 × 2%) + (−0.5 × −4%) = −1% + 2% = +1%이다. Y재와는 보완관계이고 X재는 열등재다.","c":"상","v":1},"경제교재-04-01":{"w":"수요가 완전탄력적이면 가격이 조금만 올라도 수요량이 0이 되므로 소비자에게 전가할 수 없다. 자중손실은 이때 최대가 된다.","c":"상","v":1},"경제교재-04-03":{"w":"공급이 탄력적이면 생산자는 부담을 피해 공급량을 크게 줄이므로 가격이 더 많이 오른다. 소비자 부담 : 생산자 부담 = 공급탄력성 : 수요탄력성이다.","c":"상","v":1},"경제교재-04-04":{"w":"생산자에게 부과하면 100 − P = −20 + (P − 10)에서 P = 65이고 수취가격은 55이다. 소비자에게 부과하면 100 − (P + 10) = −20 + P에서 P = 55가 수취가격이고 소비자가격은 65이다.","c":"상","v":1},"경제교재-04-06":{"w":"세후 균형은 40 − P = P − 8에서 P = 24, Q = 16이다. 거래량이 20에서 16으로 4 줄었으므로 1/2 × 8 × 4 = 16이다.","c":"상","v":1},"경제교재-04-08":{"w":"최고가격제는 균형가격이 너무 높다고 보고 그 아래에 상한을 두어야 효력이 있다. 균형가격 위의 상한은 구속력이 없다.","c":"상","v":1},"경제교재-04-09":{"w":"균형은 P = 40, Q = 20이므로 상한 30은 유효하다. 상한 30에서 공급량은 10이고 이 수량에 대한 수요가격은 60 − 10 = 50이다.","c":"상","v":1},"경제교재-04-11":{"w":"임금 상승률이 고용 감소율보다 크므로 임금 × 고용량이 늘어난다. 탄력성이 1보다 크면 반대로 줄어든다.","c":"상","v":1},"경제교재-04-15":{"w":"소비자 부담비율은 1/(3 + 1) = 1/4이므로 2, 생산자는 3/4이므로 6이다.","c":"상","v":1},"경제교재-05-01":{"w":"한계효용이론은 효용함수로 총효용을 구체적 수치로 나타내고, 무차별곡선이론은 어느 묶음이 더 좋은지의 순서만 쓴다.","c":"상","v":1},"경제교재-05-03":{"w":"한계효용이 양수인 동안은 총효용이 늘고, 0을 지나 음수가 되면 줄어든다.","c":"상","v":1},"경제교재-05-04":{"w":"MU = 0에서 X = 4이다. 총효용함수는 −1.5X² + 12X이므로 X = 4에서 −24 + 48 = 24이다.","c":"상","v":1},"경제교재-05-06":{"w":"총효용은 √4 × √9 = 6이다. MUx = 0.5 × X의 −0.5제곱 × Y의 0.5제곱 = 0.5 × 3/2 = 0.75이다.","c":"상","v":1},"경제교재-05-07":{"w":"MUx/Px = MUy/Py에서 20/4 = 5이므로 MUy = 5 × 2 = 10이다.","c":"상","v":1},"경제교재-05-09":{"w":"화폐도 일반 재화처럼 소득이 늘수록 추가 한 단위의 만족이 작아지는 것이 보통이다.","c":"상","v":1},"경제교재-05-11":{"w":"가격은 총효용이 아닌 실제 소비량의 한계효용에 따라 정해지므로 부존량이 많은 물의 가격이 낮다.","c":"상","v":1},"경제교재-05-13":{"w":"(1, 9)와 (9, 1)이 무차별일 때 (5, 5)를 더 선호한다는 식이며 무차별곡선이 원점에 대해 볼록한 근거다.","c":"상","v":1},"경제교재-05-15":{"w":"소비가 늘수록 MUx가 줄어 MUx/Px가 다시 MUy/Py와 같아질 때까지 수요량이 늘어난다.","c":"상","v":1},"경제교재-06-01":{"w":"교차점 위의 한 묶음이 두 곡선에 모두 속하면 한 곡선 위의 두 점이 같은 효용이 되는데, 한 점이 다른 점보다 두 재화를 모두 더 많이 갖고 있으므로 모순이다.","c":"상","v":1},"경제교재-06-03":{"w":"X재 지수가 1보다 큰 콥-더글라스 함수는 X재의 한계효용이 체증하는데도 MRS가 Y/X에 비례해 체감하므로 무차별곡선이 원점에 대해 볼록하다. 두 법칙은 논리적 포함 관계가 아니다.","c":"상","v":1},"경제교재-06-04":{"w":"콥-더글라스에서 소득의 1/2를 X재에 쓰므로 120/6 = 20이다. Y재는 120/4 = 30이다.","c":"상","v":1},"경제교재-06-06":{"w":"Y = 3X로 소비하므로 2X + 3X = 70에서 X = 14, Y = 42이다.","c":"상","v":1},"경제교재-06-08":{"w":"지출 비중은 X재 1/4, Y재 3/4이므로 X = 20/2 = 10, Y = 60/3 = 20이다.","c":"상","v":1},"경제교재-06-10":{"w":"열등재의 소득효과는 가격 하락 시 수요량을 줄이는 방향이다. 기펜재는 이 크기가 대체효과보다 큰 경우다.","c":"상","v":1},"경제교재-06-12":{"w":"대체효과에 의한 수요량 증가분이 가격효과 전체의 증가분보다 작기 때문이다. 열등재는 반대로 보상수요곡선이 더 완만하다.","c":"상","v":1},"경제교재-06-14":{"w":"보상변화는 새 가격에서 원래 효용으로 돌리려고 소득을 덜어내므로 음수이고, 동등변화는 가격을 내리지 않는 대신 줄 소득이라 양수이다. 둘은 항상 부호가 반대다.","c":"상","v":1},"경제교재-06-15":{"w":"MRS = 1/√X = Px/Py = 1에서 X = 1이다. 준선형 효용함수에서는 MRS가 X만의 함수라 소득효과가 없고 늘어난 소득은 Y재에 쓴다.","c":"상","v":1},"경제교재-07-01":{"w":"선호체계는 직접 관찰할 수 없으므로 시장에서 관찰되는 가격·소득·수량으로 소비자이론을 세운다.","c":"상","v":1},"경제교재-07-04":{"w":"약공리는 Q0를 살 수 있는데 Q1을 고른 경우만 문제 삼는다. Q0를 살 수 없으면 Q1이 Q0보다 직접현시선호될 수 없다.","c":"상","v":1},"경제교재-07-06":{"w":"강공리는 간접현시선호까지 포함하는 더 엄격한 조건이어서 약공리를 함축한다. 거꾸로 약공리가 성립한다고 강공리가 성립하지는 않는다.","c":"상","v":1},"경제교재-07-07":{"w":"새 가격에서 (6, 12)의 비용은 6 + 36 = 42로 소득 30을 넘어 구입할 수 없다. 처음 묶음을 살 수 없으면 새 선택은 약공리에 걸리지 않는다.","c":"상","v":1},"경제교재-07-08":{"w":"처음 가격에서 (4, 16)의 비용은 24로 (6, 12)의 비용 24와 같아 살 수 있었다. 새 가격에서 (4, 16)의 비용은 36이고 (6, 12)의 비용은 30이라 (6, 12)도 살 수 있다. 두 부등식이 모두 성립한다.","c":"상","v":1},"경제교재-07-10":{"w":"처음 가격에서 (10, 5)의 비용은 100, (7, 6)은 95라 (7, 6)을 살 수 있었는데 (10, 5)를 골랐다. 새 가격에서 (10, 5)의 비용은 150으로 (7, 6)의 130보다 커서 살 수 없다.","c":"상","v":1},"경제교재-07-13":{"w":"처음 가격에서 (65, 15)의 비용은 1,250으로 1,400 이하라 살 수 있었는데 (60, 20)을 골랐다. 새 가격에서 (60, 20)의 비용은 1,800이고 (65, 15)의 비용은 1,750이라 (60, 20)을 살 수 없다.","c":"상","v":1},"경제교재-07-15":{"w":"힉스 보상은 같은 효용을 유지하도록 소득을 조정한다. 가격 변화가 아주 작으면 두 보상은 같은 효과를 낸다.","c":"상","v":1},"경제교재-08-01":{"w":"현금보조는 소득 증가와 같은 효과를 내서 소득효과만 생긴다.","c":"상","v":1},"경제교재-08-03":{"w":"가격보조 후 가격이 (3, 2)가 되어 x = y = 90/5 = 18이고 보조액은 18 × 1 = 18이다. 현금 18을 주면 (90 + 18)/6 = 18로 같다. 완전보완재는 대체효과가 0이라 가격보조도 소득효과만 일으킨다.","c":"상","v":1},"경제교재-08-06":{"w":"소비세 때는 X재 가격이 2가 되어 X = 25, Y = 50이고 효용은 √1250 ≈ 35.36이다. 소득세 25이면 소득 75로 X = Y = 37.5이고 효용은 37.5다.","c":"상","v":1},"경제교재-08-08":{"w":"파셰 수량지수는 P1Q1/P1Q0 = (6 + 6)/(8 + 3) = 12/11 > 1이다. 2기 가격에서 1기 묶음을 살 수 있었는데 2기 묶음을 골랐으므로 명백한 개선이다.","c":"상","v":1},"경제교재-08-11":{"w":"대체효과는 미래소비를, 소득효과도(미래소비가 정상재이므로) 미래소비를 늘린다. 현재소비와 저축은 두 효과의 크기에 따라 달라진다.","c":"상","v":1},"경제교재-08-13":{"w":"제약이 없으면 C1 = C2 = 500이라 한도 100에 걸린다. C1 = 100, C2 = 900이고 효용은 10 + 30 = 40이며 이는 제약이 없을 때의 2√500 ≈ 44.7보다 낮다.","c":"상","v":1},"경제교재-08-15":{"w":"대체효과는 정상재든 열등재든 노동을 늘린다. 열등재 여가는 실질소득이 늘면 줄어들어 소득효과도 노동을 늘리므로 후방굴절 곡선이 나오지 않는다.","c":"상","v":1},"경제교재-08-16":{"w":"완전소득은 6 × 24 + A이고 여가에 3분의 2를 쓴다. A = 0이면 R = 16으로 노동 8시간, A = 36이면 6R = 120이라 R = 20으로 노동 4시간이다.","c":"상","v":1},"경제교재-09-05":{"w":"기대효용은 (10 + 6)/2 = 8이라 확실성등가는 8² = 64다. 기대소득은 68이므로 위험프리미엄은 68 − 64 = 4다.","c":"상","v":1},"경제교재-09-07":{"w":"공정한 보험료는 사고확률 × 보험금이고 프리미엄률은 보험료/보험금이므로 사고확률과 같다. 이때 보험회사의 기대이윤은 0이다.","c":"상","v":1},"경제교재-09-09":{"w":"사고 시 재산은 25라 기대효용은 (5 + 9)/2 = 7이고 확실성등가는 49다. 최대보험료는 81 − 49 = 32이며 공정한 보험료 28에 위험프리미엄 4를 더한 값과 같다.","c":"상","v":1},"경제교재-09-10":{"w":"공정한 보험료보다 비싼 보험은 가입자에게 금전적으로는 불리하다. 그래도 보험료를 낸 뒤의 확실한 소득이 확실성등가보다 크면 위험이 없어진 효용이 더 커서 이득이고, 보험회사는 기대이윤이 양수가 된다.","c":"상","v":1},"경제교재-09-12":{"w":"위험자산에 a를 두면 자산은 100 + a 또는 100 − 0.5a다. 1계조건 1/(100 + a) = 0.5/(100 − 0.5a)에서 100 − 0.5a = 50 + 0.5a이므로 a = 50이다.","c":"상","v":1},"경제교재-09-14":{"w":"처음 기대효용은 0.5 × √64 + 0.5 × 10 = 9다. 적발확률 1/4에서 0.25 × √(100 − F) + 0.75 × 10 = 9이면 √(100 − F) = 6이므로 F = 64다.","c":"상","v":1},"경제교재-09-15":{"w":"기대 소요시간은 1/S + 9S이고 미분하면 −1/S² + 9 = 0에서 S = 1/3이다. 이때 기대시간은 3 + 3 = 6이다.","c":"상","v":1},"경제교재-09-16":{"w":"선형 효용함수의 투자자는 확실성등가와 기대소득이 같고 위험프리미엄이 0이다. 위험기피자만 확실성등가가 기대소득보다 작다.","c":"상","v":1},"경제교재-10-02":{"w":"AP = 90L − L², MP = 180L − 3L²이다. MP = AP이면 90L = 2L²이므로 L = 45이고 AP를 L로 미분해도 90 − 2L = 0에서 L = 45다.","c":"상","v":1},"경제교재-10-04":{"w":"총생산은 4 × 12 = 48에서 5 × 11 = 55로 늘었으므로 한계생산은 55 − 48 = 7이다. 한계생산이 평균생산보다 작아 평균생산이 줄었다.","c":"상","v":1},"경제교재-10-06":{"w":"요소를 t배 하면 산출이 t²배라 체증이다. MPL = K는 L과 무관한 상수라 노동을 늘려도 줄지 않는다.","c":"상","v":1},"경제교재-10-08":{"w":"등량곡선 위에서 노동 증가에 따른 산출 증가(MPL × ΔL)와 자본 감소에 따른 산출 감소(MPK × ΔK)의 절댓값이 같으므로 MRTS = |ΔK/ΔL| = MPL/MPK다.","c":"상","v":1},"경제교재-10-09":{"w":"요소를 t배(t > 1) 하면 산출은 3√t L^(1/2) + 3tK로 t × q보다 작다. 첫 항이 t배가 아니라 √t배만 늘기 때문이다.","c":"상","v":1},"경제교재-10-11":{"w":"MRTS = K/L = w/r = 4에서 K = 4L이고 Q = 2L = 20이라 L = 10, K = 40이다. 비용은 4 × 10 + 40 = 80이다.","c":"상","v":1},"경제교재-10-13":{"w":"확장경로는 원점을 지나야 하므로 두 요소가 동시에 열등투입요소일 수 없다. 소비자이론에서 두 재화가 모두 열등재일 수 없는 것과 같다.","c":"상","v":1},"경제교재-10-15":{"w":"MRTS = (0.3K)/(0.7L) = w/r = 0.5에서 K/L = 0.5 × 0.7/0.3 = 7/6이다. 동차생산함수라 확장경로는 원점을 지나는 직선이다.","c":"상","v":1},"경제교재-11-02":{"w":"명시적 비용은 500 + 300 + 5 = 805이고 암묵적 비용은 귀속이자 5와 귀속임금 500을 더한 505다. 경제적 비용은 805 + 505 = 1,310이다.","c":"상","v":1},"경제교재-11-04":{"w":"평균고정비용은 40 − 25 = 15이므로 총고정비용은 15 × 50 = 750이다.","c":"상","v":1},"경제교재-11-07":{"w":"MC = 2Q = 8이고 MC = w/MPL이므로 MPL = 12/8 = 1.5다. AVC = Q = 4이고 AVC = w/APL이므로 APL = 12/4 = 3이다.","c":"상","v":1},"경제교재-11-08":{"w":"k에 대해 최소화하면 −4q + 4k = 0에서 k = q이다. 대입하면 4q² − 4q² + 2q² + 20 = 2q² + 20이다.","c":"상","v":1},"경제교재-11-10":{"w":"LAC = 60 − 12Q + Q²를 미분해 −12 + 2Q = 0이면 Q = 6이고 LAC = 60 − 72 + 36 = 24다. 이때 LMC = 60 − 24Q + 3Q² = 24로 LAC와 같다.","c":"상","v":1},"경제교재-11-12":{"w":"한계비용이 같아야 하므로 MC1 = 4y1 = MC2 = 12y2에서 y1 = 3y2다. y1 + y2 = 40이므로 y1 = 30, y2 = 10이다.","c":"상","v":1},"경제교재-11-13":{"w":"MRTS = K/L = w/r = 1/4에서 L = 4K이고 Q = 2K이므로 K = Q/2, L = 2Q다. 비용은 2 × 2Q + 8 × Q/2 = 8Q라 한계비용은 8이다.","c":"상","v":1},"경제교재-11-15":{"w":"MR = 100 − 2Q다. 이윤극대화는 MR = MC에서 Q = 40이고 수입극대화는 MR = 0에서 Q = 50이다. 한계비용이 양수이면 수입극대화 생산량이 더 많다.","c":"상","v":1},"경제교재-12-01":{"w":"기업 수가 많아도 상품이 차별화돼 있으면 단골이 생겨 수요곡선이 우하향한다(독점적 경쟁). 동질적이면 시장가격보다 높게 팔 수 없다.","c":"상","v":1},"경제교재-12-03":{"w":"MC = 10 + 4q = 50이므로 q = 10이다. 총수입 500, 총비용 50 + 100 + 200 = 350이므로 이윤은 150이다.","c":"상","v":1},"경제교재-12-04":{"w":"MC = 2Q + 2 = 12이므로 Q = 5다. 총수입 60에서 총가변비용 25 + 10 = 35를 빼면 생산자잉여는 25다. 총비용은 55라 이윤은 5이며 생산자잉여는 이윤에 총고정비용 20을 더한 값이다.","c":"상","v":1},"경제교재-12-05":{"w":"AC = 2Q + 4 + 18/Q를 미분해 2 − 18/Q² = 0이면 Q = 3이고 최저 AC = 6 + 4 + 6 = 16이다. AVC는 Q = 0에서 최저 4다.","c":"상","v":1},"경제교재-12-07":{"w":"정액세는 총고정비용을 늘려 평균비용만 올린다. 평균가변비용과 한계비용이 그대로라 생산중단점과 P = MC 생산량도 그대로다.","c":"상","v":1},"경제교재-12-09":{"w":"개별기업은 MC = 4q = P에서 q = P/4를 공급하고 기업이 200개이므로 Q = 200 × P/4 = 50P다. 생산요소 가격이 일정하다는 전제다.","c":"상","v":1},"경제교재-12-12":{"w":"LAC의 최저점은 2q − 12 = 0에서 q = 6이고 LAC = 36 − 72 + 50 = 14가 장기균형가격이다. 시장거래량은 500 − 140 = 360이므로 기업 수는 360/6 = 60개다.","c":"상","v":1},"경제교재-13-03":{"w":"MR = 90 − 2Q = 30에서 Q = 30이다. 가격은 수요곡선에서 90 − 30 = 60이다.","c":"상","v":1},"경제교재-13-04":{"w":"MR = 80 − 2Q = 20에서 Q = 30, P = 50이다. 러너지수는 (50 − 20)/50 = 0.6이다.","c":"상","v":1},"경제교재-13-07":{"w":"MR1 = 60 − 2Q1 = 10에서 Q1 = 25, P1 = 35이다. MR2 = 40 − 2Q2 = 10에서 Q2 = 15, P2 = 25이다. 시장 2의 탄력성(25/15 ≈ 1.67)이 시장 1(35/25 = 1.4)보다 커서 가격이 낮다.","c":"상","v":1},"경제교재-13-08":{"w":"수요곡선이 곧 한계수입곡선이라 P = MC에서 생산한다. 소비자가 지불할 용의가 있는 금액을 모두 받으므로 소비자잉여는 0이 된다.","c":"상","v":1},"경제교재-13-10":{"w":"사용료를 한계비용 4에 맞추면 Q = 16이다. 소비자잉여는 ½ × 16 × 16 = 128이므로 이를 가입비로 받는다.","c":"상","v":1},"경제교재-13-12":{"w":"따로 팔면 카메라 125(소비자 1만) + 스마트폰 90 × 2 = 305다. 묶으면 소비자 1은 215, 소비자 2는 160까지 내므로 160 × 2 = 320이다.","c":"상","v":1},"경제교재-13-13":{"w":"한계비용이 같아야 하므로 10 + 2Q1 = 40 + Q2이고 Q1 + Q2 = 90이다. 대입하면 3Q1 = 120이라 Q1 = 40, Q2 = 50이며 이때 한계비용은 모두 90이다.","c":"상","v":1},"경제교재-13-15":{"w":"두 세금은 MR = MC 조건을 바꾸지 않는다. 가격이 그대로라 소비자에게 전가되지 않고 독점이윤만 줄어든다.","c":"상","v":1},"경제교재-14-01":{"w":"상품이 차별화되어 있어 가격을 올려도 고객이 전부 떠나지 않는다. 그래서 수요곡선이 우하향하고 기업이 가격을 정한다.","c":"상","v":1},"경제교재-14-04":{"w":"장기균형에서 P = LAC이지만 수요곡선이 우하향하므로 P는 MR = MC보다 높다. 그래서 사회적으로 최적인 생산량보다 적게 생산한다.","c":"상","v":1},"경제교재-14-06":{"w":"접점이 LAC의 우하향 구간에 있어 균형 생산량이 최저점의 생산량보다 적다. 그 차이가 초과설비다.","c":"상","v":1},"경제교재-14-08":{"w":"탄력성이 커질수록 수요곡선이 수평선에 가까워져 접점이 LAC 최저점 쪽으로 이동한다. 탄력성이 무한대면 완전경쟁과 같다.","c":"상","v":1},"경제교재-14-10":{"w":"MR = MC는 이윤극대화 조건이고 P = LAC는 진입으로 초과이윤이 사라진 조건이다. 두 조건이 한 점에서 만난다.","c":"상","v":1},"경제교재-14-12":{"w":"MR = MC에서 Q = a/4, P = 3a/4이고 P = AC에서 a² = 144, a = 12이다. 그러면 n = 60/12 = 5, Q = 3, P = 9, AC = 3 + 18/3 = 9로 일치한다.","c":"상","v":1},"경제교재-14-13":{"w":"완전경쟁시장은 동질적 상품을 팔아 비가격경쟁의 의미가 없고, 상품 차별화가 있는 시장에서 비가격경쟁이 나타난다.","c":"상","v":1},"경제교재-15-01":{"w":"추측된 생산량 변화를 0으로 보는 것이 꾸르노 가정이다. 두 반응곡선이 만나는 점이 내쉬균형이다.","c":"상","v":1},"경제교재-15-03":{"w":"반응함수는 q1 = (60 − q2)/2이고 대칭이므로 q = 20, P = 20이다. 이윤은 20 × 20 = 400이다.","c":"상","v":1},"경제교재-15-05":{"w":"추종자 이윤은 15 × 15 = 225로 꾸르노의 400보다 작다. 선도자가 먼저 많이 생산해 가격이 내려가기 때문이다.","c":"상","v":1},"경제교재-15-07":{"w":"상대보다 조금만 낮추어도 모든 소비자를 얻으므로 가격은 한계비용까지 내려간다. 완전경쟁과 같은 산출이 나온다.","c":"상","v":1},"경제교재-15-08":{"w":"상대 가격이 오르면 자기 제품의 수요가 늘어 자기 최적 가격도 오른다. 이때 가격이 한계비용보다 높아 양의 이윤이 가능하다.","c":"상","v":1},"경제교재-15-11":{"w":"인상 때는 고객을 경쟁기업에 빼앗겨 수요량이 크게 줄고, 인하 때는 경쟁기업도 내려 수요량이 조금 늘어난다.","c":"상","v":1},"경제교재-15-13":{"w":"군소기업이 팔고 싶은 만큼 팔게 두고 남는 수요를 차지한다. 잔여수요에서 MR = MC로 가격을 정한다.","c":"상","v":1},"경제교재-15-15":{"w":"총산출은 n(a − c)/((n + 1)b) = 3 × 60/4 = 45이므로 P = 60 − 45 = 15이다.","c":"상","v":1},"경제교재-16-02":{"w":"우월전략은 상대의 모든 전략에 대한 최선이므로 상대 전략이 주어진 경우에도 최선이다.","c":"상","v":1},"경제교재-16-04":{"w":"경기자 1은 L일 때 U, R일 때 D가 낫고 경기자 2는 U일 때 L, D일 때 R이 나아 우월전략이 없다. (U,L)과 (D,R)에서 둘 다 이탈 이득이 없어 내쉬균형이다.","c":"상","v":1},"경제교재-16-06":{"w":"(U,L)에서는 경기자 1이 D로 바꾸면 3 > 2이고, (D,L)·(D,R)·(U,R)은 경기자 2 또는 1이 이탈해 이득을 본다. 어느 칸도 균형이 아니다.","c":"상","v":1},"경제교재-16-07":{"w":"경기자 2를 무차별하게 만들려면 2p = 3(1 − p)이어야 하므로 p = 3/5이다. 경기자 2의 A 확률은 3q = 2(1 − q)에서 2/5다.","c":"상","v":1},"경제교재-16-09":{"w":"한쪽이 이기는 영합게임이라 어느 순수전략 조합에서도 진 쪽이 바꾸려 한다. 상대를 무차별하게 만드는 확률은 1/2이다.","c":"상","v":1},"경제교재-16-10":{"w":"진입이 일어난 뒤에는 협조가 더 큰 보수이므로 경쟁은 공허한 위협이다. 역진귀납에서 이 위협은 제외된다.","c":"상","v":1},"경제교재-16-12":{"w":"마지막 판은 보복 기회가 없어 비협조이고 그 앞 판도 같은 논리가 적용된다. 역진귀납으로 모든 판이 비협조가 된다.","c":"상","v":1},"경제교재-16-13":{"w":"상대가 배신하면 다음 판부터 보복할 수 있어 배신의 이득이 줄어든다. 종료 시점을 모르는 경우도 같다.","c":"상","v":1},"경제교재-17-01":{"w":"생산물 수요가 늘면 같은 생산량을 늘리려는 기업의 요소 수요도 늘어난다. 그래서 요소시장은 생산물시장과 묶어 분석한다.","c":"상","v":1},"경제교재-17-03":{"w":"MPL = 60 − 4L이므로 VMP = 10(60 − 4L) = w이다. w = 200이면 L = 10이고 w = 400이면 L = 5이다.","c":"상","v":1},"경제교재-17-05":{"w":"총요소비용이 w(L) × L이므로 w = a + bL일 때 MFC = a + 2bL이다. 독점기업의 한계수입과 같은 구조다.","c":"상","v":1},"경제교재-17-07":{"w":"수요독점은 MFC = 20 + 2L이므로 200 − 2L = 20 + 2L에서 L = 45, w = 65이다. 경쟁은 200 − 2L = 20 + L에서 L = 60, w = 80이므로 15 낮다.","c":"상","v":1},"경제교재-17-08":{"w":"수요독점 임금 65와 경쟁 임금 80 사이이므로 70에서 공급량은 50이고 MRP는 L = 50에서 100으로 70보다 높아 50명을 모두 고용한다.","c":"상","v":1},"경제교재-17-11":{"w":"임금이 오르면 비용이 올라 생산물 가격이 오르는데, 생산물 수요가 비탄력적이면 판매량이 덜 줄어 노동수요량도 덜 줄어든다.","c":"상","v":1},"경제교재-17-13":{"w":"열등재이면 소득효과도 여가를 줄이는 방향이라 대체효과와 같은 방향으로 노동을 늘린다. 후방굴절은 여가가 정상재일 때만 나온다.","c":"상","v":1},"경제교재-17-14":{"w":"균형은 w = 60, L = 40이고 총임금은 2,400이다. 최저임금 70에서는 L = 30이고 총임금은 2,100이다. 균형에서 수요의 탄력성이 60/40 = 1.5로 1보다 크기 때문이다.","c":"상","v":1},"경제교재-17-16":{"w":"조합의 한계수입이 0일 때 총임금이 최대이고, 직선 수요에서 MR = 0은 탄력성이 1인 점이다.","c":"상","v":1},"경제교재-18-01":{"w":"이윤극대화 기업은 VMP가 요소 가격과 같아질 때까지 고용한다. 기능별 소득분배이론의 기초다.","c":"상","v":1},"경제교재-18-03":{"w":"실질이자율은 명목이자율에서 인플레이션율을 뺀 값이다.","c":"상","v":1},"경제교재-18-05":{"w":"공급곡선이 수직이라 수요곡선이 이동해도 거래량은 불변이고 가격인 지대만 변한다.","c":"상","v":1},"경제교재-18-07":{"w":"그 요소를 현재 용도에 붙잡아 두는 데 필요한 최소 금액, 즉 전용수입이 0이기 때문이다.","c":"상","v":1},"경제교재-18-09":{"w":"준지대 = 총수입 − 총가변비용 = 1,000 − 600 = 400이다. 총고정비용과 초과이윤의 합과 같다.","c":"상","v":1},"경제교재-18-11":{"w":"로렌츠곡선은 한 곡선이 다른 곡선 안쪽에 있어야 비교된다. 지니계수는 하나의 수치라 교차해도 비교된다.","c":"상","v":1},"경제교재-18-13":{"w":"로렌츠곡선 아래 면적은 밑변 0.5, 높이 1인 삼각형 0.25이고 지니계수는 1 − 2 × 0.25 = 0.5이다.","c":"상","v":1},"경제교재-19-01":{"w":"다른 시장의 반응을 무시하므로 연관이 작을 때 오류가 작다. 연관이 큰 시장들은 일반균형분석으로 본다.","c":"상","v":1},"경제교재-19-04":{"w":"Py = 1, Px = p로 두면 A의 수요는 (3/p, 3), B의 수요는 (6 + 3/p, 6p + 3)이다. X시장 청산 3/p + 6 + 3/p = 12에서 p = 1이고 A는 (3, 3), B는 (9, 9)를 소비한다.","c":"상","v":1},"경제교재-19-06":{"w":"MRS = y/x가 같아야 하므로 x1/y1 = x2/y2이다. 총량이 같으면 모든 점에서 x와 y의 비율이 같은 대각선이 된다.","c":"상","v":1},"경제교재-19-08":{"w":"선형 효용의 MRS는 일정해 서로 다르면 한계대체율이 같아지는 내부점이 없다. 그래서 효율 배분은 한 소비자가 한 재화만 갖는 변 위에 있다.","c":"상","v":1},"경제교재-19-09":{"w":"생산가능곡선의 기울기가 2이므로 한계변환율은 2이다. 이는 MCx/MCy와 같다.","c":"상","v":1},"경제교재-19-11":{"w":"왈라스는 존재를 가정만 했고 증명은 1950년대 애로우와 드브뢰가 했다.","c":"상","v":1},"경제교재-20-02":{"w":"그 사람의 효용을 줄이지 않고 다른 사람의 효용을 늘릴 수 없으면 파레토 효율이다. 효율은 분배와 무관하다.","c":"상","v":1},"경제교재-20-03":{"w":"한계대체율이 다르면 서로 재화를 맞바꿔 둘 다 이득을 보므로 파레토 개선이 가능하다. 같을 때 더 이상의 개선이 없다.","c":"상","v":1},"경제교재-20-05":{"w":"X를 늘릴수록 포기해야 하는 Y가 커져 한계변환율이 커진다. 한계비용 체증, 즉 한계생산 체감에서 비롯된다.","c":"상","v":1},"경제교재-20-06":{"w":"MRS_A = MRS_B = MRT이면 소비의 효율, 생산의 효율, 생산물구성의 효율이 모두 만족된다.","c":"상","v":1},"경제교재-20-08":{"w":"소비자의 MRS와 생산자의 MRTS, MC 가격이 모두 같은 가격비에 맞춰져 효율 조건이 충족된다.","c":"상","v":1},"경제교재-20-10":{"w":"공리주의는 효용의 합이 같으면 같은 후생이고, 롤즈는 가장 낮은 효용만 보므로 L자로 꺾인다.","c":"상","v":1},"경제교재-20-12":{"w":"4√x_A + 2√x_B를 x_A + x_B = 100에서 극대화하면 한계효용이 같아야 해서 x_B = x_A/4이다. 따라서 (80, 20)이다.","c":"상","v":1},"경제교재-20-13":{"w":"생산가능곡선 위의 각 생산점마다 효용가능곡선이 하나씩 생기고, 이들의 바깥쪽 포락선이 효용가능경계다. 이 경계 위에서 MRS = MRT가 성립한다.","c":"상","v":1},"경제교재-20-15":{"w":"개인 선호를 합쳐 합리적이고 민주적인 사회 선호를 만드는 방법이 없다는 뜻이다. 조건 하나를 포기하면 존재할 수 있다.","c":"상","v":1},"경제교재-21-02":{"w":"외부 한계비용이 생산자의 비용에 반영되지 않아 사회가 부담할 비용보다 적게 느낀다. 그래서 과다생산이 된다.","c":"상","v":1},"경제교재-21-04":{"w":"사회적 한계비용은 Q + 20이므로 80 − Q = Q + 20에서 Q = 30이다. 시장 산출 40보다 10 적다.","c":"상","v":1},"경제교재-21-06":{"w":"독점은 80 − 2Q = 2Q에서 Q = 20이다. 사회적 최적은 80 − Q = 2Q + 20에서 Q = 20이다. 독점의 과소생산과 외부비용의 과다생산이 상쇄된다.","c":"상","v":1},"경제교재-21-08":{"w":"최적 산출은 12 − Q = Q에서 Q = 6이다. A의 총편익은 54이고 B에게 줄 최소 보상은 B의 피해 18이므로 순편익은 36이다.","c":"상","v":1},"경제교재-21-10":{"w":"거래 후 한계저감비용이 같아지려면 80 − Q_A = 100 − (100 − Q_A)이어서 Q_A = 40이다. 가격은 40이고 A는 배출을 10 줄여 그만큼 판다.","c":"상","v":1},"경제교재-21-12":{"w":"모두가 같은 양을 소비하고 각자의 지불의사 합이 사회적 한계편익이므로 같은 수량에서 가격을 더한다.","c":"상","v":1},"경제교재-21-13":{"w":"수직합 60 − 3Q = 24에서 Q = 12이다. 이때 각자의 부담은 16과 8이다.","c":"상","v":1},"경제교재-21-14":{"w":"효율적 수준은 한계수입 12/√n = 3에서 n = 16이다. 공유지에서는 평균수입 24/√n = 3에서 n = 64이다.","c":"상","v":1},"경제교재-21-16":{"w":"먼 미래의 편익일수록 할인에 크게 줄어들므로 할인율이 내리면 편익의 현재가치가 비용보다 더 많이 늘어난다.","c":"상","v":1},"경제교재-22-01":{"w":"한 명이라도 반대하면 통과하지 않아 모두에게 이득이거나 손해가 없는 결과만 남는다. 동의를 모으는 시간과 노력이 가장 많이 든다.","c":"상","v":1},"경제교재-22-03":{"w":"찬성 51명의 이득이 작고 반대 49명의 손해가 크더라도 표 수만 세므로 통과한다.","c":"상","v":1},"경제교재-22-06":{"w":"A가 B보다, B가 C보다, C가 A보다 선호되는 순환 결과가 나와 이행성이 성립하지 않는다.","c":"상","v":1},"경제교재-22-08":{"w":"최선의 안이 채택될 가능성이 낮다고 보면 최악의 안을 막으려고 점수를 몰아 줄 수 있어 진정한 선호와 다른 결과가 나온다.","c":"상","v":1},"경제교재-22-09":{"w":"단봉선호이면 안건을 일렬로 놓았을 때 중위투표자의 최선안이 다른 어떤 안과 비교해도 과반의 지지를 얻는다.","c":"상","v":1},"경제교재-22-10":{"w":"중위투표자는 세 번째 사람이고 그의 최선량이 채택된다. 평균 42가 아니라 중앙값 30이다.","c":"상","v":1},"경제교재-22-12":{"w":"뷰캐넌과 털록의 접근이다. 우상향하는 의사결정비용곡선과 우하향하는 외부비용곡선을 수직으로 합해 최저점을 찾는다.","c":"상","v":1},"경제교재-22-14":{"w":"정부는 경쟁이 없어 효율을 높일 유인이 약하다. 경쟁과 성과급 같은 유인구조가 이 약점을 줄인다.","c":"상","v":1},"경제교재-23-02":{"w":"품질을 모르는 구매자는 평균 (900 + 300)/2 = 600까지만 낼 수 있어 700을 원하는 좋은 차 판매자는 팔지 않는다. 나쁜 차만 거래된다.","c":"상","v":1},"경제교재-23-04":{"w":"평균 보험료는 위험이 낮은 사람에게 비싸다. 그들이 떠나면 평균 위험이 커져 보험료가 다시 오른다.","c":"상","v":1},"경제교재-23-06":{"w":"정보가 없는 보험회사가 사고확률이 높은 집단을 가려내 다른 조건을 적용하는 것이다.","c":"상","v":1},"경제교재-23-07":{"w":"높은 유형은 900 − 200E > 0에서 E < 4.5이고 낮은 유형은 900 − 450E < 0에서 E > 2이다.","c":"상","v":1},"경제교재-23-09":{"w":"가입자가 손실의 일부를 직접 부담하면 사고 예방 노력을 계속할 이유가 남는다.","c":"상","v":1},"경제교재-23-11":{"w":"해고되면 같은 임금의 직장을 찾기 어려우므로 열심히 일하게 되고, 높은 임금은 저생산성 근로자만 모이는 역선택도 줄인다.","c":"상","v":1},"경제교재-23-12":{"w":"이자율을 올리면 신용도 높은 대출자가 빠지고 위험한 대출자만 남아 평균 파산위험이 커진다. 이 현상이 신용할당이다.","c":"상","v":1},"경제교재-23-14":{"w":"한계편익이 한계비용보다 크면 더 얻고 작으면 줄이므로 같아지는 점이 최적 정보 수준이다.","c":"상","v":1},"경제교재-24-01":{"w":"재고 증가는 투자지출이므로 생산했지만 팔리지 않은 부분도 지출 측면에서 같은 해 GDP에 들어간다. 그래서 생산 GDP와 지출 GDP가 사후적으로 일치한다.","c":"상","v":1},"경제교재-24-03":{"w":"기존주택 거래는 소유권 이전이라 제외되고, 중개수수료는 그해 제공된 서비스의 대가라 포함된다.","c":"상","v":1},"경제교재-24-05":{"w":"강의료 500만 원은 국내 생산이라 GDP에만 들어가고 외국인 소득이라 GNP에는 안 들어간다. 집세 200만 원은 한국인 소득이어서 GDP와 GNP에 모두 들어가므로 GDP는 500 + 200 = 700, GNP는 200이다.","c":"상","v":1},"경제교재-24-06":{"w":"10×1,000 + 10×200 + 10×100 + 10×100 = 10,000 + 2,000 + 1,000 + 1,000 = 14,000이다. 막걸리 제조에 쓰인 밀 5가마는 중간재라 제외된다.","c":"상","v":1},"경제교재-24-07":{"w":"GNP = GDP + 대외수취요소소득 − 대외지급요소소득이므로 대외순수취요소소득이 음(−)이면 GNP가 GDP보다 작다.","c":"상","v":1},"경제교재-24-08":{"w":"실질GDP는 기준연도 가격으로 생산량을 평가하므로 교역조건 변화가 반영되지 않는다. 실질GDI는 교역조건 변화에 따른 실질무역이익이 더해져 커진다.","c":"상","v":1},"경제교재-24-10":{"w":"올해 실질GDP = 2,310 ÷ 1.05 = 2,200이므로 성장률은 (2,200 − 2,000)/2,000 = 10%다.","c":"상","v":1},"경제교재-24-15":{"w":"금융자산은 보유자에게는 자산이어도 발행자에게는 부채라서 나라 전체로는 순부가 아니다. 국부는 실물자산과 순해외자산으로 구성된다.","c":"상","v":1},"경제교재-25-02":{"w":"노동수요·공급이 실질임금의 함수이므로 균형 실질임금은 10으로 그대로다. 명목임금 = 실질임금 × 물가이므로 물가가 두 배가 되면 명목임금도 두 배인 2,000이 된다.","c":"상","v":1},"경제교재-25-04":{"w":"총공급곡선이 완전고용산출량에서 수직이므로 총수요곡선이 오른쪽으로 움직이면 균형물가만 상승한다.","c":"상","v":1},"경제교재-25-06":{"w":"I = Y − C − G이다. G = 40이면 C = 30 + 0.8×460 = 398, I = 62이므로 r = 3.8이다. G = 50이면 I = 52이므로 r = 4.8이다. 정부지출 증가분 10만큼 투자가 줄고 r은 1 오른다.","c":"상","v":1},"경제교재-25-08":{"w":"총생산함수가 위로 이동해 같은 노동량으로 더 많이 생산하므로 완전고용산출량이 커진다. 총공급곡선은 수직인 채로 오른쪽으로 옮겨간다.","c":"상","v":1},"경제교재-25-09":{"w":"투자곡선이 오른쪽으로 움직여 이자율이 오르고, 저축곡선이 우상향이므로 균형 저축과 투자도 함께 늘어난다. 늘어난 투자는 소비 감소로 조달된다.","c":"상","v":1},"경제교재-25-10":{"w":"소득이 완전고용수준에 고정되므로 소비 증가는 저축을 줄여 이자율을 올리고, 그만큼 투자를 줄인다.","c":"상","v":1},"경제교재-25-11":{"w":"저축이 투자재원이고, 저축이 늘면 이자율이 내려 투자가 늘어난다. 자본축적이 장기 성장의 원천이므로 저축은 미덕이다.","c":"상","v":1},"경제교재-25-13":{"w":"효용극대화에서 c = 여가 = 1 − n이고 c = 7n − 2이다. 7n − 2 = 1 − n에서 n = 0.375이므로 c = 0.625다.","c":"상","v":1},"경제교재-25-14":{"w":"n = (1 + g)/(z + 1)이므로 y = zn = z(1 + g)/(z + 1)이다. dy/dg = z/(z + 1) = 7/8 = 0.875다. 정부지출 증가분보다 생산 증가가 작아 소비가 줄어든다.","c":"상","v":1},"경제교재-26-01":{"w":"초과공급이면 팔리지 않은 재고가 쌓여 다음 기에 생산이 줄고 소득이 감소한다. 이 수량조정으로 균형에 이른다.","c":"상","v":1},"경제교재-26-03":{"w":"Yd = 1,000이면 C = 900이므로 APC = 0.9다. APC = 1이면 C = Yd이므로 100 + 0.8Yd = Yd에서 Yd = 500이다.","c":"상","v":1},"경제교재-26-06":{"w":"실현된 재고증가는 생산 20 − 판매 15 = 5다. 계획된 재고증가가 2이므로 의도하지 않은 재고는 5 − 2 = 3이고 초과공급이므로 생산이 줄어든다.","c":"상","v":1},"경제교재-26-08":{"w":"S = I이고 I가 독립투자로 고정되어 있으므로 균형저축은 I와 같다. 저축 의도가 커지면 소득이 줄어 저축이 다시 원래 크기로 돌아온다.","c":"상","v":1},"경제교재-26-09":{"w":"S = −a + 0.2Y, I = 100 + 0.05Y일 때 a = 100이면 Y ≈ 1,333, S ≈ 167이다. 절대소비가 줄어 a = 50이 되면 Y = 1,000, S = 150으로 저축이 준다.","c":"상","v":1},"경제교재-26-10":{"w":"정부지출승수는 1/(1 − 0.75) = 4이고 조세승수는 −0.75/0.25 = −3이다. 이전지출승수는 조세승수와 절댓값이 같고 부호가 반대여서 +3이다.","c":"상","v":1},"경제교재-26-12":{"w":"승수는 1/(1 − 0.8×0.75) = 2.5이므로 ΔY = 100이다. 조세수입이 0.25×100 = 25 늘지만 정부지출이 40 늘어 재정수지는 40 − 25 = 15만큼 악화된다.","c":"상","v":1},"경제교재-26-14":{"w":"승수는 1/(1 − 0.8 + 0.2) = 2.5이므로 ΔY = 50이다. 수입은 0.2×50 = 10 늘어 순수출이 10 줄어든다.","c":"상","v":1},"경제교재-27-01":{"w":"내구재는 구입 시점에 소비지출이 일어나지만 효용은 긴 기간에 걸쳐 소비된다. 국민계정의 소비지출은 구입 시점에 잡힌다.","c":"상","v":1},"경제교재-27-03":{"w":"Y = 100이면 C = 110이므로 APC = 1.1, Y = 500이면 C = 350이므로 APC = 0.7이다. 한계소비성향은 소비곡선의 기울기 0.6이다.","c":"상","v":1},"경제교재-27-05":{"w":"소득이 줄어도 과거의 소비 습관 때문에 소비를 크게 줄이지 못해 단기소비곡선을 따라 움직이므로 평균소비성향이 올라간다. 소득이 늘 때는 장기소비곡선을 따른다.","c":"상","v":1},"경제교재-27-08":{"w":"Yp = 0.6×200 + 0.4×100 = 160이고 C = 0.9×160 = 144다. APC = 144/200 = 0.72다. 소득이 100으로 일정할 때의 APC 0.9보다 낮다.","c":"상","v":1},"경제교재-27-10":{"w":"일시적 인하는 임시소득만 늘려 대부분 저축된다. 영구적 인하는 항상소득을 늘려 소비와 총수요를 증가시킨다.","c":"상","v":1},"경제교재-27-12":{"w":"평생소득 12억 − 부채 3억 = 9억을 40년으로 나눠 연 2,250만 원을 소비한다. 은퇴 시 순자산은 −3억 + (6,000 − 2,250)만 원×20년 = −3억 + 7.5억 = 4.5억 원이다.","c":"상","v":1},"경제교재-27-15":{"w":"항상소득가설과 생애주기가설은 차입으로 소비를 평탄하게 만드는 것을 전제한다. 차입이 막히면 현재소득이 소비를 좌우하므로 케인즈의 절대소득가설이 설득력을 얻는다.","c":"상","v":1},"경제교재-28-01":{"w":"구주식 매입은 이미 생산된 자산의 소유권 이전이다. 신주 발행 자금으로 공장을 짓는 것은 자본재 생산을 수반하는 투자다.","c":"상","v":1},"경제교재-28-03":{"w":"고정자본소모는 0.05×1,000 = 50이다. 순투자 = 40 − 50 = −10이고 K(t+1) = 1,000 + 40 − 50 = 990이다.","c":"상","v":1},"경제교재-28-04":{"w":"10%일 때 PV = 220/1.1 + 242/1.21 = 400이어서 NPV = 20 > 0이다. 20%일 때 PV = 220/1.2 + 242/1.44 ≈ 351.4이므로 NPV < 0이다.","c":"상","v":1},"경제교재-28-06":{"w":"200(1 + m)² = 288에서 (1 + m)² = 1.44이므로 m = 0.2다. 시장이자율이 20%보다 낮을 때만 투자한다.","c":"상","v":1},"경제교재-28-08":{"w":"내부수익률은 사업 규모를 고려하지 못하고 현금흐름 모양이 다르면 순현재가치곡선이 교차해 잘못된 신호를 줄 수 있다.","c":"상","v":1},"경제교재-28-09":{"w":"MPK = (r + δ)×30이다. r = 0.04이면 3이고 K = 5, r = 0.09이면 4.5이고 K = 4.5다. 이자율이 오르면 임차비용이 커져 적정자본량이 줄어든다.","c":"상","v":1},"경제교재-28-11":{"w":"I = a·b·ΔY = 2×0.8×50 = 80이다. 근대적 가속도계수 ab = 1.6은 고전적 가속도계수 a = 2보다 작다.","c":"상","v":1},"경제교재-28-13":{"w":"주식시장 평가가 대체비용보다 크면 새 자본을 구축해 기업가치를 늘릴 수 있다. 그래서 신투자가 양(+)이다.","c":"상","v":1},"경제교재-28-16":{"w":"정보 비대칭 때문에 이자율을 올리면 역선택과 도덕적 해이가 커질 수 있어 은행은 한도를 배분한다. 따라서 투자는 자금의 이용 가능성에 좌우된다.","c":"상","v":1},"경제교재-29-01":{"w":"이것이 그레샴의 법칙이며 악화가 양화를 구축한다고 표현한다. 미시경제학의 역선택과 같은 구조다.","c":"상","v":1},"경제교재-29-03":{"w":"거주자 외화예금은 언제든지 원화로 바뀌어 유통될 수 있어 M2에 들어간다. 만기 2년 이상 상품은 유동성이 낮아 Lf에서 포함한다.","c":"상","v":1},"경제교재-29-04":{"w":"총예금창조액 = 1억/0.2 = 5억이다. 이 중 본원적 예금 1억을 뺀 4억이 순예금창조액이며 순신용승수는 4다.","c":"상","v":1},"경제교재-29-05":{"w":"m = (0.25 + 1)/(0.25 + 0.15) = 3.125이므로 M = 200 × 3.125 = 625다. 예금은 500, 현금은 125다.","c":"상","v":1},"경제교재-29-06":{"w":"총지급준비율은 0.15이므로 m = (0.4 + 1)/(0.4 + 0.15) = 1.4/0.55 ≈ 2.55다.","c":"상","v":1},"경제교재-29-08":{"w":"초과지급준비금이 이미 있으면 법정 비율이 내려도 은행이 대출을 늘릴 이유가 없다. 이때 지급준비율정책은 효과가 없다.","c":"상","v":1},"경제교재-29-10":{"w":"매입대금이 지급준비예치금으로 들어가 본원통화가 늘어난다. 채권 수요가 늘어 채권가격이 오르고 이자율은 내린다.","c":"상","v":1},"경제교재-29-12":{"w":"이자율이 오를수록 통화승수와 화폐공급이 늘어 화폐공급곡선이 우상향한다. 케인즈학파가 주장한 내용이다.","c":"상","v":1},"경제교재-29-14":{"w":"이것이 피셔효과다. 피셔방정식은 명목이자율 = 실질이자율 + 예상인플레이션율이며 고전학파와 통화주의가 강조한다.","c":"상","v":1},"경제교재-30-02":{"w":"MV = PY에서 M = (1/V)PY이고 현금잔고방정식은 M = kPY이므로 k = 1/V다.","c":"상","v":1},"경제교재-30-04":{"w":"영구채 가격은 이자/이자율이므로 이자율과 반대로 움직인다.","c":"상","v":1},"경제교재-30-06":{"w":"n* = √(rY/(2b))는 b에 대해 감소하고 평균화폐보유액 √(bY/(2r))는 b에 대해 증가한다.","c":"상","v":1},"경제교재-30-08":{"w":"대체효과는 화폐 보유를 줄이고 소득효과는 늘리는데 대체효과가 더 크면 이자율 상승이 화폐수요를 줄인다. 케인즈 모형에서는 경제 전체의 곡선만 우하향한다.","c":"상","v":1},"경제교재-30-10":{"w":"이자율이 더 내려가지 않고 오를 것으로 기대하면 채권 보유 시 자본손실이 예상되어 늘어난 유동성이 모두 화폐로 보유된다.","c":"상","v":1},"경제교재-30-12":{"w":"지급수단이 발달하면 거래비용이 낮아져 같은 소득을 지출하는 데 필요한 현금이 줄어 화폐수요가 감소하고 유통속도는 올라간다.","c":"상","v":1},"경제교재-30-14":{"w":"만기가 길수록 유동성이 낮아 투자자가 요구하는 보상이 커지므로 프리미엄도 커지고 수익률곡선은 일반적으로 우상향한다.","c":"상","v":1},"경제교재-30-15":{"w":"2년 만기 이자율은 현재 1년 이자율과 1년 뒤 예상 1년 이자율의 평균이므로 4 = (3 + x)/2에서 x = 5다.","c":"상","v":1},"경제교재-31-02":{"w":"비례세는 승수를 작게 만들어 이자율 하락에 따른 소득 증가폭이 줄어든다.","c":"상","v":1},"경제교재-31-04":{"w":"소득이 늘 때 화폐수요가 크게 늘어 균형을 유지하려면 이자율이 더 많이 올라야 하므로 LM의 기울기가 커진다.","c":"상","v":1},"경제교재-31-06":{"w":"이자율이 변해도 투자와 총수요가 변하지 않아 균형소득이 그대로이므로 IS곡선은 수직선이다.","c":"상","v":1},"경제교재-31-08":{"w":"LM곡선이 수직이므로 소득이 화폐시장에서 정해진다. IS가 오른쪽으로 이동해도 이자율만 올라 투자가 같은 크기만큼 줄어드는 완전 구축효과가 나타난다.","c":"상","v":1},"경제교재-31-10":{"w":"예상인플레이션이 오르면 같은 실질이자율에서 명목이자율이 높아 화폐수요가 줄고 LM이 이동한다. 이를 먼델-토빈효과로 설명한다.","c":"상","v":1},"경제교재-31-13":{"w":"600 − 0.5Y = 0.2Y − 100에서 0.7Y = 700이므로 Y = 1,000이다. 이를 대입하면 20r = 100이어서 r = 5다.","c":"상","v":1},"경제교재-31-14":{"w":"LM이 0.5Y = 400이어서 Y = 800으로 고정된다. IS에 대입하면 r = 20이고 G가 110이면 r = 21이다.","c":"상","v":1},"경제교재-31-16":{"w":"정책금리를 고정하면 LM곡선이 수평선이 되므로 IS가 이동해도 이자율은 그대로이고 소득만 늘어난다.","c":"상","v":1},"경제교재-32-01":{"w":"국공채 발행대금은 중앙은행 창구 밖에서 다시 정부지출로 쓰이므로 본원통화가 변하지 않는다.","c":"상","v":1},"경제교재-32-03":{"w":"총수요와 소득이 더 줄고 조세수입이 다시 감소해 재정적자가 해소되지 않는다. 이를 정책함정이라 한다.","c":"상","v":1},"경제교재-32-05":{"w":"투자가 이자율에 민감하면 IS가 완만해 이자율이 조금만 올라도 투자가 크게 줄어 소득 증가분이 많이 상쇄된다.","c":"상","v":1},"경제교재-32-07":{"w":"소득 증가가 가속도원리로 투자를 늘려 IS의 이동 폭을 키우고, 이자율 상승으로 투자가 줄어드는 효과를 앞지르기 때문이다.","c":"상","v":1},"경제교재-32-09":{"w":"가계는 감세분을 미래 증세에 대비해 저축하므로 민간저축이 정부저축 감소분만큼 늘어나 이자율도 변하지 않는다.","c":"상","v":1},"경제교재-32-12":{"w":"LM이 오른쪽 아래로 이동해 이자율이 내리면 투자가 늘어 소득이 증가한다.","c":"상","v":1},"경제교재-32-14":{"w":"처음 균형은 Y = 8, r = 6이다. 새 균형도 LM 위의 점이므로 Y = 10을 대입하면 r = 2 + 5 = 7이다.","c":"상","v":1},"경제교재-32-16":{"w":"승수가 1/(1 − 0.8) = 5이고 이자율이 고정이면 소득이 100 늘어난다. 이자율이 같을 때 화폐수요 증가분은 소득 증가분과 같으므로 통화량을 100 늘려야 한다.","c":"상","v":1},"경제교재-33-02":{"w":"물가 하락으로 LM이 오른쪽 아래로 이동해 이자율이 낮아지고 투자수요가 늘어 총수요가 증가한다. 이를 케인즈효과라 한다.","c":"상","v":1},"경제교재-33-04":{"w":"탄력성이 크면 IS가 완만해 같은 이자율 하락에 투자가 많이 늘어 물가 하락에 따른 총수요 증가폭이 커진다.","c":"상","v":1},"경제교재-33-06":{"w":"PY = M/k에서 총지출이 일정하고 재정정책은 완전 구축효과로 총수요에 영향을 못 준다. 통화량이 변할 때만 이동한다.","c":"상","v":1},"경제교재-33-08":{"w":"물가가 내릴 때 실질자산 증가로 소비가 늘어 IS가 오른쪽으로 이동하므로 이자율 경로가 막혀도 총수요가 늘어난다.","c":"상","v":1},"경제교재-33-10":{"w":"유휴설비와 만성적 실업이 있어 주어진 물가에서 공급이 얼마든지 늘 수 있고 완전고용소득을 넘으면 수직이 된다.","c":"상","v":1},"경제교재-33-12":{"w":"합리적 기대에서 P = Pe가 성립해 단기 총공급곡선이 수직이 되기 때문이다. 이것이 정책무력성의 정리다.","c":"상","v":1},"경제교재-33-14":{"w":"명목임금이 계약으로 고정되어 있으면 물가 상승이 실질임금을 낮춰 기업이 고용을 늘린다. 실질임금은 경기역행적이다.","c":"상","v":1},"경제교재-33-15":{"w":"300 + 12,600/P = 450 + P를 풀면 P² + 150P − 12,600 = 0이므로 P = 60이다. Y = 450 + 60 = 510이다.","c":"상","v":1},"경제교재-34-02":{"w":"구직단념자는 비경제활동인구로 옮겨 가므로 분자의 실업자와 분모의 경제활동인구가 함께 줄어 실업률이 낮아진다.","c":"상","v":1},"경제교재-34-04":{"w":"무급가족종사자는 수입이 직접 오지 않더라도 주당 18시간 이상 일하면 취업자이고 그보다 적게 일하면 취업자가 아니다.","c":"상","v":1},"경제교재-34-06":{"w":"마찰적 실업은 직장을 옮기는 과정에서 생기는 자발적 실업이고 구조적 실업과 경기적 실업은 현재 임금에서 일자리를 얻지 못하는 비자발적 실업이다.","c":"상","v":1},"경제교재-34-08":{"w":"자연실업률은 s/(s + f) = 0.02/(0.02 + 0.14) = 0.125다.","c":"상","v":1},"경제교재-34-11":{"w":"물가가 내려 노동수요곡선이 왼쪽으로 이동해도 명목임금이 내리지 않으면 실질임금이 올라 비자발적 실업이 생기며 확대재정정책이 대책이 된다.","c":"상","v":1},"경제교재-34-13":{"w":"높은 임금은 태만과 이직을 줄이고 우수한 인력을 끌어들이므로 임금을 내리지 않고 그 결과 실업이 남는다.","c":"상","v":1},"경제교재-34-15":{"w":"장기 실업이 낙인효과와 기술 노후화를 낳고 내부자가 임금을 올려 실업이 오래 남으므로 자연실업률가설이 성립하지 않는다.","c":"상","v":1},"경제교재-34-16":{"w":"경제활동인구는 3,000 × 0.6 = 1,800만 명이고 실업자는 1,800 × 0.03 = 54만 명이므로 취업자는 1,800 − 54 = 1,746만 명이다.","c":"상","v":1},"경제교재-35-02":{"w":"가격이 오른 상품의 소비는 줄어드는데 가중치는 기준연도 그대로여서 물가상승이 부풀려진다. 신제품과 품질 개선도 반영하지 못한다.","c":"상","v":1},"경제교재-35-04":{"w":"생산자물가가 먼저 오르고 생산자가 이를 상품가격에 반영해 소비자물가로 파급되는 데는 시차가 있다.","c":"상","v":1},"경제교재-35-06":{"w":"임금 인상률을 노동생산성 증가율에 연결하는 생산성임금제나 임금 가이드라인을 쓰며 장기적 효과는 크지 않다.","c":"상","v":1},"경제교재-35-07":{"w":"경제성장률을 넘는 화폐공급 증가가 물가상승률로 나타나므로 준칙에 따른 통화 공급을 주장한다.","c":"상","v":1},"경제교재-35-09":{"w":"명목이자율 = 실질이자율 + 예상인플레이션율이므로 인플레이션이 명목이자율에만 반영된다.","c":"상","v":1},"경제교재-35-11":{"w":"예상인플레이션율 변화보다 명목이자율 변화가 작아 실질이자율이 하락하고 투자와 총수요가 늘어난다.","c":"상","v":1},"경제교재-35-13":{"w":"명목소득이 늘면 더 높은 세율 구간이 적용되어 조세부담이 소득 증가율보다 크게 늘어난다.","c":"상","v":1},"경제교재-35-15":{"w":"1만 원권 제조비용이 100원이면 나머지 9,900원이 정부의 화폐발행이득이고 화폐 보유자가 그만큼 세금을 낸 효과가 있다.","c":"상","v":1},"경제교재-36-02":{"w":"총수요 증가로 소득이 늘어 실업률은 내리고 물가가 올라 인플레이션율은 오르므로 곡선 위의 이동이다.","c":"상","v":1},"경제교재-36-04":{"w":"소득이 줄어 실업률이 오르고 물가가 올라 인플레이션율도 올라 같은 실업률에서 인플레이션이 높은 곡선이 된다.","c":"상","v":1},"경제교재-36-06":{"w":"장기에는 예상인플레이션이 실제와 같아져 실업률이 자연실업률로 돌아가므로 인플레이션과 실업 사이에 상충관계가 없다.","c":"상","v":1},"경제교재-36-08":{"w":"자연국민소득이 늘고 자연실업률이 낮아지기 때문이다.","c":"상","v":1},"경제교재-36-10":{"w":"민간이 정책을 미리 알고 기대인플레이션을 올리므로 π = πe가 되어 실업률이 자연실업률에 머문다.","c":"상","v":1},"경제교재-36-12":{"w":"오쿤의 법칙으로 실업률 상승을 GDP 감소로 바꾸고 이를 인플레이션 하락폭으로 나눠 구한다.","c":"상","v":1},"경제교재-36-14":{"w":"Δπ = −0.4Δu에서 Δu = −Δπ/0.4 = 2/0.4 = 5%p다.","c":"상","v":1},"경제교재-36-15":{"w":"Δπ = −3이면 u − uN = 1.5이고 총생산 갭은 −2 × 1.5 = −3%다.","c":"상","v":1},"경제교재-37-01":{"w":"가격이 완전신축적이어서 노동시장이 항상 균형이고 그 고용량이 총생산함수와 결합해 소득을 정한다. 총수요는 물가만 정한다.","c":"상","v":1},"경제교재-37-05":{"w":"IS는 완만하고 LM은 가파르다. 재정지출이 이자율을 크게 올려 민간투자를 많이 밀어내기 때문이다.","c":"상","v":1},"경제교재-37-07":{"w":"통화량 조절은 통화당국의 결정만으로 가능하지만 재정정책은 예산 편성과 국회 동의 같은 입법 과정이 필요하다.","c":"상","v":1},"경제교재-37-08":{"w":"화폐수량설을 증가율로 쓰면 통화증가율 + 유통속도 증가율 = 물가상승률 + 실질소득 증가율이다. 유통속도 증가율과 물가상승률이 0이면 통화증가율이 실질소득 증가율과 같다.","c":"상","v":1},"경제교재-37-09":{"w":"장기에는 적응적 기대의 오차가 없어져 실제물가와 예상물가가 같아지므로 두 학파 모두 장기에는 정책이 무력하다고 인정한다. 차이는 단기 효과와 조정 속도에 있다.","c":"상","v":1},"경제교재-37-11":{"w":"케인즈학파의 계량모형은 정책이 바뀐 뒤에도 방정식의 계수가 일정하다고 가정했다. 루카스는 미시적 행동분석 위에 거시모형을 세워야 한다고 보았다.","c":"상","v":1},"경제교재-37-13":{"w":"상대가 인하하면 인하(50)가 유지(40)보다 낫고 상대가 유지하면 유지(30)가 인하(10)보다 낫다. 서로 상대가 유지하리라 예상하면 (유지, 유지)에 갇혀 가격이 경직된다.","c":"상","v":1},"경제교재-37-15":{"w":"투자와 소비 증가는 총수요를 늘리고, 노동공급과 자본축적 증가는 총공급을 늘린다. 공급 증가가 더 크다고 보기 때문에 스태그플레이션 해결책으로 내세웠다.","c":"상","v":1},"경제교재-38-01":{"w":"생산활동과 같은 방향으로 움직이면 경기순응적, 반대로 움직이면 경기역행적이다. 경기가 나빠지면 실업은 늘어난다.","c":"상","v":1},"경제교재-38-04":{"w":"저점에서 정점까지가 확장국면이고 정점에서 저점까지가 수축국면이다.","c":"상","v":1},"경제교재-38-05":{"w":"쿠즈네츠파동은 건축과 부동산 경기, 콘트라티에프파동은 기술혁신·신자원 개발 같은 장기 요인과 연결된다.","c":"상","v":1},"경제교재-38-07":{"w":"사무엘슨이 케인즈이론을 동태화한 모형이며 경기변동의 원인을 총수요 측면에서 찾는다.","c":"상","v":1},"경제교재-38-09":{"w":"총체적 충격과 개별적 충격을 구별하지 못하기 때문이다. 상대가격이 올랐다고 믿어야 생산을 늘릴 유인이 생긴다.","c":"상","v":1},"경제교재-38-11":{"w":"생산함수가 위로 이동해 노동의 한계생산이 커지면 노동수요가 늘어 고용과 실질임금이 오른다. 노동공급이 탄력적이어서 고용이 더 크게 반응한다.","c":"상","v":1},"경제교재-38-13":{"w":"실질이자율이 오르면 기간 간 상대임금 W1/[W2/(1+r)]이 올라 현재 노동이 더 유리해진다. 충격이 일시적일수록 대체 폭이 커진다.","c":"상","v":1},"경제교재-38-15":{"w":"경기변동을 시장의 불균형 현상으로 보기 때문에 정부가 개입해 해소할 수 있다.","c":"상","v":1},"경제교재-39-01":{"w":"황금률 조건 f'(k) = 1/√k = 0.2에서 k = 25이고 y = 10이다. 균제상태 소비는 y − δk = 10 − 0.2 × 25 = 5다.","c":"상","v":1},"경제교재-39-03":{"w":"1인당 자본과 1인당 생산이 일정하므로 총자본과 총생산이 인구증가율로 늘어난다. 이것이 솔로우 모형에서 노동과 자본이 모두 완전고용되는 균형성장조건이다.","c":"상","v":1},"경제교재-39-06":{"w":"유효노동 L×E는 2%로 늘고 K도 Y도 2%로 늘어난다. 노동자 수는 3% 줄므로 K/L은 2% − (−3%) = 5%로 늘어난다.","c":"상","v":1},"경제교재-39-08":{"w":"해로드-도마의 레온티에프 생산함수에서는 자본계수가 고정이라 적정성장률이 정해지고 솔로우의 콥-더글라스 생산함수에서는 자본계수가 가변이라 조정이 일어난다.","c":"상","v":1},"경제교재-39-10":{"w":"0.2√k = 0.2k에서 k = 1이다. 황금률은 0.5/√k = 0.2에서 k = 6.25이고 황금률 저축률은 자본소득분배율 0.5이므로 저축률을 올려야 한다.","c":"상","v":1},"경제교재-39-13":{"w":"10% = 7% + (1/3)gk에서 gk = 9%다.","c":"상","v":1},"경제교재-39-14":{"w":"한번 쓴다고 소멸하지 않아 비경합적이고 지적재산권으로 배제가 가능하다. 연구개발의 긍정적 외부효과가 지속 성장의 근거가 된다.","c":"상","v":1},"경제교재-40-01":{"w":"교역의 이익은 절대생산비가 아니라 기회비용의 차이에서 나온다. 모든 재화에 절대우위인 나라도 상대적으로 덜 불리한 재화에 비교우위가 있다.","c":"상","v":1},"경제교재-40-03":{"w":"철강 1톤의 기회비용은 A국이 자동차 2대, B국이 자동차 1/3대이므로 B국이 철강에 비교우위가 있다. 교역조건이 A국의 기회비용(2대)과 같을 때 B국이 이득을 최대로 가져간다.","c":"상","v":1},"경제교재-40-04":{"w":"A는 물고기를 만들어 팔고 B는 커피를 만들어 판다. 교환비율이 두 기회비용 사이(1과 2 사이)이면 양쪽 모두 직접 만드는 것보다 이익이다.","c":"상","v":1},"경제교재-40-05":{"w":"A국은 X재 100을 만들어 50을 수출해 Y 75를 얻고 소비는 (X 50, Y 75)로 무역 전 (50, 50)보다 Y가 25 많다. B국은 Y 200을 만들어 75를 수출하고 X 50을 받아 (X 50, Y 125)를 소비하므로 무역 전 (50, 100)보다 Y가 25 많다.","c":"상","v":1},"경제교재-40-08":{"w":"노동풍부국은 노동집약재를 수출하며 그 재화의 상대가격이 오르면 노동수요가 늘어 임금이 오르고 자본의 실질소득은 준다. 풍부한 요소는 이득을 보고 희소한 요소는 손해를 본다.","c":"상","v":1},"경제교재-40-10":{"w":"수입경쟁산업의 생산이 늘면서 그 산업이 집약적으로 쓰는 요소의 수요가 늘어 그 요소의 가격이 오른다. 관세는 이 요소 소유자에게 유리하게 소득을 재분배한다.","c":"상","v":1},"경제교재-40-12":{"w":"같은 산업 안에서 차별화된 상품을 서로 주고받으므로 생산요소 수요 구성이 크게 바뀌지 않는다. 시장이 커져 평균비용이 내리고 소비자는 다양한 상품을 더 싸게 산다.","c":"상","v":1},"경제교재-40-15":{"w":"교역조건은 수출단가지수와 수입단가지수의 비율이라 수출품의 국제가격 하락이 곧 악화다. 그러나 수출량이 늘고 수입량이 줄면 경상수지는 개선될 수 있다.","c":"상","v":1},"경제교재-41-01":{"w":"소국은 관세를 매겨도 국제가격이 변하지 않아 교역조건을 개선할 수 없고 생산·소비 왜곡에 따른 후생손실만 생긴다.","c":"상","v":1},"경제교재-41-03":{"w":"생산·소비 왜곡으로 사라지는 두 삼각형은 후생을 줄이고 수입품 국제가격 하락에 따른 교역조건 이득은 후생을 늘린다. 어느 쪽이 큰지는 정해지지 않는다.","c":"상","v":1},"경제교재-41-04":{"w":"국내가격 15에서 공급은 100에서 125로 25 늘고 수요는 300에서 225로 75 줄어 수입은 200에서 100이 된다. 손실은 ½ × 5 × 25 + ½ × 5 × 75 = 62.5 + 187.5 = 250이다.","c":"상","v":1},"경제교재-41-06":{"w":"4,000 − 100P − (500 + 50P) = 500에서 P = 20이다. 할당지대는 국내가격 상승분 10 × 수입량 500 = 5,000이다.","c":"상","v":1},"경제교재-41-07":{"w":"소비자잉여와 생산자잉여의 변화는 관세와 같지만 사각형의 귀속이 달라진다. 정부가 돈을 받고 면허를 팔면 재정수입이 된다.","c":"상","v":1},"경제교재-41-10":{"w":"관세 전 부가가치는 200 − 100 = 100이다. 관세 후 최종재 240, 투입재 110이므로 부가가치는 130이고 실효보호율은 30 ÷ 100 = 30%다.","c":"상","v":1},"경제교재-41-12":{"w":"수입재에 대한 한계소비성향이 낮고 상대국의 수입수요가 매우 비탄력적일 때 일어난다. 이때 수입대체산업은 오히려 불리해진다.","c":"상","v":1},"경제교재-41-13":{"w":"관세가 철폐되어 가맹국 사이에 새 무역이 생기고 공급원이 비효율적인 곳에서 효율적인 곳으로 옮겨져 세계 자원배분의 효율성이 높아진다.","c":"상","v":1},"경제교재-41-15":{"w":"관세동맹은 역외에 공동관세를 매겨 이 문제가 없다. 자유무역지대는 원산지규정으로 이를 막는다.","c":"상","v":1},"경제교재-42-02":{"w":"5% + 6% − 4% = 7%다. 실질환율이 오르면 한국 상품이 외국 상품보다 상대적으로 싸진 것이다.","c":"상","v":1},"경제교재-42-04":{"w":"4% − 6% = −2%이므로 1,200원의 2%인 24원이 내려 1,176원이다.","c":"상","v":1},"경제교재-42-05":{"w":"빅맥환율이 실제환율보다 낮으면 자국통화가 저평가된 것이다. 환율이 구매력평가 수준으로 내려가면 원화가 절상된다.","c":"상","v":1},"경제교재-42-07":{"w":"i − i* = (E^e − E)/E에서 0.005 = (E^e − 1,200)/1,200이므로 E^e = 1,206이다.","c":"상","v":1},"경제교재-42-08":{"w":"(E^e − E)/E = 5% − 6% = −1%다. 환율 변화율이 −1% = 3% − π*이므로 π* = 4%이고 두 나라의 실질이자율은 모두 2%다.","c":"상","v":1},"경제교재-42-10":{"w":"e(1 + i) = f(1 + i*)에서 f = 105 × 1.10 ÷ 1.05 = 110이다.","c":"상","v":1},"경제교재-42-11":{"w":"(5% − 2%) − (1% − 3%) = 3% + 2% = 5%다. 자국의 통화 공급이 상대적으로 늘고 실질화폐수요가 상대적으로 줄어 자국 통화가치가 떨어진다.","c":"상","v":1},"경제교재-42-13":{"w":"고정환율제에서 자본이동이 자유로우면 통화정책의 독립성이 사라진다는 것이 불가능한 삼위일체다.","c":"상","v":1},"경제교재-42-15":{"w":"물가가 경직적이면 통화 증가가 이자율을 즉시 낮추어 자본이 유출되고 환율이 급등한다. 이후 물가가 오르고 이자율이 되돌아오면서 환율은 장기 균형으로 수렴한다.","c":"상","v":1},"경제교재-43-01":{"w":"경상수지는 상품·서비스·본원소득·이전소득수지의 합 60 − 20 + 5 − 10 = 35다. 직접투자는 금융계정이라 포함하지 않는다.","c":"상","v":1},"경제교재-43-03":{"w":"복식부기 원리에 따라 모든 대외거래는 차변과 대변에 같은 금액으로 기록되므로 이론상 합이 0이다. 실제로는 통계 시점과 평가 차이로 오차 및 누락이 생긴다.","c":"상","v":1},"경제교재-43-05":{"w":"국민저축 = 민간저축 + 정부저축 = 20% − 2% = 18%이고 경상수지 = 국민저축 − 투자 = 18% − 19% = −1%다.","c":"상","v":1},"경제교재-43-07":{"w":"환율이 오르면 달러표시 수출가격은 내리고 수입품의 원화가격은 오른다. 수출입 물량이 충분히 반응해 수출액에서 수입액을 뺀 값이 늘어나야 하며 그 조건이 두 탄력성의 합이 1을 넘는 것이다.","c":"상","v":1},"경제교재-43-09":{"w":"환율 하락 압력을 막으려고 외환을 사면 그 대금만큼 본원통화가 늘어난다. 먼델-플레밍 모형은 불태화정책을 쓰지 않는다고 가정한다.","c":"상","v":1},"경제교재-43-10":{"w":"승수는 1 ÷ (1 − 0.6 + 0.1) = 2이고 소득은 80 늘며 수입은 0.1 × 80 = 8 늘어 순수출이 8 줄어든다.","c":"상","v":1},"경제교재-43-12":{"w":"통화 확대로 이자율이 내리려 하면 자본이 빠져나가 통화가치가 절하된다. 순수출이 늘어 IS도 오른쪽으로 이동해 소득이 증가한다.","c":"상","v":1},"경제교재-43-16":{"w":"통화 확대로 이자율이 내려가면 자본이 빠져나가 환율이 오르려 한다. 중앙은행이 외환을 팔아 통화량을 다시 줄이므로 LM이 제자리로 돌아온다.","c":"상","v":1}};
